  background: rgb(125, 125, 125); 
  box-shadow: 5px 5px 10px rgb(125, 125, 125), -5px -5px 10px rgb(125, 125, 125), -5px 5px 10px rgb(125, 125, 125), 5px -5px 10px rgb(125, 125, 125);
  img {
    width: 100%; 
    height: 100%; 
    min-width: 50px;
    min-height: 50px;
  }
  .text {
    color: #000;
    font-weight: bold;
    text-shadow: 1px 1px 0 rgba(255, 255, 255, 0.3), -1px -1px 0 rgba(255, 255, 255, 0.3), 1px -1px 0 rgba(255, 255, 255, 0.3), -1px 1px 0 rgba(255, 255, 255, 0.3);
    width: 100%;
    text-align: center;
    padding: 5px 20px;
    white-space: pre-line;
    font-size: max(14px, calc(100vh / 15)); /* WCAG minimum floor; original scaled with viewport height */
    span {
      padding: 3px;
      background: rgba(255, 255, 255, 0.7);
      box-shadow: 10px 0 0 rgba(255, 255, 255, 0.7), -10px 0 0 rgba(255, 255, 255, 0.7);
    }
  }
  &.stretch {
    .text {
      position: absolute;
      top: 0;
    }
  }
  .exclude {
    &:before, &:after {
      position: absolute;
      content: '';
      background: rgba(255, 0, 0, 0.7);
      display: block;
      width: 100%;
      height: 30px;
      -webkit-transform: rotate(-45deg);
      transform: rotate(-45deg);
      left: 0;
      right: 0;
      top: 0;
      bottom: 0;
      margin: auto;
    }
    &:after {
      -webkit-transform: rotate(45deg);  
      transform: rotate(45deg);    
    }
  }
}

