/* ── Hamburger menu for board page (small screens) ──────── */
.la-board-hamburger {
  display: none;
  width: 42px;
  height: 42px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(255, 255, 255, 0.1);
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  cursor: pointer;
  transition: background 0.15s ease;
}
.la-board-hamburger:hover {
  background: rgba(255, 255, 255, 0.2);
}
.la-board-hamburger__bar {
  width: 18px;
  height: 2px;
  background: #fff;
  border-radius: 2px;
  transition: transform 0.2s ease;
}

#normal_mode {
  position: relative;
}

/* Wrapper around hamburger button + dropdown — gives the dropdown
   a tight positioning context so it anchors directly below the
   hamburger button rather than #normal_mode's full-width container
   (which let the menu drop down from the far-right of the header).
   Inline-block so the wrapper hugs the button width. */
.la-board-hamburger-wrap {
  position: relative;
  display: inline-block;
  vertical-align: middle;
}

.la-board-mobile-menu {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  background: #fff;
  border-radius: 16px;
  box-shadow: 0 8px 32px rgba($la-navy, 0.18), 0 2px 8px rgba(0, 0, 0, 0.06);
  border: 1px solid rgba($la-navy, 0.08);
  padding: 8px;
  /* Bumped from 200 to 2000 so the dropdown clears every interactive
     layer on board-alt — the speak grid + board cells were rendering
     ON TOP of the menu at z-index 200 because the board surface
     itself paints into a higher stacking context. 2000 stays below
     true overlay layers (modal-backdrop ~1040, picker 901/900) so
     real modals still cover it correctly. */
  z-index: 2000;
  min-width: 240px;
  animation: la-board-menu-fade-in 0.15s ease;
  /* Cap the menu height to the available viewport space and scroll
     internally so users on short viewports can reach Exit Boards at
     the bottom. The 16px buffer pads against the page edge. */
  max-height: calc(100vh - 100px);
  overflow-y: auto;
}
@keyframes la-board-menu-fade-in {
  from { opacity: 0; transform: translateY(-6px); }
  to { opacity: 1; transform: translateY(0); }
}
.la-board-mobile-menu__item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  border-radius: 10px;
  font-size: 15px;
  font-weight: 500;
  color: $brand-charcoal-dark;
  cursor: pointer;
  border: none;
  background: none;
  width: 100%;
  text-align: left;
  transition: background 0.12s ease;
}
.la-board-mobile-menu__item:hover {
  background: rgba($brand-verdigris, 0.06);
}
.la-board-mobile-menu__item .glyphicon,
.la-board-mobile-menu__item img {
  font-size: 14px;
  color: $brand-slate-gray;
  flex-shrink: 0;
}
.la-board-mobile-menu__divider {
  height: 1px;
  background: rgba($la-navy, 0.08);
  margin: 4px 8px;
}
.la-board-mobile-menu__item--exit {
  color: #fff;
  background: $brand-charcoal-blue;
  border-radius: 10px;
  margin-top: 4px;
}
.la-board-mobile-menu__item--exit:hover {
  background: $brand-charcoal-dark;
}
.la-board-mobile-menu__item--exit .glyphicon {
  color: #fff !important;
}

/* ── Board page responsive: collapse action buttons into hamburger ──
   Breakpoint bumped from 1024px → 1500px so the hamburger collapse
   kicks in earlier and the right-side action cluster on board-alt
   normal mode never overruns the header. Affects both the classic
   board view (.nav-header__board-bar) and board-alt; the hamburger
   menu items themselves are unchanged. */
@media (max-width: 1500px) {
  /* Show hamburger */
  #inner_header .la-board-hamburger {
    display: flex !important;
  }

  /* Hide Exit Boards button (it's in the hamburger menu now) */
  #inner_header #board_done {
    display: none !important;
  }

  /* Hide Exit Boards and all action buttons — use class on #normal_mode children */
  .nav-header__board-bar #board_done {
    display: none !important;
  }
  .nav-header__board-bar #normal_mode .btn,
  .nav-header__board-bar #normal_mode .btn-group,
  .nav-header__board-bar #normal_mode .dropdown,
  .nav-header__board-bar #normal_mode a.btn,
  .nav-header__board-bar #normal_mode span.btn {
    display: none !important;
  }

  /* Keep visible: back button (has glyphicon-arrow-left) */
  .nav-header__board-bar #normal_mode a.btn:has(.glyphicon-arrow-left) {
    display: inline-flex !important;
  }
  /* Keep visible: speak mode button (#speak_mode) */
  .nav-header__board-bar #normal_mode #speak_mode {
    display: inline-flex !important;
    margin-left: 8px !important;

  }
  .nav-header__board-bar #normal_mode .btn-group:has(#speak_mode) {
    display: inline-flex !important;
  }
  .nav-header__board-bar #normal_mode .btn-group:has(#speak_mode) .btn {
    display: inline-flex !important;
  }
  /* Keep visible: hamburger */
  .nav-header__board-bar #normal_mode .la-board-hamburger {
    display: flex !important;
  }

  /* Shrink board ID text */
  #board_id {
    font-size: 14px !important;
  }

  /* Reduce header padding */
  .nav-header__board-bar {
    gap: 4px !important;

  }
  header #normal_mode .btn {
    padding: 6px 10px !important;

    font-size: 14px !important;

    height: 36px;
  }
}

@media (max-width: 640px) {
  #board_id {
    font-size: 14px !important;
  }
  header #normal_mode .btn {
    padding: 5px 8px;
    font-size: 14px;
    height: 34px;
  }
  .la-board-hamburger {
    width: 36px;
    height: 36px;
  }
  .la-board-hamburger__bar {
    width: 16px;
  }

  /* Reduce board container margins */
  .board {
    margin: -5px -10px;
  }
}

@media (max-width: 480px) {
  #board_id {
    font-size: 14px !important;
  }
  #board_id .user-name {
    display: none;
  }
  header #normal_mode .btn {
    padding: 4px 6px;
    font-size: 14px;
    height: 32px;
  }
  .la-board-hamburger {
    width: 32px;
    height: 32px;
    gap: 3px;
  }
  .la-board-hamburger__bar {
    width: 14px;
  }

  /* Minimal board margins */
  .board {
    margin: -2px -4px;
  }
}

