/* Scanning highlight overlay panels — subtle dim */
.highlight {
  background: rgba(0, 0, 0, 0.35);
}
/* Scanning highlight box — modern high-contrast border */
.highlight.box {
  border: 5px solid $brand-verdigris;
  border-radius: 12px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  box-shadow:
    0 0 0 3px rgba(44, 183, 176, 0.3),
    0 0 20px rgba(44, 183, 176, 0.25),
    0 0 40px rgba(44, 183, 176, 0.10);
  animation: scan-glow 1.2s ease-in-out infinite alternate;
  &.secondary {
    border-color: $brand-blue-grey;
    box-shadow:
      0 0 0 3px rgba($brand-blue-grey, 0.3),
      0 0 20px rgba($brand-blue-grey, 0.25);
    animation: scan-glow-secondary 1.2s ease-in-out infinite alternate;
  }
  &.pending {
    animation: scan-pulse 0.4s ease-in-out infinite;
  }
  &.inner {
    border: 3px solid #fff;
    border-radius: 10px;
    box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.5);
    animation: none;
    .highlight_icon {
      font-size: 50px;
      background: rgba(255, 255, 255, 0.9);
      border-radius: 10px;
      padding: 10px 5px 5px;
      opacity: 0.8;
      display: inline-block;
    }
    &.secondary {
      border-color: #b969ff;
      box-shadow: 0 0 0 2px rgba(185, 105, 255, 0.3);
    }
  }
}
@keyframes scan-glow {
  from { box-shadow: 0 0 0 3px rgba(44, 183, 176, 0.3), 0 0 20px rgba(44, 183, 176, 0.25), 0 0 40px rgba(44, 183, 176, 0.10); }
  to   { box-shadow: 0 0 0 5px rgba(44, 183, 176, 0.4), 0 0 30px rgba(44, 183, 176, 0.35), 0 0 50px rgba(44, 183, 176, 0.15); }
}
@keyframes scan-glow-secondary {
  from { box-shadow: 0 0 0 3px rgba($brand-blue-grey, 0.3), 0 0 20px rgba($brand-blue-grey, 0.25); }
  to   { box-shadow: 0 0 0 5px rgba($brand-blue-grey, 0.4), 0 0 30px rgba($brand-blue-grey, 0.35); }
}
@keyframes scan-pulse {
  0%, 100% { transform: scale(1); opacity: 1; }
  50%      { transform: scale(1.02); opacity: 0.9; }
}
