/* ── Setup core page: Bubble collage ── */
.setup-core-bubbles {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 12px 16px;
  padding: 24px 32px;
  border-radius: 20px;
  background:
    radial-gradient(ellipse at 25% 35%, rgba($brand-verdigris, 0.06), transparent 55%),
    radial-gradient(ellipse at 75% 65%, rgba($brand-blue-grey, 0.07), transparent 55%),
    rgba(244, 243, 240, 0.6);
}
.setup-core-bubbles__img {
  height: auto;
  width: auto;
  max-height: 75px;
  max-width: 100%;
  object-fit: contain;
  flex-shrink: 0;
  filter: drop-shadow(0 2px 6px rgba($la-navy, 0.10));
  will-change: transform, opacity;
  transition: transform 0.25s ease, filter 0.25s ease;
  opacity: 0;
  transform: translateY(-40px) scale(0.6);
}
.setup-core-bubbles__img.setup-core-bubbles__img--loaded {
  animation: setup-bubble-bounce 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}
@media (prefers-reduced-motion: reduce) {
  .setup-core-bubbles__img.setup-core-bubbles__img--loaded {
    animation: none;
    opacity: 1;
    transform: none;
  }
}
.setup-core-bubbles__img:hover {
  transform: scale(1.08) translateY(-3px) !important;
  filter: drop-shadow(0 5px 14px rgba($la-navy, 0.16));
}
@media (prefers-reduced-motion: reduce) {
  .setup-core-bubbles__img:hover { transform: none !important; }
}
// Fast stagger: 20 images in ~0.6s total
@for $i from 1 through 20 {
  .setup-core-bubbles__img--loaded:nth-child(#{$i}) {
    animation-delay: #{($i - 1) * 0.03}s;
  }
}

@keyframes setup-bubble-bounce {
  0%   { opacity: 0; transform: translateY(-40px) scale(0.6); }
  45%  { opacity: 1; transform: translateY(5px) scale(1.04); }
  65%  { transform: translateY(-3px) scale(0.97); }
  80%  { transform: translateY(1px) scale(1.01); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}

/* ── Loading spinner ── */
