// Setup card content: match modern-dashboard typography, buttons, and inner content
.md-card--setup {
  margin-bottom: 3rem;
  font-size: 16px;
  color: var(--md-ink);
  min-width: 0;

  /* Content wrapper (ember component root) */
  > div {
    min-width: 0;
  }

  /* Headings: uniform size across all setup pages.
     Uses !important to override the global h2 { font-size: 25px !important } at line 2589. */
  h1, h2, h3, h4 {
    margin: 0 0 1rem !important;
    font-size: 20px !important;
    font-weight: 900 !important;
    letter-spacing: -0.2px !important;
    color: var(--md-ink) !important;
    line-height: 1.3 !important;
  }

  p {
    margin-bottom: 1.25rem;
    line-height: 1.55;
    color: var(--md-ink);
  }
  .setup-symbols-subheader {
    font-size: 2.336rem; /* 20% smaller than 2.92rem for "Set Starter Preferences" */
    font-weight: 600;
    line-height: 1.5;
    color: var(--md-ink);
    margin: 0 0 0.75rem;
  }
  .prompt {
    font-size: 17px;
    line-height: 1.55;
    color: var(--md-ink);
    margin-bottom: 1.5rem;
  }

  /* Usage step: inherit global checklist styles (defined at root below) */
  /* Setup done page — modern action buttons */
  .setup-done-actions {
    display: flex;
    flex-direction: column;
    gap: 10px;
    max-width: 480px;
    margin-top: 1.5rem;
  }
  .setup-done-actions__btn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
