/* Applied in: Button stash hover overlay during edit mode */
#stash_hover {
  position: absolute;
  cursor: pointer;
  left: -100px;
  z-index: 3;
  width: 162px;
  /* Was a fixed 41px with overflow:hidden, which clipped the 27px
     icon + two-line label. Auto height + visible overflow lets the
     box grow to fit its content. Positioning (left/margin-top) is
     left exactly as it was so it stays anchored to the button. */
  height: auto;
  font-size: 14px;
  padding: 0px;
  margin-top: -41px;
  margin-left: 0px;
  background: #fff;
  visibility: hidden;
  border: 1px solid #ccc;
  border-radius: 3px;
  opacity: 0.0;
  overflow: visible;
  transition: visibility 0s 0.9s linear, opacity 0.15s ease-in 0.9s;
  -webkit-transition: visibility 0s 0.9s linear, opacity 0.15s ease-in 0.9s;
  &.on_button {
    visibility: visible;
    opacity: 1.0;
  }
  .option {
    float: left;
    width: 80px;
    padding: 5px;
    box-sizing: border-box;
    &:hover {
      background: #eee;
    }
    &:last-child {
      border-left: 1px solid #ccc;
      padding-left: 10px;
    }
  }
  .glyphicon {
    float: left;
    font-size: 27px;
    margin-right: 5px;
  }
}

