/* Full-bleed #board_bg is position:absolute (see board/index.hbs + bg_style). Some browsers paint
   it above grid buttons. Do NOT set position:relative on .button_row — fast_html uses position:absolute
   on buttons with top/left computed for .board as containing block; relative on .button_row would
   re-parent those coordinates and hide controls (obf/eval-*, all eval steps). */
.board.eval_mode,
.board:has(#board_bg) {
  isolation: isolate;
}
.board.eval_mode #board_bg,
.board:has(#board_bg) #board_bg {
  z-index: 0 !important;
  pointer-events: none;
}
.board.eval_mode #board_canvas,
.board:has(#board_bg) #board_canvas {
  position: relative;
  z-index: 10 !important;
  pointer-events: auto;
}
.board.eval_mode a.button,
.board.eval_mode a[data-id],
.board:has(#board_bg) a.button,
.board:has(#board_bg) a[data-id] {
  z-index: 10 !important;
  pointer-events: auto;
}
.board.finding_target .button, .board.finding_target .button input {
  cursor: copy;
}
.board .button {
  margin: 2px 2px;
}
.board .button.touched, .board .button:focus-visible {
  padding-top: 0px;
  border-width: 5px;
  &.hidden_button, &.empty {
    border-width: 1px;
  }
}
.board .button.touched .symbol, .board .button:focus-visible .symbol {
  margin-top: -4px;
}
.board.border_none .button {
  border-width: 0;
}
.board.border_none .button.touched, .board.border_none .button:focus-visible {
  padding-top: 0px;
  border-width: 5px;
  &:hidden_button {
    border-width: 0;
