@keyframes swing-in {
  0% { transform: scaleX(0.2) scaleY(0.2) translate(-110px,220px); }
  5% { transform: scaleX(0.3) scaleY(0.3) translate(-170px,80px); }
  15% { transform: scaleX(0.5) scaleY(0.5) translate(-170px,-20px); }
  35% { transform: scaleX(0.5) scaleY(0.5) translate(-260px,40px); }
  47% { transform: scaleX(0.75) scaleY(0.75) translate(-130px,50px); }
  60% { transform: translate(10px,0px); }
  70% { transform: translate(10px,0px); }
  100% { transform: scaleY(1.0) translate(0px,0px); }
}
@keyframes fly-in {
  0% { transform: rotate(60deg) scaleX(0.2) scaleY(0.2) translate(-500px,-100px); }
  60% { transform: rotate(-20deg) scaleX(1.2) scaleY(1.2) translate(20px,20px); }
  70% { transform: rotate(-20deg) scaleX(1.2) scaleY(1.2) translate(20px,20px); }
  100% { transform: scaleX(1.0) scaleY(1.0) translate(0px,0px); }
}
@keyframes swinging {
  0% { transform: rotate(0deg); }
  13% { transform: rotate(5deg) translate(-10px,-2px); }
  23% { transform: rotate(10deg) translate(-20px,-5px); }
  27% { transform: rotate(10deg) translate(-20px,-5px); }
  37% { transform: rotate(5deg) translate(-10px,-2px); }
  50% { transform: rotate(0deg); }
  62% { transform: rotate(-5deg) translate(10px,-2px); }
  73% { transform: rotate(-10deg) translate(20px,-5px); }
  77% { transform: rotate(-10deg) translate(20px,-5px); }
  87% { transform: rotate(-5deg) translate(10px,-2px); }
}
@keyframes little-swinging {
  13% { transform: translate(-2px,-2px); }
  23% { transform: translate(-4px,-5px); }
  27% { transform: translate(-4px,-5px); }
  37% { transform: translate(-2px,-2px); }
  50% { transform: rotate(0deg); }
  62% { transform: translate(2px,-2px); }
  73% { transform: translate(4px,-5px); }
  77% { transform: translate(4px,-5px); }
  87% { transform: translate(2px,-2px); }
