    color: $brand-charcoal-blue;
    font-size: 11px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    line-height: 1;
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.85),
      inset 0 -1px 0 rgba(13, 36, 56, 0.06),
      0 1px 2px rgba(13, 36, 56, 0.10),
      0 4px 10px rgba(13, 36, 56, 0.16);
