    .shadow { display: none; }

    .close {
      position: absolute;
      top: 50%;
      right: 12px;
      transform: translateY(-50%);
      width: 24px;
      height: 24px;
      display: flex;
      align-items: center;
      justify-content: center;
      border-radius: 50%;
      opacity: 0.55;
      font-size: 16px;
      line-height: 1;
      padding: 0;
      margin: 0;
      float: none;
      transition: opacity 0.15s ease, background 0.15s ease;
      &:hover { opacity: 1; background: rgba(0,0,0,0.08); }
    }

    .btn[data-dismiss='alert'] {
      margin: 0;
