  background: rgba(255, 255, 255, 0.7);
  color: $brand-slate-gray;
  font-size: 20px;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 1;
  transition: background 0.15s ease, color 0.15s ease;
  float: none;
  margin: 0;
  padding: 0;
}
.modal-content:has(#button_settings) > .modal-header .close:hover {
  background: #fff;
  color: $brand-danger;
}

/* Nav pills sidebar */
#button_settings .nav-pills.nav-stacked {
  background:
    linear-gradient(180deg, rgba($brand-verdigris, 0.04), rgba($brand-dusty-denim, 0.03));
  border-radius: 12px;
  padding: 8px;
  border: 1px solid rgba($la-navy, 0.06);
}
#button_settings .nav-pills.nav-stacked > li {
  margin: 0;
}
#button_settings .nav-pills.nav-stacked > li > a {
  border-radius: 8px;
  padding: 10px 14px;
  font-size: 15px;
  font-weight: 500;
  color: #4a5568;
  transition: background 0.12s ease, color 0.12s ease;
  border: none;
  margin: 2px 0;
}
#button_settings .nav-pills.nav-stacked > li > a:hover {
  background: rgba($brand-verdigris, 0.08);
  color: $brand-verdigris;
}
#button_settings .nav-pills.nav-stacked > li.active > a,
#button_settings .nav-pills.nav-stacked > li.active > a:hover,
#button_settings .nav-pills.nav-stacked > li.active > a:focus-visible {
  background: linear-gradient(135deg, $brand-verdigris, $brand-dusty-denim);
  color: #fff;
  font-weight: 600;
  box-shadow: 0 2px 8px rgba($brand-verdigris, 0.25);
}

/* Stronger keyboard focus ring for all interactive elements in button settings modal.
   Uses outline instead of box-shadow so it doesn't conflict with existing box-shadow on active tabs. */
.modal-content:has(#button_settings) *:focus-visible {
  @include focus-ring($width: 3px);
  border-radius: 6px;
}

/* Form controls */
#button_settings .form-control {
  border-radius: 10px;
  border: 1px solid rgba($la-navy, 0.15);
  padding: 10px 14px;
  font-size: 15px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
  box-shadow: none;
  background: #fff;
}
#button_settings .form-control:focus-visible {
  border-color: $brand-verdigris;
  box-shadow: 0 0 0 3px rgba($brand-verdigris, 0.12);
  outline: none;
}
#button_settings .control-label {
  font-size: 14px;
  font-weight: 600;
  color: $brand-charcoal-dark;
  padding-top: 10px;
}
#button_settings .checkbox label,
#button_settings .radio label {
  font-size: 14px;
  color: #4a5568;
}

/* Quick action buttons (Help tab) */
#button_settings .btn-group-vertical .btn {
  border-radius: 10px !important;
  border: 1px solid rgba($la-navy, 0.10);
  padding: 14px 18px;
  font-size: 16px;
  font-weight: 500;
  color: $brand-charcoal-dark;
  background: #fff;
  text-align: left;
  transition: background 0.12s ease, box-shadow 0.12s ease, transform 0.1s ease;
  margin-bottom: 6px;
}
#button_settings .btn-group-vertical .btn:hover {
  background: rgba($brand-verdigris, 0.06);
  box-shadow: 0 2px 8px rgba($la-navy, 0.08);
  transform: translateX(2px);
}
#button_settings .btn-group-vertical .btn .glyphicon {
  color: $brand-verdigris;
  margin-right: 10px;
}

/* General buttons inside the modal body */
#button_settings .btn-default {
  border-radius: 10px;
  border: 1px solid rgba($la-navy, 0.12);
  background: #fff;
  color: $brand-charcoal-dark;
  font-weight: 500;
  transition: background 0.12s ease, box-shadow 0.12s ease;
}
#button_settings .btn-default:hover {
  background: $surface-200;
  box-shadow: 0 1px 4px rgba($la-navy, 0.10);
}
#button_settings .btn-primary {
  border-radius: 10px;
  background: linear-gradient(135deg, $brand-verdigris, $brand-dusty-denim);
  border: none;
  color: #fff;
  font-weight: 600;
  transition: box-shadow 0.12s ease, transform 0.1s ease;
}
#button_settings .btn-primary:hover {
  box-shadow: 0 2px 10px rgba($brand-verdigris, 0.3);
  transform: translateY(-1px);
}

/* Content area headings */
#button_settings h4 {
  font-size: 18px;
  font-weight: 700;
  color: $la-navy;
  margin-bottom: 12px;
}

/* Image search results / options grid */
#button_settings .options {
  border-radius: 10px;
}

/* Footer */
.modal-content:has(#button_settings) > .modal-footer {
  background:
    linear-gradient(135deg, rgba($brand-verdigris, 0.04), rgba($brand-dusty-denim, 0.04)),
    $surface-100;
  border-top: 1px solid rgba($la-navy, 0.08);
  padding: 14px 24px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.modal-content:has(#button_settings) > .modal-footer .btn {
  border-radius: 10px;
  font-weight: 500;
  font-size: 15px;
  transition: background 0.12s ease, box-shadow 0.12s ease;
}
.modal-content:has(#button_settings) > .modal-footer .btn-lg {
  padding: 10px 22px;
  background: $brand-charcoal-blue;
  color: #fff;
  border: none;
  font-weight: 600;
}
.modal-content:has(#button_settings) > .modal-footer .btn-lg:hover {
  background: $brand-charcoal-blue;
  box-shadow: 0 2px 10px rgba($brand-charcoal-blue, 0.3);
}
/* Arrow nav buttons in footer */
.modal-content:has(#button_settings) > .modal-footer > span .btn {
  border-radius: 8px;
  border: 1px solid rgba($la-navy, 0.12);
  background: #fff;
  color: #4a5568;
}
.modal-content:has(#button_settings) > .modal-footer > span .btn:hover {
  background: $surface-200;
  color: $brand-verdigris;
}

/* Tab content spacing */
#button_settings .content .form-group {
  margin-bottom: 16px;
}

/* Image search area */
#button_settings .image_search,
#button_settings .sound_search {
  border-radius: 12px;
}

/* Close button — fixed top-right corner of the modal */
.modal-content:has(#button_settings) > .modal-header {
  position: relative;
}
.modal-content:has(#button_settings) > .modal-header .close {
  position: absolute;
  top: 14px;
  right: 16px;
  z-index: 2;
}

/* Dropdowns (select elements via bound-select) */
#button_settings select.form-control {
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
  border-radius: 10px;
  border: 1px solid rgba($la-navy, 0.15);
  padding: 6px 32px 6px 12px;
  font-size: 14px;
  font-weight: 500;
  color: $brand-charcoal-dark;
  background: #fff url("data:image/svg+xml,%3Csvg width='12' height='8' viewBox='0 0 12 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1.5L6 6.5L11 1.5' stroke='%236b7280' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E") no-repeat right 10px center;
  background-size: 12px 8px;
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
  line-height: 1.4;
  height: auto;
}
#button_settings select.form-control:focus-visible {
  border-color: $brand-verdigris;
  box-shadow: 0 0 0 3px rgba($brand-verdigris, 0.12);
  outline: none;
}
#button_settings select.form-control:hover {
  border-color: rgba($la-navy, 0.25);
}
#button_settings select.form-control option {
  padding: 6px 12px;
  font-size: 14px;
  color: $brand-charcoal-dark;
  background: #fff;
}
#button_settings select.form-control option:checked {
  background: linear-gradient(135deg, rgba($brand-verdigris, 0.12), rgba($brand-dusty-denim, 0.08));
  color: $la-navy;
  font-weight: 600;
}
/* Short dropdowns (image library, skin, etc.) */
#button_settings select.form-control.skip_select {
  padding: 4px 28px 4px 10px;
  font-size: 14px;
}

/* Responsive: stack sidebar on small screens */
@media (max-width: 768px) {
  .modal-dialog:has(#button_settings) {
    width: auto;
    margin: 10px;
  }
  #button_settings .nav-pills.nav-stacked {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    padding: 6px;
  }
  #button_settings .nav-pills.nav-stacked > li > a {
    padding: 8px 12px;
    font-size: 14px;
  }
}

/* ── Modern board-details modal restyle ───────────────── */

.modal-dialog:has(.la-board-details-wrap) {
  width: 680px;
  max-width: 94vw;
}
.la-board-details-wrap {
  color: $brand-charcoal-dark;
}

.la-board-details-wrap > .modal-header {
  background:
    linear-gradient(135deg, rgba($brand-verdigris, 0.08), rgba($brand-dusty-denim, 0.08), rgba(123, 107, 173, 0.05)),
    $surface-100;
  border-bottom: 1px solid rgba($la-navy, 0.08);
  padding: 18px 24px;
  padding-right: 56px;
  position: relative;
}
.la-board-details-wrap > .modal-header h3 {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  color: $la-navy;
  letter-spacing: -0.3px;
}
.la-board-details-wrap > .modal-header .close {
  position: absolute;
  top: 14px;
  right: 16px;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid rgba($la-navy, 0.12);
  background: rgba(255, 255, 255, 0.7);
  color: $brand-slate-gray;
  font-size: 20px;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 1;
  transition: background 0.15s ease, color 0.15s ease;
  float: none;
  margin: 0;
  padding: 0;
}
.la-board-details-wrap > .modal-header .close:hover {
  background: #fff;
  color: $brand-charcoal-dark;
}

.la-board-details-wrap > .modal-body {
  padding: 8px 24px 24px;
  max-height: 70vh;
  overflow-y: auto;
  overflow-x: hidden;
  max-width: 100%;
  box-sizing: border-box;
  /* Force left-alignment everywhere inside the modal body — overrides
     any inherited `text-align: center` that Bootstrap or legacy
     stylesheets apply at the .modal / .modal-content level. */
  text-align: left;
}
.la-board-details-wrap .modal-body * {
  text-align: inherit;
}

/* Sections — compact card-like clusters. Quiet hairlines between
   them rather than heavy borders so the eye flows down the panel
   without speed-bumps. Modeled on the Linear / GitHub "About"
   sidebar pattern: left-aligned eyebrow heading, tight rows of
   property labels + values below. */
.la-board-details-section {
  padding: 16px 0 18px;
  border-bottom: 1px solid rgba($la-navy, 0.06);
  max-width: 100%;
  min-width: 0;
}
.la-board-details-section:first-of-type {
  padding-top: 4px;
}
.la-board-details-section:last-child {
  border-bottom: none;
}
.la-board-details-section__heading {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.10em;
  color: $brand-verdigris-aa;
  margin: 0 0 10px 0;
  /* Left-aligned eyebrow — replaces the centered "OVERVIEW /
     LANGUAGE / VISIBILITY & LICENSE" headings that floated in the
     middle of the modal and broke the visual rhythm. */
  text-align: left;
}

/* Definition list grid — proper two-column layout with values
   left-aligned at a consistent left edge. Bootstrap's legacy
   `dl-horizontal` (right-aligned dt + floated dd) is replaced
   with a CSS grid; explicit text-align: left on dt and dd fights
   off any global centering. */
.la-board-details-wrap .dl-horizontal {
  display: grid;
  grid-template-columns: 150px minmax(0, 1fr);
  column-gap: 20px;
  row-gap: 0;
  margin: 0;
  max-width: 100%;
}
.la-board-details-wrap .dl-horizontal dt {
  font-size: 13px;
  font-weight: 500;
  color: rgba($la-navy, 0.55);
  padding: 8px 0;
  text-align: left !important;
  margin: 0;
  white-space: normal;
  width: auto;
  float: none;
  min-width: 0;
  line-height: 1.4;
  /* Subtle hairline between rows for scanability — Linear /
     Stripe Dashboard style. Skips the very last row in each
     section via :has() below. */
  border-top: 1px solid rgba($la-navy, 0.05);
}
.la-board-details-wrap .dl-horizontal dt:first-of-type,
.la-board-details-wrap .dl-horizontal dt:first-of-type + dd {
  border-top: none;
}
.la-board-details-wrap .dl-horizontal dd {
  font-size: 14px;
  font-weight: 500;
  color: $la-navy;
  padding: 8px 0;
  margin: 0;
  margin-left: 0;
  text-align: left !important;
  overflow-wrap: anywhere;
  word-break: break-word;
  min-width: 0;
  line-height: 1.55;
  border-top: 1px solid rgba($la-navy, 0.05);
}

/* Description block — full-width prominent content under the dl,
   not center-aligned, no decorative left border. Just clean body
   typography with preserved line breaks for the prose. */
.la-board-details-wrap .la-board-details__description {
  white-space: pre-line;
  font-size: 14px;
  color: $la-navy;
  line-height: 1.6;
  padding: 0;
  margin: 0;
  text-align: left !important;
}
/* When the description sits in the dd column, give it the same
   row treatment as siblings but allow its content to scroll
   internally if it's exceptionally long. */
.la-board-details-wrap .dl-horizontal dd .la-board-details__description,
.la-board-details-wrap .dl-horizontal dd.la-board-details__description {
  max-height: none;
}

/* Overview head — name + description block sitting prominently
   above the property grid. Replaces the previous "Name" / "Description"
   rows in the dl so the descriptive content reads like a card
   header rather than two more entries in a metadata table. */
.la-board-details-overview-head {
  margin: 4px 0 14px;
  padding: 0;
}
.la-board-details-overview-head__name {
  font-size: 18px;
  font-weight: 700;
  color: $la-navy;
  margin: 0 0 8px 0;
  line-height: 1.3;
  letter-spacing: -0.01em;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

/* Stat tiles — replaces the dl rows for "Stats & Connections" so
   numeric metadata reads as glanceable cards rather than a list
   of small text values. Pattern mirrors GitHub's "Insights"
   tiles + Linear's project metrics row. */
.la-board-details-stats {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 10px;
  margin: 4px 0 0;
}
.la-board-details-stat {
  padding: 12px 14px;
  border: 1px solid rgba($la-navy, 0.08);
  border-radius: 10px;
  background: rgba($la-navy, 0.02);
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.la-board-details-stat__value {
  font-size: 22px;
  font-weight: 700;
  color: $la-navy;
  line-height: 1.1;
  letter-spacing: -0.01em;
}
.la-board-details-stat__label {
  font-size: 11px;
  font-weight: 600;
  color: rgba($la-navy, 0.55);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.la-board-details-stat__link {
  font-size: 12px;
  font-weight: 500;
  margin-top: 2px;
}
.la-board-details-stat__link a {
  color: $brand-verdigris-aa;
  text-decoration: none;
}
.la-board-details-stat__link a:hover {
  text-decoration: underline;
}

@media (max-width: 540px) {
  .la-board-details-wrap .dl-horizontal {
    grid-template-columns: 1fr;
  }
  .la-board-details-wrap .dl-horizontal dt {
    padding: 10px 0 0;
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: rgba($la-navy, 0.50);
    border-top: 1px solid rgba($la-navy, 0.06);
  }
  .la-board-details-wrap .dl-horizontal dt:first-of-type {
    border-top: none;
  }
  .la-board-details-wrap .dl-horizontal dd {
    padding: 2px 0 12px;
    border-top: none;
  }
}
.la-board-details-wrap .dl-horizontal a {
  /* WCAG AA fix — was $brand-verdigris on $surface-100 = 3.15:1. */
  color: $brand-verdigris-aa;
  text-decoration: none;
  font-weight: 500;
}
.la-board-details-wrap .dl-horizontal a:hover {
  color: #146462;
  text-decoration: underline;
}

/* Actions section */
.la-board-details-section--actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.la-board-details-wrap .btn-default {
  border-radius: 24px;
  border: 1px solid rgba($la-navy, 0.12);
  background: #fff;
  color: $brand-charcoal-dark;
  font-weight: 500;
  font-size: 14px;
  padding: 9px 20px;
  transition: background 0.15s ease, box-shadow 0.15s ease, transform 0.1s ease;
}
.la-board-details-wrap .btn-default:hover {
  background: $surface-200;
  box-shadow: 0 2px 8px rgba($la-navy, 0.10);
  transform: translateY(-1px);
}
.la-board-details-wrap .dl-horizontal a.la-board-details-rename-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-left: 6px;
  color: $brand-charcoal-blue !important;
  opacity: 1;
  transition: color 0.15s ease;
  vertical-align: middle;
  font-weight: normal;
}
.la-board-details-rename-link svg {
  stroke-width: 2.5;
}
.la-board-details-wrap .dl-horizontal a.la-board-details-rename-link:hover {
  /* WCAG AA fix — hover was $brand-verdigris (3.15:1 on light bg). */
  color: $brand-verdigris-aa !important;
}
.la-board-details-delete-btn {
  color: $brand-danger !important;
  border-color: rgba($brand-danger, 0.2) !important;
}
.la-board-details-delete-btn:hover {
  background: rgba($brand-danger, 0.06) !important;
  color: #a93226 !important;
}

/* Edit Board Details button (top-right of modal body) */
.la-board-details-edit-btn-wrap,
.md-board-details-edit-btn-wrap {
  display: flex;
  justify-content: flex-end;
  margin-bottom: 4px;
}
.la-board-details-edit-btn,
.md-board-details-edit-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  border-radius: 8px;
  border: 1px solid rgba($brand-verdigris, 0.25);
  background: rgba($brand-verdigris, 0.06);
  color: $brand-verdigris-aa; /* WCAG AA fix — was $brand-verdigris (3.32:1). */
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.12s ease, border-color 0.12s ease;
}
.la-board-details-edit-btn:hover,
.md-board-details-edit-btn:hover {
  background: rgba($brand-verdigris, 0.12);
  border-color: rgba($brand-verdigris, 0.4);
}
.la-board-details-edit-btn svg,
.md-board-details-edit-btn svg {
  flex-shrink: 0;
}

/* Footer */
.la-board-details-wrap > .modal-footer {
  background:
    linear-gradient(135deg, rgba($brand-verdigris, 0.04), rgba($brand-dusty-denim, 0.04)),
    $surface-100;
  border-top: 1px solid rgba($la-navy, 0.08);
  padding: 14px 24px;
}
.la-board-details-wrap > .modal-footer .btn-lg {
  border-radius: 10px;
  padding: 10px 22px;
  background: $brand-charcoal-blue;
  color: #fff;
  border: none;
  font-weight: 600;
  font-size: 15px;
  transition: background 0.12s ease, box-shadow 0.12s ease;
}
.la-board-details-wrap > .modal-footer .btn-lg:hover {
  background: $brand-charcoal-blue;
  box-shadow: 0 2px 10px rgba($brand-charcoal-blue, 0.3);
}

@media (max-width: 640px) {
  .la-board-details-wrap .dl-horizontal {
    grid-template-columns: 1fr;
  }
  .la-board-details-wrap .dl-horizontal dt {
    text-align: left;
    padding-bottom: 2px;
    border-bottom: none;
  }
  .la-board-details-wrap .dl-horizontal dd {
    padding-top: 0;
    padding-bottom: 12px;
  }
}

