}
.la-tag-board-submit {
  /* Brand slate-blue primary — matches the rest of the modernized
     primary CTAs (back-to-boards, save) so the entire app's
     "confirm" verb reads with the same color + weight. */
  background: $brand-slate-blue;
  color: #ffffff;
  border: 1px solid $brand-slate-blue;
  padding: 10px 22px;
  border-radius: 999px;
  font-weight: 600;
