  transition: background 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;

  &:hover:not(:disabled),
  &:focus-visible {
    background: color.adjust($brand-slate-blue, $lightness: -6%);
    border-color: color.adjust($brand-slate-blue, $lightness: -6%);
    box-shadow: 0 3px 10px rgba($brand-charcoal-blue, 0.30);
