  opacity:1; transition:background 0.15s ease, color 0.15s ease; float:none; margin:0; padding:0;
}
.la-edit-board-details-wrap > .modal-header .close:hover { background:#fff; color:$brand-charcoal-dark; }
.la-edit-board-details-wrap > .modal-body { padding:8px 24px 24px; max-height:70vh; overflow-y:auto; }

/* Sections */
.la-edit-board-section {
  padding:16px 0;
  border-bottom:1px solid rgba($la-navy, 0.10);
}
.la-edit-board-section:last-child { border-bottom:none; }
.la-edit-board-section__heading {
  font-size:14px; font-weight:700; text-transform:uppercase;
  letter-spacing:0.06em; color:$brand-verdigris-aa; margin:0 0 12px; /* WCAG AA fix. */
}

/* Fields */
.la-edit-board-field { margin-bottom:14px; }
.la-edit-board-field:last-child { margin-bottom:0; }
.la-edit-board-label {
  display:block; font-size:14px; font-weight:600; color:$brand-slate-gray; margin-bottom:5px;
}
.la-edit-board-input {
  width:100%; border-radius:10px; border:1px solid rgba($la-navy, 0.15);
  padding:10px 14px; font-size:15px; color:$la-navy; background:#fff;
  transition:border-color 0.15s ease, box-shadow 0.15s ease;
}
.la-edit-board-input:focus-visible { border-color:$brand-verdigris; box-shadow:0 0 0 3px rgba($brand-verdigris, 0.12); outline:none; }
.la-edit-board-input::placeholder { color:$brand-cool-steel; font-style:italic; }
.la-edit-board-textarea { min-height:80px; resize:vertical; }
.la-edit-board-select {
  appearance:none; -webkit-appearance:none; -moz-appearance:none; width:100%; border-radius:10px;
  border:1px solid rgba($la-navy, 0.15); padding:10px 36px 10px 14px; font-size:15px; font-weight:500;
  color:$la-navy; background:#fff url("data:image/svg+xml,%3Csvg width='12' height='8' viewBox='0 0 12 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1.5L6 6.5L11 1.5' stroke='%236b7280' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E") no-repeat right 12px center;
  background-size:12px 8px; cursor:pointer; transition:border-color 0.15s ease, box-shadow 0.15s ease;
}
.la-edit-board-select:focus-visible { border-color:$brand-verdigris; box-shadow:0 0 0 3px rgba($brand-verdigris, 0.12); outline:none; }
.la-edit-board-field-row { display:flex; gap:10px; align-items:center; margin-top:8px; }
.la-edit-board-field--half { flex:1; }
.la-edit-board-checkbox {
  display:flex; align-items:flex-start; gap:10px; font-size:14px; color:$brand-charcoal-dark; cursor:pointer;
  padding:8px 12px; background:rgba($brand-verdigris, 0.03); border:1px solid rgba($la-navy, 0.06);
  border-radius:10px; margin-bottom:6px;
}
.la-edit-board-checkbox:last-child { margin-bottom:0; }
.la-edit-board-check { margin-top:2px; accent-color:$brand-verdigris; width:16px; height:16px; flex-shrink:0; }
.la-edit-board-hint { font-size:0.9375rem; color:$brand-slate-gray; margin:6px 0 0; line-height:1.4; }

/* Icon picker */
.la-edit-board-icon-row { display:flex; align-items:flex-start; gap:10px; margin-top:10px; }
.la-edit-board-icon-preview {
  width:42px; height:42px; border:1px solid rgba($la-navy, 0.12); border-radius:8px; overflow:hidden; flex-shrink:0;
}
.la-edit-board-icon-preview img { width:100%; height:100%; object-fit:cover; cursor:pointer; }
.la-edit-board-icon-options { display:flex; flex-wrap:wrap; gap:6px; }
.la-edit-board-icon-option {
  width:36px; height:36px; border:1px solid rgba($la-navy, 0.10); border-radius:8px;
  cursor:pointer; object-fit:cover; transition:border-color 0.12s ease, transform 0.1s ease;
}
.la-edit-board-icon-option:hover { border-color:$brand-verdigris; transform:scale(1.08); }

/* Background preview */
.la-edit-board-bg-preview {
  width:120px; height:80px; border:1px solid rgba($la-navy, 0.10); border-radius:8px;
  overflow:hidden; margin:8px 0;
}
.la-edit-board-bg-preview img { width:100%; height:100%; object-fit:contain; }
.la-edit-board-color-swatch {
  display:inline-block; width:36px; height:36px; border:2px solid rgba($la-navy, 0.15);
  border-radius:8px; cursor:pointer; vertical-align:middle; flex-shrink:0;
}
.la-edit-board-dropdown-btn {
  border-radius:10px; border:1px solid rgba($la-navy, 0.12); background:$surface-100;
  color:$brand-charcoal-dark; font-size:14px; font-weight:500; padding:8px 14px; cursor:pointer;
  display:inline-flex; align-items:center; gap:4px;
}
.la-edit-board-dropdown-btn:hover { background:$surface-200; }

/* Intro sections */
.la-edit-board-intro-section {
  position:relative; padding:12px; background:rgba($brand-verdigris, 0.03);
  border:1px solid rgba($la-navy, 0.06); border-radius:10px; margin-bottom:8px;
}
.la-edit-board-intro-section .la-edit-board-input { margin-bottom:6px; }
.la-edit-board-intro-section .la-edit-board-input:last-of-type { margin-bottom:0; }
.la-edit-board-remove-btn {
  position:absolute; top:8px; right:8px; width:28px; height:28px; border-radius:50%;
  border:1px solid rgba($brand-danger, 0.15); background:#fff; color:$brand-danger;
  cursor:pointer; display:flex; align-items:center; justify-content:center; padding:0;
}
.la-edit-board-remove-btn:hover { background:rgba($brand-danger, 0.06); }
.la-edit-board-add-btn {
  border-radius:24px; padding:8px 18px; background:#fff; color:$brand-charcoal-dark;
  border:1px solid rgba($la-navy, 0.12); font-size:14px; font-weight:500; cursor:pointer;
}
.la-edit-board-add-btn:hover { background:$surface-200; }

/* Advanced link */
.la-edit-board-advanced-link { color:$brand-verdigris-aa; font-size:1rem; font-weight:500; } /* WCAG AA fix. */
.la-edit-board-advanced-link:hover { color:#146462; text-decoration:underline; }

/* Footer */
.la-edit-board-details-wrap > .modal-footer {
  background: linear-gradient(135deg, rgba($brand-verdigris, 0.04), rgba($brand-dusty-denim, 0.04)), $surface-100;
  border-top:1px solid rgba($la-navy, 0.08); padding:14px 24px;
}
.la-edit-board-close {
  border-radius:24px; padding:10px 24px; background:$brand-charcoal-blue; color:#fff; border:none;
  font-weight:600; font-size:15px; text-decoration:none;
  transition:background 0.12s ease, box-shadow 0.12s ease;
}
.la-edit-board-close:hover { background:$brand-charcoal-blue; box-shadow:0 2px 10px rgba($brand-charcoal-blue, 0.3); color:#fff; text-decoration:none; }

/* ── Modern board-ideas modal restyle ─────────────────── */

.modal-dialog:has(.la-board-ideas-wrap) { width:660px; max-width:94vw; }
