.la-board-ideas-tab--active {
  background:linear-gradient(135deg, $brand-verdigris, $brand-dusty-denim); color:#fff; font-weight:600;
}
.la-board-ideas-tab--active:hover { background:linear-gradient(135deg, #238b7f, #3e74c0); color:#fff; }

/* Explainer */
.la-board-ideas-explainer { font-size:0.9375rem; color:$brand-slate-gray; line-height:1.5; margin-bottom:14px; }

/* Search */
.la-board-ideas-search { display:flex; gap:8px; margin-bottom:14px; }
.la-board-ideas-search-input {
  flex:1; border-radius:10px; border:1px solid rgba($la-navy, 0.15); padding:10px 14px;
