}
.la-board-ideas-item:hover { background:$surface-100; box-shadow:0 1px 4px rgba($la-navy, 0.08); }
.la-board-ideas-item--with-image { min-height:80px; }
.la-board-ideas-item-image { width:64px; height:64px; border-radius:8px; overflow:hidden; flex-shrink:0; }
.la-board-ideas-item-image img { width:100%; height:100%; object-fit:cover; }
.la-board-ideas-item-text { flex:1; font-size:15px; white-space:normal; }
.la-board-ideas-item-text--used { color:$brand-slate-gray; } /* WCAG AA fix — was $brand-cool-steel (2.84:1). */
.la-board-ideas-item-check { color:$brand-verdigris-aa; margin-right:6px; font-weight:700; } /* WCAG AA fix. */
.la-board-ideas-item-count { font-size:0.9375rem; color:$brand-slate-gray; font-weight:400; margin-left:auto; flex-shrink:0; }
.la-board-ideas-add-btn {
  border-radius:24px; padding:6px 16px; background:#fff; color:$brand-charcoal-dark;
  border:1px solid rgba($la-navy, 0.12); font-size:14px; font-weight:500; cursor:pointer;
