}
table#pin {
  table-layout: fixed;
  width: 100%;
  max-width: 360px;
  margin-left: auto;
  margin-right: auto;
}
table#pin td a {
  display: block;
  height: 80px;
  width: 100%;
  cursor: pointer;
  color: #000;
  font-size: 24px;
  padding-top: 22px;
}
table#pin td a.pin-key__icon {
  font-size: 28px;
  line-height: 80px;
  padding-top: 0;
}
table#pin td a.pin-key__icon img {
  display: block;
  height: 32px;
  width: auto;
  margin: 24px auto 0;
}
table#pin td {
  border: 1px solid #ddd;
  width: 33.33%;
}
table#pin tr:first-child td {
  border-top-color: #bbb;
}
table#pin tr td:first-child {
  border-left-color: #bbb;
}
table#pin tr td:last-child {
  border-right-color: #bbb;
}
table#pin tr:last-child td {
  border-bottom-color: #bbb;
}
table#pin td a:hover {
  text-decoration: none;
}

table#pin td:hover, table#pin td:focus-visible, table#pin td a.touched {
  background-color: #eee;
}

table>tbody>tr.voice_pad>td {
  padding-top: 15px;
  padding-bottom: 15px;
}

#checklist li.text-muted a {
  color: rgb(153, 153, 153);
}

.swatch {
  width: 18px;
  height: 18px;
  border: 1px solid #888;
  background: #fff;
  display: inline-block;
  margin-bottom: -2px;
}

/* Applied in: Button search results - content grabbers, button settings */
#button_results {
  margin-top: 10px;
}
#button_results .result {
  cursor: pointer;
  padding: 10px;
  border: 1px solid #ccc;
  border-radius: 3px;
  margin-top: 3px;
}
#button_results .result:hover {
  background: #eee;
  border-color: #aaa;
  
}
