    width: 100%;
  }
}
.user_weeks {
  .week {
    width: 10%; 
    height: 50px; 
    float: left; 
    border: 1px solid #ddd; 
    margin-left: -1px; 
    margin-bottom: -1px;
    margin-top: -1px;
    padding: 5px;


    &.level_0 {
      background: #fff;
    }
    &.level_1, &.level_2 {
      background: #dee8ef;
    }
    &.level_2 {
      background: #D1E1EE;
    }
    &.level_3 {
      background: #b9d1e5;
    }
    &.level_4 {
      background: #A4C5E1;
    }
    &.level_5 {
      background: #7ca7cc;
    }
    &.level_6 {
      background: #6a9ac4;
      color: #fff;
    }
    &.level_7, &.level_8 {
      background: #6195C2;
      color: #fff;
    }
    &.level_9, &.level_10 {
      background: $nav_primary;
      color: #fff;
    }
    &.level_11, &.level_12, &.level_13, &.level_14, &.level_15 {
      background: #0f6175;
      color: #fff;
    }
    &.level_16, &.level_17, &.level_18, &.level_19, &.level_20 {
      background: #0c6e49;
      color: #fff;
    }
    &:hover {
      border-width: 3px;
      padding: 3px;
    }
  }
  .week_label {
    width: 10%; 
    float: left; 
    border: 1px solid rgba(255, 255, 255, 0); 
    margin-left: -1px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    padding-top: 5px;
    padding-bottom: 10px;
    rotate: -15deg;
    color: #888;
  }
}
table tr.long_delay td {
  border-top-width: 4px;
}
.small-placeholder:placeholder-shown {
  font-size: 14px;
}
.btn  {
  .sub_note {
    color: #a65151; font-size: 14px; margin-left: 55px; height: 0; margin-top: -2px; height: 2px; font-style: italic;  
  }
