.subscription_table {
  border-collapse: separate;
  border-spacing: 0;
  max-width: 720px;
  width: 100%;
  background: #fff;
  border-radius: 20px;
  overflow: hidden;
  box-shadow: 0 8px 24px rgba($indigo, 0.10), 0 0 0 1px rgba($indigo, 0.04);

  .glyphicon {
    font-size: 20px;
  }

  th {
    padding: 8px 12px;
  }

  /* ── Base cell styles ── */
  td {
    padding: 16px 20px;
    border-bottom: 1px solid $color-linen;
    text-align: center;
    font-size: 15px;
    line-height: 1.5;
    color: $indigo;
    transition: background 0.12s ease;
    vertical-align: middle;

    .sale {
      background: linear-gradient(135deg, #d4edda 0%, #c3e6cb 100%);
      position: absolute;
      top: 0;
      width: 100%;
      margin-left: -20px;
      border-bottom: 1px solid $color-linen;
      color: $indigo;
      font-size: 14px;
      font-weight: 600;
      padding: 6px 0;
      letter-spacing: 0.06em;
      text-transform: uppercase;
    }
  }

  /* ── Column dividers ── */
  /* Supporter column: strong left border */
  td.separator {
    border-left: 2px solid #c5bfb3;
  }
  /* Eval column: left border to separate from Supporter */
  td:last-child {
    border-left: 2px solid #c5bfb3;
  }
  /* Don't double-border when separator IS the last child */
  td.separator:last-child {
    border-left: 2px solid #c5bfb3;
  }

  td.dim {
    background: $color-warm-white;
    div.middle {
      background: $color-warm-white;
    }
  }

  /* ── "- or -" divider badge ── */
  div.middle {
    background: #fff;
    position: absolute;
    right: -25px;
    width: 50px;
    height: 36px;
    padding-top: 6px;
    z-index: 2;
    top: 50px;
    font-size: 18px;
    color: $brand-slate-gray;
    font-weight: 500;
  }

  /* ── Currency & lifetime labels ── */
  .subscription-currency-us {
    color: var(--fs-dark-teal, $brand-verdigris);
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 0.06em;
  }

  .subscription-table__lifetime-purchase {
    color: var(--fs-navy, $la-navy);
    font-weight: 600;
  }

  /* ── Cloud extras links ── */
  td a[href*='blog.mylingolinq.com'] {
    color: var(--fs-dark-teal, $brand-verdigris);
    text-decoration: none;
    font-weight: 500;
    border-bottom: 1px solid transparent;
    transition: border-color 0.12s ease;
  }
  td a[href*='blog.mylingolinq.com']:hover {
    color: var(--fs-dark-teal, $brand-verdigris);
    border-bottom-color: var(--fs-dark-teal, $brand-verdigris);
  }

  td.subscription-table__cloud-extras-right a[href*='blog.mylingolinq.com'] {
    color: var(--fs-dark-teal, $brand-verdigris);
    text-decoration: none;
    border-bottom: 1px solid transparent;
  }
  td.subscription-table__cloud-extras-right a[href*='blog.mylingolinq.com']:hover {
    border-bottom-color: var(--fs-dark-teal, $brand-verdigris);
  }

  .btn-primary .subscription-currency-us {
    color: rgba(255, 255, 255, 0.85);
  }

  /* ── Default row hover ── */
  tr:hover {
    td {
      background: rgba(58, 107, 199, 0.03);
    }
    div.middle {
      background: rgba(58, 107, 199, 0.03);
    }
  }

  /* ── Header row ── */
  tbody tr:first-child td {
    padding: 20px;
    border-bottom: 2px solid $color-linen;
  }
  /* Pin header cells to their default bg on hover — no hover effect */
  tbody tr:first-child:hover td.subscription-table__communicator-header {
    background: #2c5282;
  }
  tbody tr:first-child:hover td.subscription-table__supporter-header {
    background: color.adjust(#415a75, $lightness: 17%, $saturation: 12%);
  }
  tbody tr:first-child:hover td.subscription-table__eval-header {
    background: color.adjust($brand-slate-gray, $lightness: 23%);
  }
  tbody tr:first-child td:first-child {
    border-top-left-radius: 20px;
  }
  tbody tr:first-child td:last-child {
    border-top-right-radius: 20px;
  }

  .subscription-table__communicator-header {
    font-size: 22px;
    font-weight: 700;
    color: #fff;
    background: #2c5282;
    letter-spacing: 0.01em;
  }

  .subscription-table__supporter-header {
    font-size: 18px;
    font-weight: 700;
    color: #fff;
    background: color.adjust(#415a75, $lightness: 20%, $saturation: 12%); /* 15% lighter than sign-in button */
  }

  .subscription-table__eval-header {
    font-size: 18px;
    font-weight: 700;
    color: #fff;
    background: var(--fs-medium-gray, $brand-slate-gray);
  }

  /* ── Subtle column background tints (skip header row) ── */
  /* Communicator columns (default cells) */
  tbody tr:not(:first-child) td {
    background: rgba(44, 82, 130, 0.02);
  }
  /* Supporter column */
  tbody tr:not(:first-child) td.separator {
    background: rgba(26, 122, 110, 0.04);
  }
  /* Eval column */
  tbody tr:not(:first-child) td:last-child {
    background: rgba(139, 111, 58, 0.04);
  }

  /* ── Plan buttons row hover ── */
  tr.subscription-table__row--plan-buttons:hover td {
    background: rgba($la-teal, 0.08);
  }

  /* ── Last row rounding ── */
  tbody tr:last-child td {
    border-bottom: none;
    padding: 12px;
    .btn {
      width: 100%;
    }
  }
  tbody tr:first-child {
    td:first-child {
      border-top-left-radius: 20px;
    }
    td.separator {
      border-left-color: rgba(255, 255, 255, 0.25);
    }
    td:last-child {
      border-top-right-radius: 20px;
      border-left-color: rgba(255, 255, 255, 0.25);
    }
  }
  tbody tr:last-child {
    td:first-child {
      border-bottom-left-radius: 20px;
    }
    td:last-child {
      border-bottom-right-radius: 20px;
    }
  }

  /* ── Plan buttons ── */
  .btn {
    padding: 10px 16px;
    border-radius: 999px;
    font-weight: 600;
    font-size: 14px;
    line-height: 1.2;
    transition: all 0.25s ease;
    border: none;
  }
  .btn-primary {
    background: var(--fs-navy, $la-navy);
    color: #fff;
    box-shadow: 0 4px 12px rgba($indigo, 0.08);
  }
  .btn-primary:hover {
    background: #243F6B;
    box-shadow: 0 8px 24px rgba($indigo, 0.10);
    transform: translateY(-2px);
  }
  .btn-default {
    background: transparent;
    border: 2px solid var(--fs-navy, $la-navy);
    color: var(--fs-navy, $la-navy);
    box-shadow: 0 1px 4px rgba($indigo, 0.06);
  }

  /* Right plan buttons: white bg when unselected */
  tr.subscription-table__row--plan-buttons td:nth-child(2) .btn-default,
  tr.subscription-table__row--plan-buttons td:nth-child(3) .btn-default,
  tr.subscription-table__row--plan-buttons td:nth-child(4) .btn-default {
    background: #fff;
  }
  /* Right plan buttons hover */
  tr.subscription-table__row--plan-buttons td:nth-child(2) .btn-default:hover,
  tr.subscription-table__row--plan-buttons td:nth-child(3) .btn-default:hover,
  tr.subscription-table__row--plan-buttons td:nth-child(4) .btn-default:hover {
    background: #243F6B;
    border-color: #243F6B;
    color: #fff;
  }
  tr.subscription-table__row--plan-buttons td:nth-child(2) .btn:hover,
  tr.subscription-table__row--plan-buttons td:nth-child(3) .btn:hover,
  tr.subscription-table__row--plan-buttons td:nth-child(4) .btn:hover {
    transform: translateY(-2px) !important;
    box-shadow: 0 8px 24px rgba($indigo, 0.10);
  }

  /* First plan button: same outline ring */
  td.subscription-table__cell--first-plan .btn-default,
  td.subscription-table__cell--first-plan .btn-default:hover {
    box-shadow: 0 1px 4px rgba($indigo, 0.06) !important;
  }
  td.subscription-table__cell--first-plan .btn-primary {
    border: 2px solid var(--fs-navy, $la-navy);
    background: var(--fs-navy, $la-navy);
    color: #fff;
    box-shadow: 0 4px 12px rgba($indigo, 0.08);
  }
  td.subscription-table__cell--first-plan .btn-primary:hover {
    border-color: #243F6B;
    background: #243F6B;
    color: #fff;
    box-shadow: 0 8px 24px rgba($indigo, 0.10);
  }
  tr.subscription-table__row--plan-buttons:hover td.subscription-table__cell--first-plan .btn-primary {
    background: var(--fs-navy, $la-navy) !important;
    color: #fff;
  }
  tr.subscription-table__row--plan-buttons:has(td:nth-child(2):hover) td.subscription-table__cell--first-plan .btn-primary,
  tr.subscription-table__row--plan-buttons:has(td:nth-child(3):hover) td.subscription-table__cell--first-plan .btn-primary,
  tr.subscription-table__row--plan-buttons:has(td:nth-child(4):hover) td.subscription-table__cell--first-plan .btn-primary {
    background: #fff !important;
    color: var(--fs-navy, $la-navy);
  }
  tr.subscription-table__row--plan-buttons:has(td:nth-child(2):hover) td.subscription-table__cell--first-plan .btn-primary .subscription-currency-us,
  tr.subscription-table__row--plan-buttons:has(td:nth-child(3):hover) td.subscription-table__cell--first-plan .btn-primary .subscription-currency-us,
  tr.subscription-table__row--plan-buttons:has(td:nth-child(4):hover) td.subscription-table__cell--first-plan .btn-primary .subscription-currency-us {
    color: var(--fs-dark-teal, $brand-verdigris);
  }
  .btn-default:hover {
    background: var(--fs-navy, $la-navy);
    border: 2px solid var(--fs-navy, $la-navy);
    color: #fff;
    box-shadow: 0 4px 12px rgba($indigo, 0.08);
    transform: translateY(-2px) !important;
  }
  td .btn:hover {
    transform: translateY(-2px) !important;
  }

  /* ── Feature rows: alternating light bg ── */
  tr.subscription-table__row--light-gray-bg td {
    background: $color-warm-white;
  }
  tr.subscription-table__row--light-gray-bg:hover td {
    background: #f5f5f0;
  }

  /* ── Pricing row ── */
  tr.subscription-table__row--pricing td {
    vertical-align: middle;
    padding-top: 24px;
    padding-bottom: 24px;
  }
  tr.subscription-table__row--pricing div.middle {
    top: 50%;
    transform: translateY(-50%);
  }

  /* Large price amounts */
  tr.subscription-table__row--pricing td span[style*='font-size: 40px'],
  tr.subscription-table__row--pricing td span[style*='font-size: 25px'] {
    font-weight: 700 !important;
    color: var(--fs-navy, $la-navy) !important;
  }

  /* ── No-hover rows ── */
  tr.subscription-table__row--no-hover:hover td {
    background: #fff;
  }
  tr.subscription-table__row--no-hover:hover div.middle {
    background: #fff;
  }

  /* ── Blue accent row (supervisor credits / bulk) ── */
  tr.subscription-table__row--blue-bg td {
    background: rgba(58, 107, 199, 0.08);
    border-bottom-color: rgba(58, 107, 199, 0.12);
  }
  tr.subscription-table__row--blue-bg:hover td {
    background: rgba(58, 107, 199, 0.12);
  }
  tr.subscription-table__row--blue-bg td a {
    color: var(--fs-dark-teal, $brand-verdigris);
    font-weight: 600;
    text-decoration: none;
  }
  tr.subscription-table__row--blue-bg td a:hover {
    text-decoration: underline;
  }

  /* ── Navy CTA row (trial / gift / modeling) ── */
  tbody tr.subscription-table__row--navy-bg td {
    background: var(--fs-navy, $la-navy);
    color: $brand-honey-bronze;
    padding-top: 20px !important;
    padding-bottom: 20px !important;

    a {
      color: $brand-honey-bronze;
      text-decoration: none;
      font-weight: 600;
      &:hover {
        text-decoration: underline;
      }
    }
    .btn-default {
      border-color: var(--fs-teal, $la-teal);
      color: var(--fs-teal, $la-teal);
    }
    .btn-default:hover {
      background: rgba($la-teal, 0.15);
      border-color: var(--fs-teal, $la-teal);
      color: var(--fs-teal, $la-teal);
    }
    .btn-primary {
      background: var(--fs-teal, $la-teal);
      color: var(--fs-navy, $la-navy);
      font-weight: 700;
    }
    .btn-primary:hover {
      background: $brand-verdigris;
      color: #fff;
    }
  }
  tr.subscription-table__row--navy-bg:hover td {
    background: #243F6B;
    color: $brand-honey-bronze;
    a {
      color: $brand-honey-bronze;
    }
  }
}

/* ── Subscription form card layout (replaces table on subscription-form) ── */
form.row.subscription-form-with-cards {
  width: 100%;
  max-width: 960px;
}

.subscription-form-cards {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 0;
  max-width: 100%;
  width: 100%;
  background: #fff;
  border-radius: 20px;
  overflow: hidden;
  box-shadow: 0 8px 24px rgba($indigo, 0.10), 0 0 0 1px rgba($indigo, 0.04);
}

.subscription-form-card {
  display: flex;
  flex-direction: column;
  border-left: 2px solid #c5bfb3;

  &:first-child {
    border-left: none;
  }
}

.subscription-form-card__header {
  padding: 20px;
  text-align: center;
  font-size: 22px;
  font-weight: 700;
  color: #fff;
  letter-spacing: 0.01em;

  &.subscription-table__communicator-header {
    background: #2c5282;
    font-size: 22px;
  }

  &.subscription-table__supporter-header {
    background: color.adjust(#415a75, $lightness: 20%, $saturation: 12%);
    font-size: 18px;
  }

  &.subscription-table__eval-header {
    background: var(--fs-medium-gray, $brand-slate-gray);
    font-size: 18px;
  }
}

.subscription-form-card__body {
  flex: 1;
  display: flex;
  flex-direction: column;
  padding: 16px 20px;
  font-size: 15px;
  line-height: 1.5;
  color: $indigo;

  .subscription-form-card--communicator & {
    background: rgba(44, 82, 130, 0.02);
  }

  .subscription-form-card--supporter & {
    background: rgba(26, 122, 110, 0.04);
  }

  .subscription-form-card--eval & {
    background: rgba(139, 111, 58, 0.04);
  }
}

.subscription-form-card__description,
.subscription-form-card__feature,
.subscription-form-card__row {
  padding: 12px 0;
  border-bottom: 1px solid $color-linen;
}

.subscription-form-card__description.subscription-table__row--light-gray-bg,
.subscription-form-card__feature.subscription-table__row--light-gray-bg,
.subscription-form-card__row.subscription-table__row--light-gray-bg {
  background: rgba(44, 82, 130, 0.03);
}

.subscription-form-card__pricing {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 12px;
  padding: 16px 0;
  border-bottom: 1px solid $color-linen;
  position: relative;

  .subscription-form-card__price-block {
    flex: 1;
    min-width: 100px;
  }

  .middle {
    background: #fff;
    padding: 6px 10px;
    font-size: 18px;
    color: $brand-slate-gray;
    font-weight: 500;
    margin: 8px 0;
  }

  .sale {
    background: linear-gradient(135deg, #d4edda 0%, #c3e6cb 100%);
    color: $indigo;
    font-size: 14px;
    font-weight: 600;
    padding: 6px 0;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    margin: -16px -20px 8px -20px;
    padding: 6px 20px;
  }
}

.subscription-form-card__feature-item {
  margin-top: 8px;

  &:first-child {
    margin-top: 0;
  }
}

.subscription-form-card__buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  padding: 12px 0;
  border-bottom: 1px solid $color-linen;

  .subscription-form-card--communicator & {
    background: transparent;
  }

  .btn {
    flex: 1;
    min-width: 120px;
  }
}

.subscription-form-card__row.subscription-table__row--blue-bg {
  background: rgba(44, 82, 130, 0.08);
  border-bottom: 1px solid $color-linen;
  padding: 12px 0;

  a {
    color: var(--fs-dark-teal, $brand-verdigris);
    text-decoration: none;
    font-weight: 500;
  }

  a:hover {
    border-bottom: 1px solid var(--fs-dark-teal, $brand-verdigris);
  }
}

.subscription-form-card__row.subscription-table__row--navy-bg {
  background: $la-navy;
  color: #fff;
  border-bottom: none;
  padding: 12px;
  margin: 0 -20px -16px -20px;
  border-radius: 0 0 20px 20px;

  .subscription-form-card--supporter &,
  .subscription-form-card--eval & {
    border-radius: 0;
  }

  a {
    color: $brand-honey-bronze;
  }

  .subscribe-trial-btn {
    width: 100%;
  }
}

.subscription-form-cards .subscription-table__cloud-extras-right a[href*='blog.mylingolinq.com'],
.subscription-form-cards a[href*='blog.mylingolinq.com'] {
  color: var(--fs-dark-teal, $brand-verdigris);
  text-decoration: none;
  font-weight: 500;
  border-bottom: 1px solid transparent;
  transition: border-color 0.12s ease;
}

.subscription-form-cards a[href*='blog.mylingolinq.com']:hover {
  border-bottom-color: var(--fs-dark-teal, $brand-verdigris);
}

/* Cloud Extras modal trigger (replaces blog link) – match previous link appearance */
.subscription-form__cloud-extras-link {
  padding: 0;
  margin: 0;
  border: none;
  background: none;
  font: inherit;
  color: var(--fs-dark-teal, $brand-verdigris);
  text-decoration: none;
  font-weight: 500;
  border-bottom: 1px solid transparent;
  transition: border-color 0.12s ease;
  cursor: pointer;

  &:hover {
    border-bottom-color: var(--fs-dark-teal, $brand-verdigris);
  }
}

.subscription-form__premium-symbol-image {
  float: left;
  width: 60px;
  margin-left: 20px;
}

/* la-* classes used in subscription-form: features list and sale badge */
.subscription-form-cards .la-pricing-card__features {
  list-style: none;
  margin: 12px 0 0;
  padding: 0;
  text-align: left;
  width: 100%;
  font-size: 15px;
  line-height: 1.5;
  color: $brand-charcoal-dark;

  li {
    padding: 0.35em 0;
    border-bottom: 1px solid rgba(0, 0, 0, 0.06);

    &:last-child {
      border-bottom: none;
    }
