/* Applied in: speak-menu component - speak options dropdown */
/* ── Modern Speak Menu ─────────────────────────────────── */
.modal-content:has(.md-speak-menu) {
  border-radius: 20px;
  border: none;
  overflow: hidden;
  background: #ffffff;
}
.md-speak-menu {
  padding: 16px 20px 12px !important;
  font-size: 16px;
  background: #ffffff;
  border-radius: 20px;
  overflow: hidden;
}

/* Header */
.md-speak-menu__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 12px;
  margin-bottom: 14px;
  border-bottom: 1px solid rgba($la-navy, 0.15);
}
.md-speak-menu__title {
  font-size: 1.25rem; /* 20px — meets AAC ~30% larger than web default */
  font-weight: 700;
  color: $la-navy;
}
.md-speak-menu__close {
  width: 44px; /* WCAG 2.5.5 — minimum touch target 44×44 */
  height: 44px;
  border: 1px solid rgba($la-navy, 0.12);
  background: rgba($la-navy, 0.05);
  border-radius: 50%;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: $brand-slate-gray;
  transition: background 0.12s ease, color 0.12s ease, transform 0.12s ease;
  padding: 0;
}
.md-speak-menu__close:hover {
  background: rgba($la-navy, 0.10);
  color: $brand-charcoal-dark;
  transform: scale(1.05);
}

/* Sections */
.md-speak-menu__section {
  margin-bottom: 20px;
}
.md-speak-menu__section--punctuation {
  border-top: 1px solid rgba($la-navy, 0.15);
  margin-top: 16px;
  padding-top: 16px;
}
.md-speak-menu__section-label {
  font-size: 1rem; /* 16px — large enough with uppercase treatment */
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: rgba($la-navy, 0.85); /* ~7.8:1 contrast on white — passes AAA */
  margin-bottom: 8px;
  padding-left: 2px;
}

/* Button rows */
.md-speak-menu__row {
  display: grid;
  gap: 8px;
}
.md-speak-menu__row--1 { grid-template-columns: 1fr; }
.md-speak-menu__row--2 { grid-template-columns: repeat(2, 1fr); }
.md-speak-menu__row--3 { grid-template-columns: repeat(3, 1fr); }
.md-speak-menu__row--5 { grid-template-columns: repeat(5, 1fr); }
.md-speak-menu__row--locale {
  grid-template-columns: repeat(auto-fill, minmax(148px, 1fr));
}

/* Speak menu: board tools (speak mode + languages) above main actions */
.md-speak-menu__section-wrap--board-tools {
  border-bottom: 1px solid rgba($la-navy, 0.15);
  margin-bottom: 16px;
  padding-bottom: 4px;
}
.md-speak-menu__btn--text-row {
  min-height: 52px;
  justify-content: center;
  padding: 12px 10px;
}
.md-speak-menu__btn--locale-chip {
  min-height: 48px;
  padding: 10px 8px;
}
.md-speak-menu__btn-label--locale {
  font-size: 1rem; /* 16px — meets WCAG AA body text, bold compensates for slightly under 18px */
  line-height: 1.35;
  font-weight: 600;
  word-break: break-word;
}

/* Individual buttons */
.md-speak-menu__btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 14px 8px;
  cursor: pointer;
  text-align: center;
  position: relative;
  border-radius: 14px;
  border: 1px solid rgba($la-navy, 0.08);
  background: #E9EBED;
  transition: background 0.12s ease, box-shadow 0.12s ease;
  color: $la-navy;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.06);
}
.md-speak-menu__btn:hover {
  background: #F2F3F5;
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.10);
}
.md-speak-menu__btn:active {
  background: #DFE1E4;
  transform: scale(0.97);
}
.md-speak-menu__btn svg {
  flex-shrink: 0;
  stroke: url(#md-speak-icon-grad);
}
.md-speak-menu__btn-label {
  font-size: 1.125rem; /* 18px — AAC requirement */
  font-weight: 600;
  line-height: 1.35;
  color: $brand-charcoal-dark;
}
.md-speak-menu__badge {
  position: absolute;
  top: 4px;
  right: 6px;
  background: $brand-danger;
  color: #fff;
  font-size: 14px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 10px;
  line-height: 1;
}
.md-speak-menu__punctuation {
  font-size: 42px;
  line-height: 36px;
  display: block;
  color: $brand-charcoal-dark;
  font-weight: 700;
}
.md-speak-menu__punctuation--sm {
  font-size: 22px;
  line-height: 28px;
}
#menu_punctuation_button .md-speak-menu__punctuation--sm {
  background: linear-gradient(135deg, $brand-verdigris, $brand-dusty-denim);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Bottom actions */
.md-speak-menu__bottom {
  padding-top: 8px;
  margin-top: 4px;
}
.md-speak-menu__bottom-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 10px 12px;
  background: transparent;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  font-size: 15px;
  font-weight: 500;
  color: $la-navy;
  transition: background 0.12s ease;
  text-align: left;
}
.md-speak-menu__bottom-btn:hover {
  background: rgba(255, 255, 255, 0.20);
}
.md-speak-menu__bottom-btn--remember {
  color: $brand-verdigris;
  font-weight: 600;
}
.md-speak-menu__bottom-btn--action {
  /* WCAG AA fix — was $brand-dusty-denim on white = 3.49:1. */
  color: $brand-dusty-denim-aa;
  font-weight: 600;
}
.md-speak-menu__bottom-btn--remembered {
  font-size: 14px;
  color: $brand-charcoal-dark;
}
.md-speak-menu__bottom-btn--remembered .md-speak-menu__remembered-text {
  font-size: 16px;
  font-weight: 600;
  color: $la-navy;
}
.md-speak-menu__bottom-btn svg {
  flex-shrink: 0;
  color: inherit;
  opacity: 0.7;
}

/* Legacy list fallback */
.md-speak-menu__legacy-list {
  list-style: none;
  margin: 0;
  padding: 8px 0;
}
.md-speak-menu__legacy-list li { padding: 0; }
.md-speak-menu__legacy-list a {
  display: block;
  padding: 12px 16px;
  color: $la-navy;
  font-size: 16px;
  font-weight: 500;
  text-decoration: none;
  border-radius: 10px;
  transition: background 0.12s ease;
}
.md-speak-menu__legacy-list a:hover {
  background: rgba($brand-verdigris, 0.06);
}
.md-speak-menu__legacy-context {
  padding: 12px 16px 4px;
  font-size: 14px;
  color: rgba(75, 78, 92, 0.55);
}

@media (max-width: 768px) {
  .md-speak-menu__row--3 {
    grid-template-columns: repeat(2, 1fr);
  }
}

