.time_block_rows {
  .time_block {
    float: left;
    display: block;
    width: calc(2% + 1px);
    overflow: hidden;
    margin-left: -1px;
    border: 1px solid #eee;
    position: relative;
    overflow: hidden;
    &:before {
      content: "";
      position: absolute;
      top: 0;
      left: 0;
      border-left: 100px solid #fff;
      width: 0px;
      height: 100px;
    }
    &:nth-child(2n+2) {
      border-left-color: #aaa;
    }
    &:nth-child(49) {
      border-right-color: #aaa;
    }
    &.level_10 {
      &:before {
        border-left-color: #428bca !important;
      }
    }
    &.level_9 {
      &:before {
        border-left-color: #428bca !important;
      }
    }
    &.level_8 {
      &:before {
        border-left-color: #5195cf !important;
      }
    }
    &.level_7 {
      &:before {
        border-left-color: #60a0d6 !important;
      }
    }
    &.level_6 {
      &:before {
        border-left-color: #71ade0 !important;
      }
    }
    &.level_5 {
      &:before {
        border-left-color: #84b7e3 !important;
      }
    }
    &.level_4 {
      &:before {
        background: #9ac7ed !important;
      }
    }
    &.level_3 {
      &:before {
        border-left-color: #a8ceed !important;
      }
    }
    &.level_2 {
      &:before {
        border-left-color: #bddaf3 !important;
      }
    }
    &.level_1 {
      &:before {
        border-left-color: #d7e8f7 !important;
      }
    }
  }
  .time_block_top {
    float: left; 
    text-align: center; 
    width: 4%; 
    color: #aaa;
  }
  .time_block_left {
    float: left; 
    width: 4%; 
    color: #aaa;
    overflow: hidden;
  }
  .time_block_row {
    margin-bottom: -1px;
    &:hover {
      .time_block_left {
        color: #444;
        font-weight: bold;
      }
      .time_block {
        border-top-color: #aaa;
      }
      + .time_block_row .time_block {
        border-top-color: #aaa;
      }
    }
    &:last-child:hover {
      .time_block {
        border-bottom-color: #aaa;
      }
    }
  }
  &.wider {
    .time_block_row {
      .face {
        opacity: 0.5;
      }
      &:hover .face {
        opacity: 1.0;
      }
    }
    .time_block_left {
      width: 16%;
      line-height: 30px;
      
      .face {
        display: block;
        margin: 0 auto;
        width: 35px;
        height: 35px;
        background-image: url(../images/faces.png);
        background-size: auto 35px;
        &.happy {
          background-position-x: -35px;
        }
        &.neutral {
          background-position-x: -69px;
        }
        &.sad {
          background-position-x: -103px;
        }
      }
    }
    .time_block {
      width: calc(6% + 1px);
      border-left-color: #eee;
      line-height: 35px;
    }
    .dates {
      .time_block {
        color: #aaa;
        border: 0;
        &:nth-child(2n+1) {
          visibility: hidden;
        }
      }
    }
  }
}
