  align-items: center;
  flex: 1;
  min-width: 0;
  padding: 0 4px;
}

.ll-bento-bar__brand {
  justify-content: flex-start;
  gap: 10px;
  flex: 0 0 auto;
  width: max-content;
  min-width: 0;
  margin-left: -2px;
}

.ll-bento-brand-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 8px 20px;
  border-radius: 999px;
  text-decoration: none;
  color: inherit;
  outline: none;
  transition: background 0.2s ease, color 0.2s ease;
  width: max-content;
  background: rgba(225, 228, 238, 0.98);

  &:focus:not(:focus-visible) {
    outline: none;
  }

  &:hover {
    background: #fff;
    text-decoration: none;
  }
}

.ll-bento-bar__brand-sep {
  color: inherit;
  opacity: 0.7;
  font-size: 14px;
  flex-shrink: 0;
  margin: 0 2px;
}

.ll-bento-bar__brand-home {
  font-size: 14px;
