// Help me… buttons: $ll-bento-help-btn-blue defined in _variables.scss

/* Getting Started - progress block */
.ll-bento-getting-started {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 16px;
  border-radius: var(--ll-bento-radius-md);
  background: rgba(255, 255, 255, 0.38);
  border: 1px solid rgba(255, 255, 255, 0.5);
  backdrop-filter: blur(var(--ll-bento-material-blur));
  -webkit-backdrop-filter: blur(var(--ll-bento-material-blur));
  transform: translateZ(0);
  box-shadow: 0 4px 16px rgba(19, 29, 56, 0.04),
              var(--ll-bento-material-inner-highlight),
              var(--ll-bento-material-counter-shadow);
  text-decoration: none;
  color: var(--ll-bento-ink);
  min-width: 140px;
  max-width: 240px;

  &--main {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    max-width: none;
    margin: 0 var(--ll-bento-content-inset) 14px;
    padding: 24px 28px;
    background: linear-gradient(135deg, rgba(255, 252, 250, 0.38) 0%, rgba(248, 250, 253, 0.32) 100%);
    border-radius: var(--ll-bento-radius-xl);
    border: 1px solid rgba(255, 255, 255, 0.5);
    box-shadow: 0 4px 16px rgba(19, 29, 56, 0.04),
                var(--ll-bento-material-inner-highlight),
                var(--ll-bento-material-counter-shadow);
    transition: background 0.2s ease, box-shadow 0.3s var(--ll-bento-ease-in-out), transform 0.3s var(--ll-bento-ease-in-out);

    &:hover {
      background: linear-gradient(135deg, rgba(248, 250, 253, 0.42) 0%, rgba(240, 244, 250, 0.36) 100%);
      box-shadow: 0 8px 24px rgba(19, 29, 56, 0.08),
                  var(--ll-bento-material-inner-highlight),
                  var(--ll-bento-material-counter-shadow);
      transform: translateY(-3px);
      text-decoration: none;
      color: inherit;
    }

    &:active,
    &:focus-visible,
    &:visited {
      text-decoration: none;
    }

    &:active {
      transform: translateY(-1px);
      box-shadow: 0 6px 20px rgba(19, 29, 56, 0.06),
                  var(--ll-bento-material-inner-highlight),
                  var(--ll-bento-material-counter-shadow);
    }

  }

  &__image {
    width: 56px;
    height: 56px;
    flex-shrink: 0;
    object-fit: contain;

    .ll-bento-getting-started--main & {
      width: 64px;
      height: 64px;
      margin-left: -12px;
    }
  }

  &__body {
    display: flex;
    flex-direction: column;
    gap: 4px;
    flex: 1;
    min-width: 0;
  }

  &__header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 12px;
  }

  &__divider {
    display: none;
  }

  /* Base styles - exclude --main which uses action-card-style effects */
  &:not(.ll-bento-getting-started--main) {
    outline: 2px solid transparent;
    outline-offset: 2px;
    transition: background 0.2s ease, border-color 0.2s ease, box-shadow 0.25s var(--ll-bento-ease-in-out), transform 0.25s var(--ll-bento-ease-in-out), outline-color 0.2s var(--ll-bento-ease-out);

    &:active,
    &:focus-visible,
    &:visited {
      text-decoration: none;
    }

    &:focus:not(:focus-visible) {
      outline: none;
      outline-offset: 0;
    }

    &:active {
      transform: translateY(1px);
      box-shadow: 0 1px 4px rgba(19, 29, 56, 0.05),
                  inset 0 1px 2px rgba(19, 29, 56, 0.04);
    }

    &:hover {
      background: rgba(248, 250, 253, 0.95);
      border-color: rgba(30, 36, 48, 0.24);
      text-decoration: none;
    }
  }

  &__stage {
    display: block;
    font-size: 14px;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: var(--ll-bento-muted, rgba(15, 23, 42, 0.6));
    margin-bottom: 4px;

    .ll-bento-getting-started--main & {
      font-size: 14px;
    }
  }

  &__title {
    font-size: 14px;
    font-weight: 600;

    .ll-bento-getting-started--main & {
      font-size: 18px;
      font-weight: 700;
      margin: 0;
      line-height: 1.3;
    }
    color: var(--ll-bento-ink);
  }

  &__hint {
    font-size: 14px;
    color: var(--ll-bento-muted);

    .ll-bento-getting-started--main & {
      font-size: 14px;
      line-height: 1.4;
      text-align: right;
      color: #3D7A5C;
    }
  }

  &__stage {
    .ll-bento-getting-started--main & {
      color: #3D7A5C;
    }
  }

  &__btn {
    flex-shrink: 0;
    padding: 12px 20px;
    width: 260px;
    min-width: 260px;
    text-align: center;
    border-radius: 999px;
