    border: 1px solid rgba(210, 214, 224, 0.5);

    &--speak {
      /* Much lighter tint of active action button color #3D7A5C */
      background: var(--ll-bento-icon-gloss), rgba(61, 122, 92, 0.14);
      border-color: rgba(61, 122, 92, 0.28);
    }

    &--reports {
      background: var(--ll-bento-icon-gloss), rgba(220, 238, 242, 0.85);
