    }

    &--green-yellow {
      background: var(--ll-bento-icon-gloss), rgba(245, 242, 228, 0.85);
      border-color: rgba(230, 225, 205, 0.5);
    }

    &--account {
      background: var(--ll-bento-icon-gloss), rgba(235, 235, 245, 0.85);
