  &--with-btn {
    justify-content: space-between;
  }

  &__action-btn {
    flex-shrink: 0;
    min-width: 100px;
    width: 100px;
    box-sizing: border-box;
    padding: 10px 16px;
    border-radius: 999px;
    font-size: 14px;
    font-weight: 600;
    background: $bento-ink-light;
    color: rgba(30, 36, 48, 0.9);
