/* Card components - hero and feature tiles */
.ll-bento-card {
  border-radius: var(--ll-bento-radius-xl);
  background: var(--ll-bento-card);
  border: 1px solid var(--ll-bento-stroke);
  box-shadow: var(--ll-bento-shadow-md);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  overflow: hidden;

  &__row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    padding: 18px;
  }

  &__title {
    margin: 0;
    font-size: 20px;
    letter-spacing: -0.02em;
  }

  &__subtitle {
    margin: 6px 0 0;
    color: var(--ll-bento-muted);
    font-size: 14px;
  }

  &--hero {
    background: linear-gradient(
        135deg,
        rgba(255, 255, 255, 0.80),
        rgba(255, 255, 255, 0.62)
      );
  }

  &--feature {
    padding: 0;
  }
}

/* Primary action button - distinct from Bootstrap .btn */
.ll-bento-btn {
  border: none;
  cursor: pointer;
  border-radius: 999px;
  padding: 12px 16px;
  font-weight: 700;
  font-size: 14px;
  letter-spacing: -0.01em;
  outline: 2px solid transparent;
  outline-offset: 2px;
  transition: transform 0.25s var(--ll-bento-ease-in-out), box-shadow 0.25s var(--ll-bento-ease-in-out), outline-color 0.2s var(--ll-bento-ease-out);

  &--primary {
    color: rgba(255, 255, 255, 0.98);
    background: linear-gradient(135deg, #3db8bc 0%, #4eb5ff 50%, #5f7cff 100%);
    box-shadow: 0 12px 28px rgba(61, 184, 188, 0.35), 0 4px 12px rgba(78, 181, 255, 0.2);
    border: 1px solid rgba(255, 255, 255, 0.25);
    min-width: 152px;

    &:active {
      transform: translateY(1px);
      box-shadow: 0 4px 12px rgba(61, 184, 188, 0.25), 0 2px 6px rgba(78, 181, 255, 0.15);
    }
  }
}

/* Feature grid - 2-column layout for action tiles */
.ll-bento-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.ll-bento-feature {
  display: grid;
  grid-template-columns: 44px 1fr;
  gap: 12px;
  padding: 16px;

  &__icon {
    width: 44px;
    height: 44px;
    border-radius: 16px;
    box-shadow: 0 4px 12px rgba(19, 29, 56, 0.06), var(--ll-bento-icon-rim);
    border: 1px solid rgba(210, 214, 224, 0.5);

    &--reports {
      background: var(--ll-bento-icon-gloss), rgba(220, 238, 242, 0.85);
    }

    &--ideas {
      background: var(--ll-bento-icon-gloss), rgba(228, 235, 250, 0.85);
    }

    &--modeling {
      background: var(--ll-bento-icon-gloss), rgba(228, 235, 250, 0.85);
    }

    &--extras {
      background: var(--ll-bento-icon-gloss), rgba(245, 232, 238, 0.85);
    }
  }

  &__title {
    margin: 0;
    font-size: 15px;
    letter-spacing: -0.02em;
  }

  &__sub {
    margin: 5px 0 0;
    color: var(--ll-bento-muted);
    font-size: 14px;
  }

  &__meta {
    margin: 10px 0 0;
    font-size: 14px;
    color: rgba(30, 36, 48, 0.70);
  }
}

/* Bottom dock - primary navigation bar; fixed height so it never stretches */
.ll-bento-dock {
  position: absolute;
  left: calc(15px + var(--ll-bento-content-inset)); /* Bootstrap col padding + content inset to align with tabs */
  right: calc(15px + var(--ll-bento-content-inset));
  bottom: 12px;
  height: 58px !important;
  min-height: 58px !important;
  max-height: 58px !important;
  flex-shrink: 0;
  box-sizing: border-box;
  border-radius: 999px;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.38) 0%, rgba(248, 250, 253, 0.32) 100%);
  border: 1px solid rgba(255, 255, 255, 0.5);
  backdrop-filter: blur(var(--ll-bento-material-blur));
  -webkit-backdrop-filter: blur(var(--ll-bento-material-blur));
  transform: translateZ(0);
  box-shadow: 0 4px 16px rgba(19, 29, 56, 0.04),
              0 8px 24px rgba(19, 29, 56, 0.08),
              var(--ll-bento-material-inner-highlight),
              var(--ll-bento-material-counter-shadow) !important;

  display: flex;
  align-items: center;
  justify-content: space-evenly;
  gap: 12px;
  padding: 8px 16px;
  overflow: hidden;
}

.ll-bento-dock__item {
  border: none;
  background: transparent;
  height: 42px;
  border-radius: 999px;
  padding: 0 14px;
  cursor: pointer;
  display: flex;
  align-items: center;
  flex: 1 1 0;
  min-width: 0;
  justify-content: center;
  outline: 2px solid transparent;
  outline-offset: 2px;
  transition: outline-color 0.2s var(--ll-bento-ease-out);

  .ll-bento-dock__label {
    font-size: 14px;
    color: rgba(30, 36, 48, 0.98);
    font-weight: 600;
    letter-spacing: -0.01em;
  }

  &--active {
    background: rgba(245, 247, 255, 0.85);
    border: 1px solid rgba(75, 121, 255, 0.16);

    .ll-bento-dock__label {
      color: rgba(30, 36, 48, 1);
    }
  }
}

.ll-bento-dock__supervisor {
  flex: 0.65 1 0;
  justify-content: flex-start;
  padding: 0 16px;

  .ll-bento-dock__label {
    text-align: left;
  }

  &:hover {
    background: rgba(240, 242, 245, 0.9);
  }
}

.ll-bento-dock__supervisor,
.ll-bento-dock__logging {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  width: 100%;

  .ll-bento-dock__supervisor-label {
    font-size: 14px;
    font-weight: 500;
    color: rgba(30, 36, 48, 0.90);
    letter-spacing: 0.08em;
    text-transform: uppercase;
    flex-shrink: 0;
  }

  .ll-bento-dock__label {
    flex: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

.ll-bento-dock__logging {
  flex: 1.35 1 0;
  border: none;
  background: transparent;
  padding: 0;
  cursor: default;
  gap: 8px;
}

.ll-bento-dock__logging-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  border: none;
  background: transparent;
  padding: 0 8px 0 16px;
  height: 42px;
  border-radius: 999px;
  cursor: pointer;
  font: inherit;
  color: inherit;
  outline: 2px solid transparent;
  outline-offset: 2px;
  transition: outline-color 0.2s var(--ll-bento-ease-out);

  &:hover {
    background: rgba(240, 242, 245, 0.9);
  }
}

.ll-bento-dock__logging-sep {
  color: rgba(30, 36, 48, 0.90);
  font-size: 14px;
  flex-shrink: 0;
  margin-left: -8px;
}

.ll-bento-dock__logging-last {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
  color: rgba(30, 36, 48, 0.98);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 1;
  min-width: 0;
}

.ll-bento-dock__logging-link {
  color: rgba(75, 121, 255, 0.9);
  text-decoration: none;

  &:hover {
    color: rgba(75, 121, 255, 1);
    text-decoration: underline;
  }
}

.ll-bento-dock__logging-last-label {
  font-size: 14px;
  font-weight: 500;
  color: rgba(30, 36, 48, 0.90);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  flex-shrink: 0;
}

.ll-bento-dock__cta {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 42px;
  border-radius: 999px;
  border: 1px solid rgba(220, 180, 170, 0.5);
  background: linear-gradient(135deg, rgba(230, 165, 155, 0.95) 0%, rgba(255, 225, 205, 0.95) 100%);
  color: rgba(50, 40, 45, 0.95);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: -0.01em;
  padding: 0 18px;
  cursor: pointer;
  box-shadow: 0 6px 16px rgba(210, 160, 150, 0.2);
  flex-shrink: 0;
  outline: 2px solid transparent;
  outline-offset: 2px;
  transition: transform 0.25s var(--ll-bento-ease-in-out), box-shadow 0.25s var(--ll-bento-ease-in-out), outline-color 0.2s var(--ll-bento-ease-out), background 0.2s var(--ll-bento-ease-out);

  &:hover {
    // SPEC R3: legitimate reset — :hover state, not a focus reset. Cancels the
    // animated transparent outline above so it does not flash on hover.
    outline: none;
    text-decoration: none;
    background: linear-gradient(135deg, rgba(235, 183, 175, 0.95) 0%, rgba(255, 231, 215, 0.95) 100%);
  }

  &:active {
    transform: translateY(1px);
    box-shadow: 0 2px 8px rgba(210, 160, 150, 0.15),
                inset 0 1px 2px rgba(19, 29, 56, 0.06);
  }
}

/* Mid-day mode - icy blue light gray, text converted for contrast */
