  color: $bento-ink-light;
  transition: background 0.4s var(--ll-bento-ease-in-out), color 0.3s ease;
  --ll-bento-bg: #c4c8ce;
  --ll-bento-ink: #{$bento-ink-light};
  --ll-bento-muted: rgba(230, 236, 242, 0.72);
  --ll-bento-card: rgba(100, 110, 125, 0.65);
  --ll-bento-card-strong: rgba(110, 120, 138, 0.75);
  --ll-bento-stroke: rgba(255, 255, 255, 0.08);
  --ll-bento-shadow-lg: 0 18px 50px rgba(0, 0, 0, 0.25);
  --ll-bento-shadow-md: 0 10px 28px rgba(0, 0, 0, 0.15);
  --ll-bento-shadow-sm: 0 6px 16px rgba(0, 0, 0, 0.15);

  background: radial-gradient(1400px 900px at 10% 10%, rgba(189, 198, 208, 0.5) 0%, transparent 50%),
              radial-gradient(1200px 800px at 90% 30%, rgba(186, 200, 213, 0.4) 0%, transparent 55%),
