/* Focus ring - keyboard focus only (no outline on mouse click/blur to prevent flash) */
.ll-bento-app-shell {
  .ll-bento-tab:focus-visible,
  .ll-bento-btn:focus-visible,
  .ll-bento-brand-link:focus-visible,
  .ll-bento-icon-btn:focus-visible,
  .ll-bento-search:focus-visible,
  .ll-bento-getting-started:focus-visible,
  .ll-bento-action-card:focus-visible,
  .ll-bento-hero-card:focus-visible,
  .ll-bento-home-board-card:focus-visible,
  .ll-bento-dock__item:focus-visible,
  .ll-bento-dock__cta:focus-visible,
  .ll-bento-dock__logging-btn:focus-visible,
  .ll-bento-action-card__action-btn:focus-visible,
  .ll-bento-hero-card__btn:focus-visible,
  .ll-bento-home-board-card__btn:focus-visible,
  .ll-bento-getting-started__btn:focus-visible {
    @include focus-ring;
  }

  /* Topbar elements use outline: none by default; only show ring on focus-visible */
  .ll-bento-brand-link:focus-visible,
  .ll-bento-icon-btn:focus-visible,
  .ll-bento-search:focus-visible {
    @include focus-ring;
  }
}

/* Default theme – style guide colors and typography
   Teal #4ECDC4 (accent), Dark Teal #2A9D8F (accessible), White #FFFFFF, Light Gray #F0F0F0, Coral #FF6B47
   Typography: Lexend (headings), Atkinson Hyperlegible (body), Source Code Pro (data) */
.ll-bento-app-shell--default,
.ll-bento-app-shell--default {
  --ll-bento-bg: #FFFFFF;
  --ll-bento-ink: #1e2430;
  --ll-bento-muted: rgba(30, 36, 48, 0.7);
  font-family: "Atkinson Hyperlegible", "Open Sans", Calibri, sans-serif;
  background: #FFFFFF;
  color: var(--ll-bento-ink);
}

/* Light mode (default) – brand palette */
.ll-bento-app-shell--default {
  --ll-bento-primary-1: #3d7a5c;
  --ll-bento-primary-2: #7eb8e0;
  --ll-bento-primary-3: #{$brand-smart-blue};
  --ll-bento-secondary: #eaf2fb;
  --ll-bento-functional-green: #3d7a5c;
  --ll-bento-functional-coral: #d4a84b;
}

/* Gold theme – teal/coral accent */
.ll-bento-app-shell--default {
  --ll-bento-primary-1: #{$la-teal};
  --ll-bento-functional-green: #{$brand-verdigris};
  --ll-bento-functional-coral: #FF6B47;
}

/* #index_view only exists when the index route is active (template in app/templates/index.hbs).
   When you navigate to landing, user profile, or a board, the outlet renders
   a different template and #index_view is not in the DOM. Use white so no teal bar shows above the footer;
   the teal bar below the navbar is from #content.index.with_user { border-top: 15px solid #2A9D8F }. */
#within_ember.bento-default-mode-active #index_view {
  background: #FFFFFF;
}

#within_ember.bento-default-mode-active #index_view {
