/* Demo: color circles on bento bar (default theme only) – change ll-bento-main-content bg for client preview */
.ll-bento-bar--default .ll-bento-bar__demo-colors {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-right: 8px;
}
.ll-bento-demo-color {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  padding: 0;
  border: 2px solid rgba(0, 0, 0, 0.15);
  cursor: pointer;
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}
