  .nav-icon {
    font-size: 16px;
    width: 22px;
    text-align: center;
    flex-shrink: 0;
  }

  // ── Main content ─────────────────────────────────────────────────────────
  main.main {
    grid-area: main;
    overflow-y: auto;
    padding: $aac-spacing-28;
    background: $color-background;
  }

  .phrase-bar {
    background: $indigo;
    border-radius: $aac-radius-xl;
    padding: $aac-spacing-16 $aac-spacing-20;
    display: flex;
    align-items: center;
    gap: $aac-spacing-14;
    margin-bottom: $aac-spacing-24;
    min-height: 64px;
    box-shadow: 0 2px 12px rgba($indigo, 0.18);
    min-width: 50rem;
    width: fit-content;
    margin-left: auto;
    margin-right: auto;
