    &.clinical { background: $cat-people-bg;      color: $cat-people-text; }
    &.practice { background: $cat-actions-bg;     color: $cat-actions-text; }
    &.social   { background: $cat-descriptors-bg; color: $cat-descriptors-text; }
  }
