// =============================================================================
// LANDING-ALT PAGE — Modern App-Shell Layout
// Marketing landing page redesigned with speech-page aesthetics.
// =============================================================================

/* Hide the main app header on the alt page (footer is shown, sticky at bottom) */
#within_ember.landing-alt-route #setup_footer {
  display: none !important;
}

/* Show navbar on landing-alt; #content padding-top reserves space below fixed navbar */
#within_ember.landing-alt-route .la-wrapper {
  top: 0;
  height: 100vh;
  padding-top: 0;
  padding-bottom: 0;
  box-sizing: border-box;
}

/* Footer on landing-alt: sticky at bottom, reserve space in scroll area */
#within_ember.landing-alt-route .page-footer {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 1000;
}
#within_ember.landing-alt-route .la-wrapper {
  padding-bottom: var(--bottombar-height);
  box-sizing: border-box;
}


/* Whenever landing-alt page (.la-wrapper) is shown (index or /landing-alt),
   ensure footer is above it and la-wrapper reserves space at bottom */
#within_ember:has(.la-wrapper) .page-footer {
  z-index: 1001;
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  display: flex !important;
  visibility: visible !important;
}
#within_ember:has(.la-wrapper) .la-wrapper {
  padding-bottom: 0;
  box-sizing: border-box;
}

/* Footer rendered inside landing-alt-page: fix to bottom of viewport */
.la-wrapper .la-page-footer-wrap {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 1001;
  padding-bottom: env(safe-area-inset-bottom, 0);
}
.la-wrapper .la-page-footer-wrap .page-footer {
  margin: 0;
}

.la-wrapper .page-footer .page-footer__developers-link {
  display: none;
}



/* LA = landing-alt prefix for all new classes */
/* Page background: fluctuating gradient (replaces orbs) so content has clear contrast and hierarchy */
@keyframes la-gradient-fluctuate {
  0%, 100% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
}

.la-wrapper {
  position: fixed;
  inset: 0;
  z-index: 999;
  background: linear-gradient(
    160deg,
    #f8f7f5 0%,
    #faf9f7 15%,
    #f5f4f2 30%,
    #fcfbf9 45%,
    #f7f6f4 60%,
    #fafaf8 75%,
    #f6f5f3 90%,
    #f8f7f5 100%
  );
  background-size: 200% 200%;
  animation: la-gradient-fluctuate 20s ease-in-out infinite;
  overflow-y: auto;
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;

  .app-shell {
    font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
    display: block;
    min-height: 100%;
    height: auto;
    overflow: visible;
    position: relative;
  }
}

/* Landing-alt: app-shell and wrapper use same gradient as hero-background (.la-hero-card).
   :has(#la-main) matches both index and /landing-alt route. */
#within_ember:has(#la-main) .la-wrapper {
  background: linear-gradient(180deg, #{color.adjust($brand-stone-100, $lightness: 10%)} 0%, #{color.adjust($brand-stone-200, $lightness: 10%)} 50%, #{color.adjust($brand-stone-300, $lightness: 10%)} 100%);
  background-size: auto;
  animation: none;
}
#within_ember:has(#la-main) .la-wrapper .app-shell {
  background: linear-gradient(180deg, #{color.adjust($brand-stone-100, $lightness: 10%)} 0%, #{color.adjust($brand-stone-200, $lightness: 10%)} 50%, #{color.adjust($brand-stone-300, $lightness: 10%)} 100%);
}
#within_ember:has(#la-main) .la-wrapper .la-main {
  background: linear-gradient(180deg, #{color.adjust($brand-stone-100, $lightness: 10%)} 0%, #{color.adjust($brand-stone-200, $lightness: 10%)} 50%, #{color.adjust($brand-stone-300, $lightness: 10%)} 100%);
}

// Parallax image only in the section from "Included in every plan" through footer
.la-parallax-zone {
  position: relative;
  border-radius: 24px;
  overflow: hidden;
  margin-top: 22px; /* breathing room: feature cards → Included in every plan (~80px total) */
  background-color: #f7fafc; /* matches page gradient where image doesn’t fill */
  background-image: url('/images/aac-user-front-page.png');
  background-size: contain;
  background-position: center center;
  background-repeat: no-repeat;
  background-attachment: fixed;

  &::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: 0;
    /* Light blue with a slight teal tint */
    background: linear-gradient(
      160deg,
      rgba(88, 158, 200, 0.14) 0%,
      rgba(208, 235, 248, 0.78) 45%,
      rgba(238, 248, 252, 0.76) 100%
    );
    pointer-events: none;
  }

  > .la-divider,
  > section {
    position: relative;
    z-index: 1;
  }
}

/* Motion safety: disable parallax for users who prefer reduced motion (WCAG, AAC/neurodivergent-friendly) */
@media (prefers-reduced-motion: reduce) {
  .la-parallax-zone {
    background-attachment: scroll !important;
  }
}

.la-wrapper--about,
.la-wrapper--pricing,
.la-wrapper--contact,
.la-wrapper--troubleshooting,
.la-wrapper--privacy {
  color: $brand-teal;
}

/* Privacy page: same background as authenticated-view workspace (md-shell) */
.la-wrapper.la-wrapper--privacy {
  background:
    radial-gradient(1200px 600px at 20% 20%, rgba(44, 183, 176, 0.12), transparent 55%),
    radial-gradient(1200px 600px at 80% 15%, rgba(240, 106, 91, 0.10), transparent 60%),
    radial-gradient(1000px 700px at 60% 85%, rgba(91, 141, 239, 0.12), transparent 60%),
    var(--md-bg, #eef1f6);
  min-height: 100vh;
}

/* Privacy page: center all containers and hero */
.la-wrapper.la-wrapper--privacy .app-shell,
.la-wrapper.la-wrapper--privacy .la-main {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  max-width: 100%;
  box-sizing: border-box;
}
.la-wrapper.la-wrapper--privacy .la-main > section:not(.la-privacy-section) {
  width: 100%;
  max-width: 748px;
  margin-left: auto;
  margin-right: auto;
  box-sizing: border-box;
}

.la-wrapper.la-wrapper--privacy .la-main > section.la-privacy-section {
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 100%;
  margin-left: auto;
  margin-right: auto;
  box-sizing: border-box;
  padding: 40px;
  border-radius: 48px;
  background: rgba(255, 255, 255, 0.22);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid rgba(0, 0, 0, 0.04);
  box-shadow:
    0 4px 56px rgba(0, 0, 0, 0.012),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);

  @media (min-width: 768px) {
    width: 60%;
    max-width: 60%;
  }
}

// Thin 1px page divider — adopted as the project-wide separator style.
// (Was a 160px chunky gradient bar; superseded by the about/pricing thin-line treatment.)
.la-about-hero-separator {
  width: 100%;
  max-width: 100%;
  height: 1px;
  margin: 0 auto $aac-spacing-24;
  border: none;
  border-radius: 0;
  background: rgba(0, 0, 0, 0.12);
}

// Section divider — subtle gradient line between heading and content
.la-section-divider {
  width: 100%;
  max-width: 200px;
  height: 2px;
  border: none;
  margin: 0 auto 2rem;
  background: linear-gradient(90deg, transparent, #c5bfb3, transparent);
  border-radius: 2px;
}

// ── About/Pricing/Contact page light glass hero ───────────────────────────────
.la-wrapper.la-wrapper--about,
.la-wrapper.la-wrapper--pricing,
.la-wrapper.la-wrapper--contact,
.la-wrapper.la-wrapper--troubleshooting,
.la-wrapper.la-wrapper--privacy {

  // Glossy glass hero card (replaces dark navy) — keep contained, not full-bleed
  .la-hero-card {
    width: auto;
    max-width: fit-content;
    margin-left: auto;
    margin-right: auto;
    border-radius: calc(#{$aac-radius-xl} - 3px);
    background:
      // Top specular highlight — bright glossy streak
      linear-gradient(
        180deg,
        rgba(255, 255, 255, 0.95) 0%,
        rgba(255, 255, 255, 0.7) 6%,
        rgba(255, 255, 255, 0.55) 40%,
        rgba(255, 255, 255, 0.65) 100%
      );
    backdrop-filter: blur(24px) saturate(1.4);
    -webkit-backdrop-filter: blur(24px) saturate(1.4);
    border: 1px solid rgba(255, 255, 255, 0.6);
    border-top-color: rgba(255, 255, 255, 0.85);
    box-shadow:
      // Outer depth
      0 8px 32px rgba(0, 0, 0, 0.08),
      0 2px 6px rgba(0, 0, 0, 0.04),
      // Inner top highlight — glossy sheen
      0 1px 0 rgba(255, 255, 255, 0.8) inset,
      0 20px 40px -20px rgba(255, 255, 255, 0.5) inset;

    // Soften radial glows for light bg
    &::before {
      background: radial-gradient(circle, rgba($brand-honey-bronze, 0.08) 0%, transparent 50%);
    }

    &::after {
      background: radial-gradient(circle, rgba($la-teal, 0.07) 0%, transparent 50%);
    }
  }

  // Title 15% smaller, darkened blue for light bg (em gets gradient from .la-wrapper .la-hero-title em)
  .la-hero-title {
    font-size: 46px; // 54 × 0.85
    color: $indigo;

    @media (max-width: 1366px) { font-size: 36px; }
    @media (max-width: 1200px) { font-size: 31px; }
    @media (max-width: 1024px) { font-size: 27px; }
    @media (max-width: 768px)  { font-size: 26px; }
    @media (max-width: 480px)  { font-size: 22px; }
  }

  // Eyebrow badge — darken for light bg
  .la-hero-card .la-section-eyebrow-badge {
    color: $brand-stormy-teal;
    background: rgba($brand-teal, 0.1);
    border-color: rgba($brand-teal, 0.25);
  }

  // Troubleshooting page: content card and tables
  .la-troubleshooting-intro {
    max-width: 640px;
    margin-left: auto;
    margin-right: auto;
  }
  .la-troubleshooting-section {
    padding: 0 2rem 4rem;
  }
  .la-troubleshooting-card {
    max-width: 960px;
    margin: 0 auto;
    padding: 2rem;
  }
  .la-troubleshooting-content {
    color: $brand-charcoal-dark;
  }
  .la-troubleshooting-subtitle {
    margin-top: 2.5rem;
    margin-bottom: 1rem;
    font-size: 14px;
    color: $la-navy;
  }
  .la-troubleshooting-table {
    width: 100%;
    margin-bottom: 1rem;
    background: rgba(255, 255, 255, 0.5);
    border-radius: 8px;
    overflow: hidden;
    th, td {
      padding: 0.75rem 1rem;
      border-color: rgba($brand-teal, 0.12);
    }
    th {
      background: rgba($brand-teal, 0.08);
      color: $indigo;
      font-weight: 600;
    }
    tbody tr:hover td {
      background: rgba(255, 255, 255, 0.7);
    }
  }
  .la-troubleshooting-table--details {
    max-width: 500px;
  }
  .la-troubleshooting-cell {
    vertical-align: middle !important;
  }
  .la-troubleshooting-cell--narrow {
    width: 210px;
  }
  .la-troubleshooting-pass { color: $brand-stormy-teal; font-weight: 600; }
  .la-troubleshooting-partial { color: #b8860b; }
  .la-troubleshooting-fail { color: $brand-danger; }
  .la-troubleshooting-pending { color: $la-navy; }
  .la-troubleshooting-muted td {
    color: $brand-slate-gray;
  }
  .la-troubleshooting-pre {
    white-space: pre-line;
    max-height: 100px;
    overflow: auto;
    font-size: 14px;
  }
  .la-troubleshooting-pre--small {
    max-width: 200px;
    max-height: 100px;
    white-space: pre-wrap;
  }
  .la-troubleshooting-alpha-demo {
    position: relative;
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .la-troubleshooting-alpha-box {
    flex-shrink: 0;
    width: 20px;
    height: 20px;
    &.la-troubleshooting-alpha-box--blue {
      position: relative;
      width: 20px;
      height: 20px;
      margin-right: 5px;
      background: rgba(0, 0, 255, 1);
    }
    &.la-troubleshooting-alpha-box--red {
      background: rgba(255, 0, 0, 0.5);
    }
    &.la-troubleshooting-alpha-box--green {
      position: absolute;
      top: 0;
      left: 0;
      width: 10px;
      height: 20px;
      background: rgba(0, 255, 0, 0.5);
    }
  }
  .la-troubleshooting-actions {
    margin-top: 1.5rem;
  }
  .la-troubleshooting-content .la-btn--ghost {
    padding: 0.35rem 0.75rem;
    font-size: 14px;
    background: rgba($brand-charcoal-dark, 0.08);
    color: $brand-charcoal-dark;
    border: 1px solid rgba($brand-charcoal-dark, 0.2);
    &:hover {
      background: rgba($brand-charcoal-dark, 0.14);
      color: #1f2937;
    }
  }

  // Glass cards — glossy inner cards
  .la-about-glass-card {
    background:
      linear-gradient(
        180deg,
        rgba(255, 255, 255, 0.92) 0%,
        rgba(255, 255, 255, 0.78) 5%,
        rgba(255, 255, 255, 0.65) 50%,
        rgba(255, 255, 255, 0.75) 100%
      );
    border-color: rgba(255, 255, 255, 0.85);
    border-top-color: rgba(255, 255, 255, 0.95);
    box-shadow:
      0 12px 40px rgba(0, 0, 0, 0.10),
      0 4px 12px rgba(0, 0, 0, 0.06),
      0 1px 0 rgba(255, 255, 255, 0.9) inset,
      0 16px 32px -16px rgba(255, 255, 255, 0.5) inset;

    &:hover {
      background:
        linear-gradient(
          180deg,
          rgba(255, 255, 255, 0.96) 0%,
          rgba(255, 255, 255, 0.85) 5%,
          rgba(255, 255, 255, 0.72) 50%,
          rgba(255, 255, 255, 0.82) 100%
        );
      box-shadow:
        0 20px 56px rgba(0, 0, 0, 0.14),
        0 8px 20px rgba(0, 0, 0, 0.08),
        0 1px 0 rgba(255, 255, 255, 0.95) inset,
        0 20px 40px -20px rgba(255, 255, 255, 0.6) inset;
    }

    &--cta {
      background:
        linear-gradient(
          180deg,
          rgba(58, 107, 199, 0.14) 0%,
          rgba(58, 107, 199, 0.04) 5%,
          rgba(58, 107, 199, 0.02) 50%,
          rgba(58, 107, 199, 0.08) 100%
        );
      border-color: rgba(58, 107, 199, 0.2);
      border-top-color: rgba(58, 107, 199, 0.35);

      &:hover {
        background:
          linear-gradient(
            180deg,
            rgba(58, 107, 199, 0.2) 0%,
            rgba(58, 107, 199, 0.08) 5%,
            rgba(58, 107, 199, 0.04) 50%,
            rgba(58, 107, 199, 0.12) 100%
          );
      }
    }
  }

  // Card content — dark text for light glass (icon size from .la-wrapper .la-about-glass-card__icon)

  .la-about-glass-card__title {
    font-size: 23px; // 20 × 1.15
    color: $la-navy;
  }

  .la-about-glass-card__text {
    font-size: 18px; // 16 × 1.15
    color: $brand-charcoal-dark;

    strong { color: $indigo; }
    .la-challenge-cta { color: $la-navy; }
  }

  // CTA buttons inside about hero (literals: $la-* defined later in file)
  .la-hero-card .la-btn--primary {
    background: $brand-honey-bronze;
    color: $la-navy;
    border-color: $brand-honey-bronze;
    filter: brightness(1.02);
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.2), 0 2px 5px rgba(0, 0, 0, 0.1);

    &:hover {
      filter: brightness(0.96);
      transform: translateY(-2px);
      box-shadow: 0 8px 28px rgba(0, 0, 0, 0.25), 0 3px 8px rgba(0, 0, 0, 0.12);
      color: $la-navy;
    }
  }

  .la-hero-card .la-btn--ghost {
    color: $la-navy;
    border-color: rgba(42, 90, 168, 0.3);

    &:hover {
      background: rgba(42, 90, 168, 0.08);
    }
  }

  // CTA section — match hero glossy glass style
  .la-cta-section {
    width: min(580px, 90%);
    margin-left: auto;
    margin-right: auto;
    padding: $aac-spacing-32 $aac-spacing-40;
    background:
      linear-gradient(
        180deg,
        rgba(255, 255, 255, 0.95) 0%,
        rgba(255, 255, 255, 0.7) 6%,
        rgba(255, 255, 255, 0.55) 40%,
        rgba(255, 255, 255, 0.65) 100%
      );
    backdrop-filter: blur(24px) saturate(1.4);
    -webkit-backdrop-filter: blur(24px) saturate(1.4);
    border: 1px solid rgba(255, 255, 255, 0.6);
    border-top-color: rgba(255, 255, 255, 0.85);
    box-shadow:
      0 8px 32px rgba(0, 0, 0, 0.08),
      0 2px 6px rgba(0, 0, 0, 0.04),
      0 1px 0 rgba(255, 255, 255, 0.8) inset,
      0 20px 40px -20px rgba(255, 255, 255, 0.5) inset;

    &::before,
    &::after {
      display: none;
    }
  }

  .la-cta-headline {
    color: $la-navy;
  }

  .la-cta-description {
    color: $brand-charcoal-dark;

    .la-challenge-cta { color: $la-navy; }
  }

  .la-cta-section .la-btn--ghost {
    color: $la-navy;
    border-color: rgba(42, 90, 168, 0.3);

    &:hover {
      background: rgba(42, 90, 168, 0.08);
    }
  }
}

