.la-pricing-preview-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: $aac-spacing-24;
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
}

/* 2 columns: first two cards in a row, third wraps and fills the next line */
@media (max-width: $aac-breakpoint-lg) {
  .la-pricing-preview-grid,
  .pricing-wrapper.la-pricing-preview-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: $aac-spacing-20;
    max-width: 100%;
  }

  /* 3rd card spans full row when it wraps, so it's wider than each of the first two */
  .pricing-wrapper.la-pricing-preview-grid .pricing-card:nth-child(3) {
    grid-column: 1 / -1;
  }
}

/* Stack all pricing cards on small screens */
@media (max-width: $aac-breakpoint-md) {
  .la-pricing-preview-grid,
  .pricing-wrapper.la-pricing-preview-grid {
    grid-template-columns: 1fr;
    gap: $aac-spacing-16;
    max-width: 100%;
  }

  .pricing-wrapper.la-pricing-preview-grid .pricing-card:nth-child(3) {
    grid-column: auto;
    max-width: none;
    margin-left: 0;
    margin-right: 0;
  }
}

.la-pricing-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  will-change: transform; // GPU layer — prevents backdrop-filter recompute on scroll
  transform: translateY(-6px);
  transition: transform 0.35s ease, box-shadow 0.35s ease, background 0.35s ease;

  &:hover {
    transform: translateY(-12px);
  }
}

/* Bottom-align CTA button in each pricing card (grid gives equal-height cards) */
.pricing-card .cta,
.la-pricing-card .cta {
  margin-top: auto;
  padding-top: $aac-spacing-20;
}

.la-pricing-card__prices {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
  margin: $aac-spacing-16 0;
  padding: $aac-spacing-12 0;
  border-top: 1px solid rgba(0, 0, 0, 0.08);
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
  width: 100%;
}

/* Communicator card: two price options side by side with divider in the middle */
.pricing-card--communicator .price-block:not(.single).la-pricing-card__prices {
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: $aac-spacing-12;
}

.pricing-card--communicator .price-block:not(.single) .or-divider {
  margin: 0;
}

.la-pricing-card__price-row {
  display: flex;
  flex-direction: column;
  align-items: center;
}

/* Pricing page card structure (pricing-wrapper / pricing-card) */
.pricing-wrapper {
  list-style: none;
  padding: 0;
  margin: 0;
}

.pricing-card {
  position: relative;

  .pricing-card__badge,
  .badge {
    position: absolute;
    top: 0.55rem;
    right: 0.75rem;
    font-size: 14px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: 4px 10px;
    border-radius: 999px;
    background: rgba($brand-teal, 0.2);
    color: $brand-stormy-teal;
  }

  .plan-subtitle {
    margin: 0 0 1rem;
  }

  .price-block {
    &.single .price-option {
      margin: 0 auto;
    }
  }

  .or-divider {
    margin: 0.5rem 0;
    font-size: 14px;
    color: rgba(0, 0, 0, 0.5);
  }

  .feature-list {
    list-style: none;
    padding: 0;
    margin: 1rem 0;
    text-align: left;
    width: 100%;

    li {
      padding: 0.35em 0;
      font-size: 15px;
      line-height: 1.4;
    }
  }

  .cta {
    display: inline-block;
    margin-top: auto; /* bottom-align with other cards; padding from .pricing-card .cta, .la-pricing-card .cta */
    padding: 12px 24px;
    border-radius: 8px;
    font-weight: 600;
    text-decoration: none;
    text-align: center;
    transition: opacity 0.15s ease;

    &:hover {
      opacity: 0.9;
    }

    &.primary {
      background: var(--fs-dark-teal, $brand-verdigris);
      color: #fff;
      border: none;
    }

    &.secondary {
      background: transparent;
      color: var(--fs-dark-teal, $brand-verdigris);
      border: 2px solid var(--fs-dark-teal, $brand-verdigris);
    }
  }
}

.la-pricing-card__amount {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: 36px;
  font-weight: $aac-font-weight-black;
  color: $indigo;
  line-height: 1.1;
