  align-items: center;
}

// Pricing page: Plans section badge — larger bottom margin; entrance from left on load
.la-wrapper.la-wrapper--pricing .la-section .la-section-header .la-section-eyebrow-badge {
  margin-bottom: 2.5rem;
  opacity: 0;
  transform: translateX(-36px);
  animation: la-hero-title-from-left 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
}

.la-wrapper.la-wrapper--pricing .la-section .la-section-header .la-hero-title-wrap {
  opacity: 0;
  transform: translateX(-36px);
  animation: la-hero-title-from-left 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) 0.15s forwards;
}

// Pricing page: "Choose your plan" — same size as hero and Compare plans headers, same separator
.la-wrapper.la-wrapper--pricing .la-section .la-section-header .la-section-title {
  font-size: 35px;
  color: $indigo;
  letter-spacing: -0.035em;
  line-height: 1.05;
  margin: 0;

  em {
    color: $brand-smart-blue;
  }

  @media (max-width: 1366px) { font-size: 27px; }
  @media (max-width: 1200px) { font-size: 24px; }
  @media (max-width: 1024px) { font-size: 20px; }
  @media (max-width: 768px)  { font-size: 20px; }
  @media (max-width: 480px)  { font-size: 17px; }
}
.la-wrapper.la-wrapper--pricing .la-section .la-section-header .la-hero-title {
  margin-bottom: $aac-spacing-16;
  font-weight: normal;
  text-align: center;
}
.la-wrapper.la-wrapper--pricing .la-section .la-section-header .la-about-hero-separator {
  margin: 0 auto 0;
  margin-top: -2rem;
  margin-bottom: 0;
}
.la-wrapper.la-wrapper--pricing .la-section .la-section-header {
  margin-bottom: 0;
  max-width: 748px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 1rem;
  padding-right: 1rem;
  width: 100%;
  box-sizing: border-box;
  text-align: center;
}

.la-wrapper.la-wrapper--pricing .la-section .la-section-header .la-hero-title-wrap {
  margin-left: auto;
  margin-right: auto;
}
.la-pricing-cloud-extras-cta {
  display: flex;
  justify-content: center;
  margin: 0 auto $aac-spacing-24;
  padding: 0 1rem;
  max-width: 748px;
  box-sizing: border-box;
}

/* Pricing cards: cloud extras open-modal control reads clearly as a link */
.la-wrapper.la-wrapper--pricing .la-pricing-card__cloud-extras-link {
  font-weight: $aac-font-weight-semi;
  text-decoration: none;
  border-bottom-width: 2px;
  border-bottom-style: solid;
  border-bottom-color: rgba($brand-verdigris, 0.55);
  padding-bottom: 1px;

  &:hover,
  &:focus-visible {
    border-bottom-color: var(--fs-dark-teal, $brand-verdigris);
    color: color.adjust($brand-verdigris, $lightness: -8%);
    outline: none;
  }

  &:focus-visible {
    box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.9), 0 0 0 4px var(--fs-dark-teal, $brand-verdigris);
    border-radius: 2px;
  }
}

.la-wrapper.la-wrapper--pricing .la-section .la-pricing-preview-grid {
  margin-top: 0;
}

.la-wrapper .la-main {
  width: 100%;
  max-width: 100%;
  margin-left: 0;
  margin-right: 0;
  padding-left: calc(#{$aac-spacing-28} + 5rem);
  padding-right: calc(#{$aac-spacing-28} + 5rem);
  overflow-y: visible;
  background: linear-gradient(180deg, #f2f3f5 0%, #e6e8ec 50%, #d8dce0 100%);
}

// ── Font overrides (toggled via controller) ─────────────────────────────────
.la-wrapper.la-font--atkinson {
  font-family: 'Atkinson Hyperlegible', sans-serif !important;

  h1, h2, h3, h4, h5, h6,
  p, a, span, li, blockquote,
  .la-hero-title, .la-section-title, .la-stat-number,
  .la-feature-card h3, .la-cta-title, .la-logo,
  .la-btn, .la-topbar-link, .la-topbar-cta,
  .la-plan-title, .la-cta-headline,
  .la-testimonial-display-text, .la-testimonial-mark {
    font-family: 'Atkinson Hyperlegible', sans-serif !important;
  }
}

.la-wrapper.la-font--lexend {
  font-family: 'Lexend', sans-serif !important;

  h1, h2, h3, h4, h5, h6,
  p, a, span, li, blockquote,
  .la-hero-title, .la-section-title, .la-stat-number,
  .la-feature-card h3, .la-cta-title, .la-logo,
  .la-btn, .la-topbar-link, .la-topbar-cta,
  .la-plan-title, .la-cta-headline,
  .la-testimonial-display-text, .la-testimonial-mark {
    font-family: 'Lexend', sans-serif !important;
  }
}

// ── Color tokens (re-use landing palette) ────────────────────────────────
// $la-* color tokens, two-tone logo, and shadow scale defined in _variables.scss

// ── Topbar ───────────────────────────────────────────────────────────────────
.la-topbar {
  grid-area: topbar;
  position: sticky;
  top: 0;
  background: color.adjust($indigo, $lightness: -6%);
  display: flex;
  align-items: center;
  min-height: 92px;
  padding: 0 $aac-spacing-24;
  gap: 32px; /* logo to nav links */
  border-bottom: 1px solid color.adjust($indigo, $lightness: -6%);
  z-index: $aac-z-topbar;
}

.la-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: $aac-font-size-lg;
  font-weight: $aac-font-weight-black;
  letter-spacing: $aac-letter-spacing-base;
  white-space: nowrap;
  flex-shrink: 0;
  text-decoration: none;

  .app-logo__lingo,
  & > span:first-child { color: $la-logo-left; }
  .app-logo__linq,
  & > span:last-child { color: $la-logo-right; font-style: italic; }

  &:hover { text-decoration: none; }
}

/* App-logo wordmark (footer, etc.): same two-tone */
.app-logo__lingo { color: $la-logo-left; }
.app-logo__linq { color: $la-logo-right; font-style: italic; }

.la-logo-img {
  height: 37px;
  width: auto;
}

.la-topbar-nav {
  display: flex;
  align-items: center;
  gap: 32px; /* nav link to nav link */
  margin-left: 0;

  &::before {
    content: '';
    display: block;
    width: 1px;
    height: 20px;
    background: rgba(white, 0.3);
    margin-right: 0;
  }
}

/* Logo to nav 32px when nav is inside .app-navbar (no .la-topbar gap) */
.app-navbar .la-topbar-nav {
  margin-left: 31px; /* 31px + 1px separator = 32px to first link */
}

.la-topbar-link {
  color: rgba(white, 0.7) !important;

  font-size: 14px; /* 20% smaller than 17px */
  font-weight: $aac-font-weight-semi !important;

  padding: $aac-spacing-6 $aac-spacing-12;
  border-radius: $aac-radius-md;
  text-decoration: none;
  transition: color 0.15s ease, background 0.15s ease;

  &:hover {
    color: white;
    background: rgba(white, 0.08);
    text-decoration: none;
  }

  &.active {
    color: white;
  }
}

.la-topbar-link:focus-visible {
  @include focus-ring;
}

.la-topbar-alt-link {
  color: rgba(white, 0.75);
  font-size: 14px;
  font-weight: $aac-font-weight-semi;
  padding: $aac-spacing-4 $aac-spacing-8;
  border-radius: $aac-radius-md;
  text-decoration: none;
  margin-left: $aac-spacing-4;
  transition: color 0.15s ease, background 0.15s ease;

  &:hover {
    color: rgba(white, 0.7);
    background: rgba(white, 0.06);
    text-decoration: none;
  }
}

.la-topbar-alt-link:focus-visible {
  @include focus-ring;
}

.la-topbar-right {
  display: flex;
  align-items: center;
  gap: 16px; /* right CTA gap */
}

/* ── Hamburger button (hidden on desktop, shown ≤1024px) ── */
.la-topbar-hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 38px;
  height: 38px;
  margin-right: 24px;
  padding: 0;
  background: rgba(255, 255, 255, 0.10);
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.2s ease, border-color 0.2s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.18);
    border-color: rgba(255, 255, 255, 0.3);
  }
  &:focus-visible {
    background: rgba(255, 255, 255, 0.18);
    border-color: rgba(255, 255, 255, 0.3);
    @include focus-ring;
  }
}

.la-topbar-hamburger__bar {
  display: block;
  width: 18px;
  height: 2px;
  background: rgba(255, 255, 255, 0.9);
  border-radius: 1px;

  & + & {
    margin-top: 4px;
  }
}

/* Footer hamburger sits on a light background — override the white bars from
   the base rule (designed for the dark topbar) with a dark color. */
.la-footer__hamburger .la-topbar-hamburger__bar {
  background: $brand-charcoal-dark;
}

/* ── Mobile drawer (slide-in from right) ── */
.la-mobile-drawer {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 10000;
}

.la-mobile-drawer__backdrop {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba($indigo, 0.35);
  animation: la-drawer-fade-in 0.25s ease forwards;
}

@keyframes la-drawer-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

.la-mobile-drawer__panel {
  position: absolute;
  top: 0;
  right: 0;
  width: auto;
  height: 100%;
  background: #fff;
  box-shadow: -4px 0 24px rgba($indigo, 0.15);
  padding: 72px 40px 32px 32px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  animation: la-drawer-slide-in 0.28s cubic-bezier(0.4, 0, 0.2, 1) forwards;
  /* Scroll when content exceeds viewport height (tall footer menus on short screens). */
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
}

@keyframes la-drawer-slide-in {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}

.la-mobile-drawer__close {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 1px solid rgba($indigo, 0.1);
  border-radius: 10px;
  font-size: 22px;
  color: rgba($indigo, 0.5);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;

  &:hover {
    background: rgba($indigo, 0.05);
    color: rgba($indigo, 0.8);
  }
}

.la-mobile-drawer__close:focus-visible {
  @include focus-ring($color: $brand-verdigris);
}

.la-mobile-drawer__link {
  display: block;
  padding: 14px 16px;
  font-size: 17px;
  font-weight: 600;
  color: $la-navy;
  text-decoration: none;
  border-radius: 12px;
  transition: background 0.15s ease;

  &:hover {
    background: rgba($indigo, 0.05);
    text-decoration: none;
    color: $la-navy;
  }
}

.la-mobile-drawer__link:focus-visible {
  @include focus-ring($color: $brand-verdigris);
}

/* Button-style drawer items (Upgrade, Help, Theme): match .la-mobile-drawer__link look with navy */
.la-mobile-drawer__link--button {
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  appearance: none;
  cursor: pointer;
  display: block;
  padding: 14px 16px;
  font-size: 17px;
  font-weight: 600;
  color: $la-navy;
  text-decoration: none;
  border-radius: 12px;
  transition: background 0.15s ease;

  &:hover {
    background: rgba($indigo, 0.05);
    color: $la-navy;
  }
}

.la-mobile-drawer__link--button:focus-visible {
  @include focus-ring($color: $brand-verdigris);
}

.la-mobile-drawer__header {
  display: block;
  padding: 14px 16px 4px;
  font-size: 14px;
  font-weight: 700;
  color: rgba($indigo, 0.6);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.la-mobile-drawer__cta {
  display: inline-block;
  align-self: flex-start;
  margin-top: 12px;
  padding: 10px 20px;
  background: color.adjust($brand-honey-bronze, $saturation: -7%);
  color: $la-navy;
  font-size: 14px;
  font-weight: 800;
  text-align: center;
  text-decoration: none;
  border-radius: 100px;
  transition: filter 0.15s ease;

  &:hover {
    filter: brightness(1.08);
    text-decoration: none;
    color: $la-navy;
  }
}

.la-mobile-drawer__divider {
  height: 1px;
  background: rgba($indigo, 0.08);
  margin: 8px 0;
}

.la-mobile-drawer__footer-note {
  display: block;
  padding: 14px 16px 4px;
  font-size: $aac-font-size-xs;
  color: rgba($indigo, 0.6);
  letter-spacing: 0.02em;
}

.la-mobile-drawer__badges {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: $aac-spacing-10;
  padding: 10px 16px 4px;
}

/* ── LingoLinq company sidebar (About, Pricing, Developers, etc.) ── */
.ll-company-sidebar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 10000;
}

.ll-company-sidebar__backdrop {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba($indigo, 0.35);
  animation: la-drawer-fade-in 0.25s ease forwards;
}

.ll-company-sidebar__panel {
  position: absolute;
  top: 0;
  right: 0;
  width: 300px;
  max-width: 90vw;
  height: 100%;
  background: #fff;
  box-shadow: -4px 0 24px rgba($indigo, 0.15);
  padding: 72px 24px 32px 24px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  animation: la-drawer-slide-in 0.28s cubic-bezier(0.4, 0, 0.2, 1) forwards;
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
}

.ll-company-sidebar__close {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 1px solid rgba($indigo, 0.1);
  border-radius: 10px;
  font-size: 22px;
  color: rgba($indigo, 0.5);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;

  &:hover {
    background: rgba($indigo, 0.05);
    color: rgba($indigo, 0.8);
  }
}

.ll-company-sidebar__title {
  margin: 0 0 20px 0;
  font-size: 14px;
  font-weight: 600;
  color: $la-navy;
  letter-spacing: -0.01em;
}

.ll-company-sidebar__nav {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ll-company-sidebar__link {
  display: block;
  padding: 12px 14px;
  font-size: 14px;
  font-weight: 500;
  color: $la-navy;
  text-decoration: none;
  border-radius: 10px;
  transition: background 0.15s ease, color 0.15s ease;

  &:hover {
    background: rgba($indigo, 0.06);
    text-decoration: none;
    color: $la-navy;
  }
}

.la-topbar-compare-link {
  color: rgba(white, 0.55);
  font-size: $aac-font-size-xs;
  font-weight: $aac-font-weight-semi;
  text-decoration: none;
  transition: color 0.15s ease;

  &:hover { color: rgba(white, 0.9); text-decoration: none; }
}

// ── Font-toggle buttons ─────────────────────────────────────────────────────
.la-font-toggles {
  display: flex;
  align-items: center;
  gap: $aac-spacing-6;
}

.la-font-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: $aac-radius-circle;
  border: 1px solid rgba(white, 0.15);
  background: rgba(white, 0.08);
  color: rgba(white, 0.55);
  font-size: 14px;
  font-weight: $aac-font-weight-bold;
  cursor: pointer;
  transition: all 0.15s ease;
  padding: 0;
  line-height: 1;

  &:hover {
    background: rgba(white, 0.15);
    color: rgba(white, 0.85);
    border-color: rgba(white, 0.25);
  }

  &:focus-visible {
    @include focus-ring($color: $la-teal);
  }

  &--active {
    background: rgba(white, 0.2);
    color: white;
    border-color: rgba(white, 0.4);
    box-shadow: 0 0 0 1px rgba(white, 0.1);
  }
}

.la-font-toggle-letter--atkinson {
  font-family: 'Atkinson Hyperlegible', sans-serif;
}

.la-font-toggle-letter--lexend {
  font-family: 'Lexend', sans-serif;
}

.la-topbar-sign-in {
  font-size: 14px;
  font-weight: $aac-font-weight-semi;
  color: rgba(255, 255, 255, 0.82);
  text-decoration: none;
  letter-spacing: $aac-letter-spacing-base;
  padding: 6px 20px;
  border-radius: $aac-radius-pill;
  border: 1px solid rgba(255, 255, 255, 0.18);
  transition: color 0.15s ease, background 0.15s ease, border-color 0.15s ease;
  white-space: nowrap;

  &:hover {
    color: #fff;
    background: rgba(255, 255, 255, 0.10);
    border-color: rgba(255, 255, 255, 0.30);
    text-decoration: none;
  }
}

.la-topbar-cta {
  background: $la-hero-cta-bg;
  color: $la-navy;
  font-size: 14px;
  font-weight: $aac-font-weight-black;
  padding: 6px 16px;
  border-radius: $aac-radius-pill;
  text-decoration: none;
  border: 1px solid rgba($brand-honey-bronze, 0.5);
  letter-spacing: $aac-letter-spacing-base;
  transition: filter 0.15s ease;
  white-space: nowrap;

  &:hover { filter: brightness(1.08); text-decoration: none; color: $la-navy; }
}

/* Try Free in inner header — same bg as Try LingoLinq (hero .la-btn--primary), slightly smaller than hero CTA */
#inner_header .la-topbar-cta {
  background: $la-hero-cta-bg !important;

  color: $la-navy !important;

  font-size: 14px !important;

  font-weight: 600; /* semi-bold: a bit more bold, not full bold */
  padding: 6px 16px !important;

  border: 1px solid rgba($brand-honey-bronze, 0.5) !important;

  filter: brightness(1.02) !important;

  box-shadow: none !important;

  transition: filter 0.15s ease, transform 0.2s ease !important;


  &:hover {
    filter: brightness(0.96) !important;

    transform: translateY(-2px) !important;

    box-shadow: none !important;

    color: $la-navy !important;

    text-decoration: none !important;

  }
}

/* Sign In (identity button) — same glass as Watch Demo, same shadow as Try Free; overrides gradient/base .btn when in header */
header #identity #identity_button.btn {
  background: rgba(255, 255, 255, 0.22) !important;
  background-image: none !important;
  backdrop-filter: blur(10px) !important;

  -webkit-backdrop-filter: blur(10px) !important;

  color: $la-navy !important;
  border: 1px solid rgba(0, 0, 0, 0.04) !important;
  box-shadow: none !important;
  transition: background 0.25s ease, border-color 0.25s ease, color 0.25s ease, box-shadow 0.25s ease !important;


  &:hover,
  &:focus-visible {
    background: rgba(255, 255, 255, 0.32) !important;
    background-image: none !important;
    color: $la-navy !important;
    border-color: rgba(0, 0, 0, 0.06) !important;
    box-shadow: none !important;
    filter: none !important;

  }
}
header #identity #identity_button.btn::before,
header #identity #identity_button.btn::after {
  display: none !important;
  background: none !important;
  background-image: none !important;
}

/* Unauthenticated pages: identity/Sign In button — solid dark slate to match dropdown (landing, login, register, etc.). Pill-shaped (not circular). */
#within_ember header.header--unauthenticated #identity #identity_button.btn,
#within_ember header.header--unauthenticated .app-navbar #identity #identity_button.btn {
  width: auto !important;
  min-width: unset !important;
  height: 42px !important;
  padding-left: 2.2rem !important;
  padding-right: 2.2rem !important;
  padding-top: 2px !important;
  padding-bottom: 2px !important;
  border-radius: 999px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 0.25rem !important;
  white-space: nowrap !important;
  background: rgba($brand-charcoal-dark, 1) !important;
  background-image: none !important;
  color: rgba(255, 255, 255, 0.95) !important;
  border: 1px solid rgba(255, 255, 255, 0.12) !important;
  box-shadow: none !important;

  &:hover,
  &:focus-visible {
    background: color.adjust(rgba($brand-charcoal-dark, 1), $lightness: 8%) !important;
    background-image: none !important;
    color: #ffffff !important;
    border-color: rgba(255, 255, 255, 0.2) !important;
    box-shadow: none !important;
  }
}

.la-topbar-login {
  background: $brand-smart-blue;
  color: $la-white;
  font-size: $aac-font-size-sm;
  font-weight: $aac-font-weight-black;
  padding: $aac-spacing-8 $aac-spacing-20;
  border-radius: $aac-radius-pill;
  text-decoration: none;
  letter-spacing: $aac-letter-spacing-base;
  transition: filter 0.15s ease;
  white-space: nowrap;

  &:hover { filter: brightness(1.08); text-decoration: none; color: $la-white; }
}

/* Tiny link to left of Try Free: toggles hero + sign-in/speak button colors (current vs previous slate) */
.la-hero-color-toggle {
  margin-right: 12px;
  padding: 2px 6px;
  font-size: 14px;
  line-height: 1.2;
  color: rgba(255, 255, 255, 0.6);
  background: transparent;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  transition: color 0.15s ease, background 0.15s ease;

  &:hover {
    color: rgba(255, 255, 255, 0.95);
    background: rgba(255, 255, 255, 0.12);
  }
}

// ── Sidebar ──────────────────────────────────────────────────────────────────
.la-sidebar {
  grid-area: sidebar;
  background: $color-surface;
  border-right: 1px solid $color-border;
  padding: $aac-spacing-16 $aac-spacing-8;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-16;

  > * + * {
    border-top: 1px solid rgba(0, 0, 0, 0.08);
    padding-top: $aac-spacing-16;
  }
}

.la-sidebar-label {
  font-size: $la-panel-font-size-xs;
  font-weight: $aac-font-weight-black;
  text-transform: uppercase;
  letter-spacing: $aac-letter-spacing-wide;
  color: $brand-teal;
  padding: $aac-spacing-10 $aac-spacing-12 $aac-spacing-4;
  margin-top: $aac-spacing-6;

  &:first-child { margin-top: 0; }

  &.la-sidebar-label--lower { margin-top: 0; }
}

.la-sidebar-quicklinks {
  margin: 0 0 auto 0;
  padding-bottom: $aac-spacing-16;
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
}

.la-nav-item {
  display: flex;
  align-items: center;
  gap: $aac-spacing-10;
  /* WCAG 2.5.5 AAA touch target — was 10×14 (~20 tall). */
  padding: $aac-spacing-12 $aac-spacing-14;
  min-height: 44px;
  border-radius: $aac-radius-md;
  cursor: pointer;
  font-size: $la-panel-font-size-sm;
  font-weight: $aac-font-weight-semi;
  color: $color-text-mid;
  border: 1.5px solid transparent;
  text-decoration: none;
  transition: all 0.15s ease;
  user-select: none;

  &:hover {
    background: $color-border;
    color: $color-text;
    text-decoration: none;
  }

  &.la-active {
    background: rgba($brand-honey-bronze, 0.08);
    color: color.adjust($brand-honey-bronze, $lightness: -10%);
    border-color: rgba($brand-honey-bronze, 0.25);
  }
}

.la-nav-icon {
  font-size: $la-panel-font-size-base;
  width: 22px;
  text-align: center;
  flex-shrink: 0;
}

.la-panel-badges {
  margin: auto 0;
  padding: $aac-spacing-16 $aac-spacing-12;
  display: flex;
  justify-content: center;
  gap: $aac-spacing-8;
  border-top: 1px solid rgba(0, 0, 0, 0.08);
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
}

.la-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: $aac-spacing-4 $aac-spacing-10;
  border-radius: $aac-radius-pill;
  font-size: $la-panel-font-size-xs;
  font-weight: $aac-font-weight-medium;
  letter-spacing: $aac-letter-spacing-wide;
  text-transform: uppercase;
  opacity: 0.55;
  box-shadow: none;

  &.la-badge--wcag {
    background: rgba($cat-actions-text, 0.06);
    color: $cat-actions-text;
    border: 1px solid rgba($cat-actions-text, 0.08);
  }

  &.la-badge--oss {
    background: rgba($cat-people-text, 0.06);
    color: $cat-people-text;
    border: 1px solid rgba($cat-people-text, 0.08);
  }
}

// ── Main content ─────────────────────────────────────────────────────────────
.la-main {
  grid-area: main;
  overflow-y: auto;
  padding: $aac-spacing-48 $aac-spacing-28;
  padding-bottom: 0;
  background: #F3F1ED;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-28; /* reduced from 48 for tighter section spacing */
}

// ── Background orbs (used on register, login, forgot pages; landing uses fluctuating gradient) ──
.la-bg-orbs {
  position: absolute;
  inset: -80px;
  pointer-events: none;
  filter: blur(28px);
  opacity: 0.82;
  z-index: 0;
}

.la-bg-orb {
  position: absolute;
  border-radius: 999px;
  transform: translateZ(0);

  &--a {
    width: 500px;
    height: 500px;
    right: 5%;
    top: 3%;
    background: radial-gradient(circle at 30% 30%, rgba(58, 107, 199, 0.42), transparent 58%),
                radial-gradient(circle at 70% 70%, rgba(100, 140, 220, 0.34), transparent 60%);
  }

  &--b {
    width: 420px;
    height: 420px;
    left: 4%;
    top: 8%;
    background: radial-gradient(circle at 35% 35%, rgba($brand-honey-bronze, 0.36), transparent 60%),
                radial-gradient(circle at 70% 70%, rgba(230, 180, 80, 0.28), transparent 58%);
  }

  &--c {
    width: 480px;
    height: 480px;
    left: 15%;
    top: 45%;
    background: radial-gradient(circle at 35% 35%, rgba($la-teal, 0.32), transparent 58%),
                radial-gradient(circle at 70% 70%, rgba(245, 140, 100, 0.26), transparent 60%);
  }

  &--d {
    width: 540px;
    height: 540px;
    right: 8%;
    bottom: 10%;
    background: radial-gradient(circle at 30% 30%, rgba(58, 107, 199, 0.32), transparent 58%),
                radial-gradient(circle at 70% 70%, rgba(140, 170, 230, 0.26), transparent 60%);
  }
}

// ── Hero card ────────────────────────────────────────────────────────────────
// Full-width hero: break out of .la-main so hero spans viewport; content stays centered. Sits just below navbar.
.la-hero-card {
  position: relative;
  margin-top: clamp(0rem, calc(0rem + 2vw), 2rem); /* 2rem less than previous */
  width: 100vw;
  margin-left: calc(50% - 50vw);
  margin-right: calc(50% - 50vw);
  background:
    radial-gradient(circle at 20% 20%, rgba($la-teal, 0.05), transparent 60%),
    radial-gradient(circle at 80% 80%, rgba($la-navy, 0.05), transparent 60%),
    linear-gradient(180deg, #{color.adjust($brand-stone-100, $lightness: 10%)} 0%, #{color.adjust($brand-stone-200, $lightness: 10%)} 50%, #{color.adjust($brand-stone-300, $lightness: 10%)} 100%);
  border-radius: 0;
  position: relative;
  z-index: 1;
  overflow: visible;
  /* Bottom shadow to lift hero off the section below */
  box-shadow: 0 10px 18px -6px rgba($indigo, 0.22);
  transition: background 0.25s ease;
}

.hero-background {
  padding-top: 0; /* 2rem less than previous 2rem */

  @media (max-width: 1024px) {
    padding-top: 6rem; /* 2rem less than previous 8rem */
  }

  // Bottom curve removed — hero has flat bottom
  &::after {
    display: none;
  }
}

/* hero-background::before overlay removed */

#within_ember.la-hero-colors-alt .la-hero-card {
  background: color.adjust($la-hero-blue, $lightness: 11%, $saturation: 6%);
}
/* Alt toggle: buttons 15% lighter than rgb(75, 110, 144) (#4b6e90) */
#within_ember.la-hero-colors-alt .la-topbar-login,
#within_ember.la-hero-colors-alt .la-mockup-speak,
#within_ember.la-hero-colors-alt #identity .btn {
  background: color.adjust(#4b6e90, $lightness: 15%);
}

/* Hero container: layout only, fully transparent (no glass panel); above wave image */
.la-hero-card .hero-container {
  position: relative;
  z-index: 1;
  max-width: min(1320px, 94%);
  margin: clamp(1.5rem, calc(0.5rem + 1.75vw), 3rem) auto 0;
  padding: clamp(24px, calc(12px + 2.5vw), 48px) clamp(28px, calc(12px + 3.5vw), 72px) clamp(28px, calc(14px + 2.9vw), 56px) clamp(20px, calc(4px + 3vw), 48px);
  border-radius: clamp(16px, calc(10px + 1.25vw), 28px);
  background: transparent;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  border: none;
  box-shadow: none;
}

.la-hero-card-inner {
  max-width: min(1320px, 100%);
  margin: 0 auto;
  padding: 0;
  display: grid;
  grid-template-columns: 6fr 4fr; /* 60% left (text), 40% right (mockup) */
  gap: clamp(24px, calc(8px + 3.3vw), 56px);
  align-items: start; /* let columns grow with content so mockup margin/scale have room */
  position: relative;
  background: transparent;

  // warm glow — top right, balances mockup side
  &::before {
    content: '';
    position: absolute;
    top: -60px;
    right: -40px;
    width: 420px;
    height: 420px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba($brand-honey-bronze, 0.12) 0%, transparent 55%);
    pointer-events: none;
  }

  // cool glow — bottom left, soft fill on text side
  &::after {
    content: '';
    position: absolute;
    bottom: -50px;
    left: 25%;
    width: 360px;
    height: 360px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba($la-teal, 0.09) 0%, transparent 55%);
    pointer-events: none;
  }

  .la-section-eyebrow-badge {
    color: #0d5c5f;
    background: rgba(13, 92, 95, 0.15);
    border-color: rgba(13, 92, 95, 0.35);
  }
}

/* Hero text: layout only, no container bg */
.la-hero-text {
  max-width: min(860px, 100%);
  padding-left: 0.5rem;
  padding-right: 0.5rem;
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* Dark gray text and borders on transparent hero so content reads on glass panel; Lexend font */
.la-hero-card .la-hero-text .la-hero-title,
.la-hero-card .la-hero-text .la-hero-title .la-hero-title-line1,
.la-hero-card .la-hero-text .la-hero-title .la-hero-title-line2 {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  color: $brand-charcoal-dark;
}
/* "every student" — gradient +5% saturation */
.la-hero-card .la-hero-text .la-hero-title .la-hero-highlight {
  background: $la-highlight-gradient;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
}
.la-hero-card .la-hero-text .la-hero-subtitle {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  color: $brand-charcoal-dark;
}
.la-hero-card .la-hero-text .la-hero-badge-label {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
}
.la-hero-card .la-hero-text .la-hero-headline {
  border-bottom-color: rgba(0, 0, 0, 0.09);
}
.la-hero-card .la-hero-text .la-hero-badges-section {
  background: rgba(0, 0, 0, 0.04);
  border-color: rgba(0, 0, 0, 0.08);
}
.la-hero-card .la-hero-text .la-hero-badge-label {
  color: $brand-charcoal-dark;
}
.la-hero-card .la-hero-text .la-btn--ghost {
  color: rgba(255, 255, 255, 0.86);
  border-color: rgba(255, 255, 255, 0.11);
}
.la-hero-card .la-hero-text .la-btn--ghost:hover {
  color: rgba(255, 255, 255, 0.95);
  background: rgba(65, 75, 91, 0.85);
}

/* Left content block: headline max-width, vertical rhythm per spacing map */
.la-hero-headline-and-badges .la-hero-headline,
.la-hero-title-wrap {
  max-width: min(590px, 100%);
}

// Hero left column: distinct sections (headline, badges, actions)
.la-hero-section {
  position: relative;
}

// Wrapper so the headline's border matches the badge container width (grid column = badge width)
.la-hero-headline-and-badges {
  display: grid;
  grid-template-columns: 1fr;
  width: fit-content;
}

.la-hero-headline-and-badges .la-hero-headline {
  min-width: 0; /* allow column to shrink to badge width */
  width: calc(100% - 1rem);
}

.la-hero-headline {
  margin-bottom: 28px; /* 28px divider → paragraph (vertical rhythm) */
  border-bottom: 1px solid rgba(255, 255, 255, 0.09);
}

/* Hero vertical rhythm: headline 24px → divider, 28px → paragraph, 32px → pills, 28px → CTA */
.la-hero-card .la-hero-headline .la-hero-title-wrap {
  padding-bottom: 24px;
}

.la-hero-trust-line {
  margin-top: 24px;
  margin-bottom: 14px;
  padding-top: 18px;
  border-top: 1px solid rgba(255, 255, 255, 0.11);
  font-size: 16px;
  font-weight: 500;
  letter-spacing: 0.035em;
  color: rgba(255, 255, 255, 0.78);
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
}
@media (max-width: 768px) {
  .la-hero-trust-line {
    font-size: 14px;
  }
}

.la-hero-card .la-hero-text .la-hero-trust-line {
  border-top-color: rgba(0, 0, 0, 0.04);
  color: $brand-cool-steel;
}

.la-hero-badges-section {
  width: fit-content;
  padding: clamp(8px, calc(4px + 0.56vw), 12px);
  margin-bottom: 28px; /* 28px feature pills → CTA buttons */
  background: rgba(255, 255, 255, 0.94);
  border: 1px solid rgba(0, 0, 0, 0.12);
  border-radius: 16px;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.08), 0 2px 6px rgba(0, 0, 0, 0.04);
}

.la-hero-badges-section .la-hero-badges {
  margin-top: 0;
  margin-bottom: 0;
  width: 100%;
}

.la-hero-badges-section .la-hero-badge {
  flex: 1 1 0;
  min-width: 0;
  padding-left: 14px;
  padding-right: 22px;
  justify-content: flex-start;
}

.la-hero-badges-section .la-hero-badge-label {
  white-space: nowrap;
}

.la-hero-actions-section {
  padding-top: 16px; /* 8px more above CTAs for breathing room below pills */
}

.la-hero-eyebrow {
  font-size: clamp(11px, calc(8px + 0.35vw), 14px);
  font-weight: $aac-font-weight-bold;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: $brand-honey-bronze;
  margin-bottom: $aac-spacing-16;
}

.la-hero-title-wrap {
  padding-bottom: clamp(12px, calc(6px + 1.25vw), 24px);
}

.la-wrapper .la-hero-title {
  font-family: 'Maitree', serif;
  font-size: clamp(2rem, calc(0.8rem + 3.47vw), 3.575rem);
  font-weight: 600; /* semi-bold: cleaner, calmer, more editorial than 700 */
  color: #ffffff;
  line-height: 1.08;
  letter-spacing: -0.025em; /* tight for display; keeps two-line headline feeling like one unit */
  font-kerning: normal;
  margin: 0;
  margin-bottom: 0;
  display: block;
  height: auto;

  span {
    display: inline;
    position: static;
    left: auto;
    top: auto;
    font-weight: inherit;
  }

  .la-hero-title-line1 {
    color: #FFFFFF;
    font-size: 1.2em;
  }

  .la-hero-highlight {
    font-size: 1.1025em; /* 5% larger than 1.05em */
    font-weight: normal;
  }

  .la-hero-title-line2 {
    display: inline;
    /* Scale with viewport like line1 does (line1 uses 1.2em which scales via
       the parent's clamp). Floor 18px on tiny phones, ceiling 32px at 768. */
    font-size: clamp(18px, calc(12px + 2.5vw), 32px);
  }
}

/* Hero title entrance: Communication from left, "access for every student" from right */
@keyframes la-hero-title-from-left {
  from {
    opacity: 0;
    transform: translateX(-36px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes la-hero-title-from-right {
  from {
    opacity: 0;
    transform: translateX(36px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes ub-letter-bounce {
  0%   { opacity: 0; transform: translateY(-14px); color: $brand-verdigris; }
  60%  { opacity: 1; transform: translateY(2px);  color: $brand-dusty-denim; }
  80%  { transform: translateY(-1px);             color: #3a6bb0; }
  100% { opacity: 1; transform: translateY(0);    color: $indigo; }
}
.la-hero-card .la-hero-title .la-hero-title--from-left {
  display: inline-block;
  animation: la-hero-title-from-left 1s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
}
.la-hero-card .la-hero-title .la-hero-title--from-right {
  display: inline-block;
  animation: la-hero-title-from-left 1s cubic-bezier(0.25, 0.46, 0.45, 0.94) 0.2s forwards;
  opacity: 0;
}

/* Dashboard hero: subtitle enters from the right (after title from left) */
@keyframes md-hero-from-right {
  from {
    opacity: 0;
    transform: translateX(36px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* Dashboard hero: "It's great to see you" from left, "Let's continue..." from right (same timing as landing-alt); centered on page */
.md-navbar__speech-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: $brand-cool-steel;
  margin-right: 10px;
  vertical-align: middle;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.15s ease;
}
.md-navbar__speech-dot:hover {
  background: $brand-slate-gray;
  transform: scale(1.3);
}
.md-hero__speech-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: $brand-cool-steel;
  margin-top: 8px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.15s ease;
}
.md-hero__speech-dot:hover {
  background: $brand-slate-gray;
  transform: scale(1.3);
}
.md-hero--dashboard {
  text-align: center;
  padding-bottom: 20px;
  margin-bottom: 8px;
}
.md-hero--dashboard-user {
  padding-top: 0;
}
.md-hero--dashboard .md-hero__title .md-hero__title--from-left {
  display: inline-block;
  font-size: inherit;
  opacity: 0;
  animation: la-hero-title-from-left 1s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
}
.md-hero--dashboard .md-hero__sub .md-hero__sub--from-right {
  display: inline-block;
  font-size: inherit;
  opacity: 0;
  animation: md-hero-from-right 1s cubic-bezier(0.25, 0.46, 0.45, 0.94) 0.5s forwards;
}
.md-hero__gradient-text {
  font-style: normal;
  background: $la-highlight-gradient;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
}

.la-hero-highlight {
  background: $la-highlight-gradient;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
  font-size: 1.155em; /* 5% larger than 1.1em */
}

/* "every student" in hero — teal to blue gradient */
.hero-gradient {
  background: linear-gradient(90deg, $brand-verdigris, $brand-dusty-denim);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
  font-size: 1.155em; /* match previous la-hero-highlight emphasis */
}

/* Same gradient as "every student" for "actually", "nothing you don't", "a voice", pricing hero "pricing" */
.la-wrapper .la-section-title em,
.la-wrapper .la-plan-title em,
.la-wrapper .la-cta-headline em,
.la-wrapper .la-hero-title em {
  background: $la-highlight-gradient;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
}

.la-hero-subtitle-badges-wrap {
  width: fit-content;
  max-width: 100%;
  display: flex;
  flex-direction: column;
}

.la-wrapper .la-hero-subtitle {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: clamp(1.25rem, calc(0.65rem + 1.38vw), 1.755rem);
  font-weight: 400;
  color: #FFFFFF;
  line-height: 1.7;
  letter-spacing: 0.01em;
  margin: 0 0 32px; /* 32px paragraph → feature pills (vertical rhythm) */
  max-width: 65ch; /* 55–70 chars per line for readability */
}

/* Small screens (≤640px): floor la-hero-subtitle at 15px so it stays legible
   when the clamp above would otherwise scale it too small. */
@media (max-width: $aac-breakpoint-sm) {
  .la-wrapper .la-hero-subtitle {
    font-size: 15px;
  }
}

@keyframes la-badges-enter {
  from {
    opacity: 0;
    transform: translateX(-48px);
  }
  to {
    opacity: 0.95;
    transform: translateX(0);
  }
}

.la-hero-badges {
  display: flex;
  flex-wrap: nowrap;
  gap: clamp(4px, calc(2px + 0.42vw), 8px);
  margin-top: 0;
  margin-bottom: 0;
}

.la-hero-badge {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, calc(4px + 0.56vw), 12px);
  padding: clamp(3px, calc(2px + 0.14vw), 5px) clamp(12px, calc(4px + 1.11vw), 20px) clamp(3px, calc(2px + 0.14vw), 5px) clamp(12px, calc(8px + 0.56vw), 16px);
  flex-shrink: 0; /* overridden in .la-hero-badges-section for equal fit */
  background: rgba(255, 255, 255, 0.98);
  border: 1px solid rgba(0, 0, 0, 0.1);
  border-radius: 12px; /* more square than pill so badges don’t look like action buttons */
  opacity: 0.98;
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.07), inset 0 1px 0 rgba(255, 255, 255, 0.95);
  transition: background 0.2s ease, opacity 0.2s ease, box-shadow 0.2s ease;
  will-change: transform;
  animation: la-badges-enter 0.85s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;

  &:nth-child(1) { animation-delay: 0.2s; opacity: 0; }
  &:nth-child(2) { animation-delay: 0.4s; opacity: 0; }
  &:nth-child(3) { animation-delay: 0.6s; opacity: 0; }

  &:hover {
    background: #ffffff;
    border-color: rgba(0, 0, 0, 0.12);
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.12), inset 0 1px 0 rgba(255, 255, 255, 1);
    opacity: 1;
  }
}

// $la-hero-badge-icon-bg defined in _variables.scss

.la-hero-badge-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: clamp(26px, calc(20px + 0.83vw), 32px);
  height: clamp(26px, calc(20px + 0.83vw), 32px);
  min-width: 26px;
  min-height: 26px;
  border-radius: 50%;
  font-size: clamp(13px, calc(10px + 0.35vw), 15px);
  line-height: 1;
  background: rgba(color.adjust($brand-honey-bronze, $saturation: -15%, $lightness: 15%), 0.88);

  /* Cloud-based icon bg; 90% Lower Cost and Real Classrooms use same ($la-hero-badge-icon-bg) */
