/* 90% Lower Cost icon: copy cloud-based icon bg and icon color */
.la-hero-badge-icon--cost {
  background: $la-hero-badge-icon-bg !important;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.12);
  color: $brand-charcoal-dark;
}

.la-hero-badge-label {
  font-size: clamp(11.7px, calc(9px + 0.32vw), 14px); /* 10% smaller than previous */
  font-weight: $aac-font-weight-semi;
