  letter-spacing: 0.01em;
}

.la-hero-actions {
  display: flex;
  gap: clamp(10px, calc(4px + 0.83vw), 16px);
  flex-wrap: wrap;
  margin-top: 0; /* 32px from pills section margin-bottom */
