  margin: 0;
}

.la-wrapper .la-about-glass-card__text {
  font-size: 16px;
  color: #e8ecf4;
  line-height: 1.75;
  margin: 0;

  strong {
    color: #ffffff;
  }

  .la-challenge-cta {
    color: #7eb8e0;
  }
}

.la-chip-icon {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  flex-shrink: 0;

  &.la-chip-icon--teal  { background: rgba($la-teal, 0.14); }
  &.la-chip-icon--coral { background: rgba($brand-honey-bronze, 0.12); }
}

.la-chip-title {
  font-size: $aac-font-size-xs * 1.15;
  font-weight: $aac-font-weight-black;
  color: color.adjust($la-hero-blue, $lightness: -10%);
  white-space: nowrap;
