}
.la-wrapper--support .la-beta-feedback__file-input {
  width: 100%;
  max-width: 100%;
}

/* Beta feedback: client-side validation banner and field highlights */
#beta-feedback-hero .la-beta-feedback__validation-banner {
  font-size: 14px;
  line-height: 1.45;
  color: #92400e;
  background: rgba(254, 243, 199, 0.95);
  border: 1px solid rgba(217, 119, 6, 0.35);
  border-radius: 12px;
  padding: 0.75rem 1rem;
  margin-bottom: 1rem;
}
#beta-feedback-hero .la-contact-form__field-error {
  font-size: 14px;
  line-height: 1.45;
  color: #b91c1c;
  margin: 0.375rem 0 0;
}
#beta-feedback-hero .la-contact-form__row--error .la-contact-form__label {
  color: #991b1b;
}
#beta-feedback-hero .la-contact-input--invalid,
#beta-feedback-hero select.la-contact-input--invalid {
  border-color: #dc2626;
  box-shadow: 0 0 0 1px rgba(220, 38, 38, 0.2);
}
#beta-feedback-hero .la-contact-input--invalid:focus-visible {
  border-color: #b91c1c;
  box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.15);
  outline: none;
}

/* Honeypot row: off-screen, not keyboard-focusable in normal tab order.
   Applies in both the standalone /beta-feedback page and the beta-feedback
   modal — the field type itself is a honeypot regardless of host. */
.la-wrapper--support .la-beta-feedback-hp,
.beta-feedback-modal-wrap .la-beta-feedback-hp {
  position: absolute;
  left: -10000px;
  top: auto;
  width: 1px;
  height: 1px;
  overflow: hidden;
}
.la-wrapper--support .la-beta-feedback-hp__input,
.beta-feedback-modal-wrap .la-beta-feedback-hp__input {
  pointer-events: none;
}

/* ── Beta Feedback modal ─────────────────────────────────────────────────
   Sizing/chrome mirror the find-button modal pattern (full-height,
   border-radius 18px, .la-modal-header + .la-modal-close). Header
   reuses the about-page hero composition (.la-section-eyebrow-badge +
   .la-hero-title with .hero-gradient + .la-about-hero-separator +
   .la-pricing-hero-subtitle) so the modal reads as a "mini about-page".
   Form fields rely on the global .la-contact-input / .la-btn classes —
   no per-modal restyling. */
.modal .modal-dialog:has(.beta-feedback-modal-wrap) {
  max-width: 845px; /* find-button modal is 676px; this is ~25% wider. */
  width: calc(100vw - 16px);
  height: calc(100vh - 8px);
  max-height: calc(100vh - 8px);
  margin: 4px auto;
  display: flex;
  flex-direction: column;
}
.modal .modal-dialog:has(.beta-feedback-modal-wrap) > * {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.modal-content:has(.beta-feedback-modal-wrap) {
  border: none;
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 20px 60px rgba($brand-blue-black, 0.18), 0 8px 24px rgba($brand-blue-black, 0.10);
  flex: 1 1 auto;
  min-height: 0;
  max-height: none !important;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.beta-feedback-modal-wrap {
  background: #fff;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

/* Header: about-page hero composition, centered inside a la-modal-header
   shell with the close button pinned to the top-right. */
.beta-feedback-modal-wrap > .la-modal-header {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding: 28px 28px 20px;
  border-bottom: 1px solid var(--md-line, rgba($brand-blue-black, 0.1));
  background: rgba(255, 255, 255, 0.6);
}
.beta-feedback-modal__hero {
  flex: 1 1 auto;
  min-width: 0;
  text-align: center;
}
/* Mirror the about-page hero treatment for the modal header. .la-hero-title
   and the eyebrow margin override are both scoped to .la-wrapper /
   .la-wrapper--about in their original definitions, so we re-apply the
   computed about-page values here. */
.beta-feedback-modal__hero .la-section-eyebrow-badge {
  margin-bottom: 2.5rem;
}
.beta-feedback-modal__title {
  font-family: 'Maitree', serif;
  font-weight: 600;
  color: $indigo;
  line-height: 1.08;
  letter-spacing: -0.025em;
  margin: 0 0 $aac-spacing-24;
  font-size: 35px;
  @media (max-width: 1366px) { font-size: 27px; }
  @media (max-width: 1200px) { font-size: 24px; }
  @media (max-width: 1024px) { font-size: 20px; }
  @media (max-width: 480px)  { font-size: 17px; }
}
/* Match the support-page rule (.la-wrapper--support .hero-gradient) so the
   "Feedback" gradient text sizes 1:1 with "Beta " — without this it inherits
   the global 1.155em and reads slightly larger than the prefix. */
.beta-feedback-modal__title .hero-gradient {
  font-size: 1em;
}
.beta-feedback-modal__subtitle {
  margin: 1.5rem auto 0;
  max-width: 680px;
  font-size: 24px;
  font-weight: 400;
  color: $brand-charcoal-dark;
  line-height: 1.75;
  letter-spacing: 0.005em;
}
.beta-feedback-modal-wrap > .la-modal-header > .la-modal-close {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  min-width: 48px;
  min-height: 48px;
  padding: 0;
  margin: 0;
  border: 1px solid rgba($brand-blue-black, 0.12);
  border-radius: 50%;
  background: $surface-300;
  color: var(--md-muted, $brand-slate-gray);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}
.beta-feedback-modal-wrap > .la-modal-header > .la-modal-close:hover,
.beta-feedback-modal-wrap > .la-modal-header > .la-modal-close:focus-visible {
  background: #fff;
  color: $brand-charcoal-dark;
  outline: none;
}

/* Body: scrolls when content overflows the available modal height. */
.beta-feedback-modal__body {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding: 24px 28px 28px;
}

@media (max-width: 600px) {
  .beta-feedback-modal-wrap > .la-modal-header {
    padding: 20px 20px 16px;
  }
  .beta-feedback-modal__subtitle {
    font-size: 16px;
  }
  .beta-feedback-modal__body {
    padding: 18px 20px 20px;
  }
}

/* Beta onboarding modal — compact welcome flow (sibling of beta-feedback-modal). */
.modal .modal-dialog:has(.beta-onboarding-modal-wrap) {
  max-width: 560px;
  width: calc(100vw - 32px);
  height: auto;
  max-height: calc(100vh - 32px);
  margin: 16px auto;
  display: flex;
  flex-direction: column;
}
.modal .modal-dialog:has(.beta-onboarding-modal-wrap) > * {
  flex: 0 1 auto;
  display: flex;
  flex-direction: column;
}
.modal-content:has(.beta-onboarding-modal-wrap) {
  border: none;
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 20px 60px rgba($brand-blue-black, 0.18), 0 8px 24px rgba($brand-blue-black, 0.10);
  height: auto !important;
  max-height: calc(100vh - 32px) !important;
  display: flex;
  flex-direction: column;
}

.beta-onboarding-modal-wrap {
  background: #fff;
  display: flex;
  flex-direction: column;
}

.beta-onboarding-modal__header {
  position: relative;
  text-align: center;
  padding: 32px 28px 20px;
  background: linear-gradient(180deg, rgba($brand-teal, 0.06), rgba(255, 255, 255, 0));
  border-bottom: 1px solid rgba($brand-blue-black, 0.08);
}

.beta-onboarding-modal__close {
  position: absolute;
  top: 16px;
  right: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  min-width: 36px;
  min-height: 36px;
  padding: 0;
  margin: 0;
  border: 1px solid rgba($brand-blue-black, 0.12);
  border-radius: 50%;
  background: $surface-300;
  color: var(--md-muted, $brand-slate-gray);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}
.beta-onboarding-modal__close:hover,
.beta-onboarding-modal__close:focus-visible {
  background: #fff;
  color: $brand-charcoal-dark;
  outline: none;
}

.beta-onboarding-modal__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  margin: 0 auto 16px;
  border-radius: 50%;
  background: rgba($brand-teal, 0.12);
  color: $brand-teal;
}
.beta-onboarding-modal__icon-svg {
  display: block;
}

.beta-onboarding-modal__title {
  font-family: 'Maitree', serif;
  font-size: 22px;
  font-weight: 600;
  color: $indigo;
  text-align: center;
  margin: 0;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

.beta-onboarding-modal__body {
  padding: 24px 28px;
  text-align: center;
}
.beta-onboarding-modal__lead {
  margin: 0 0 20px;
  font-size: 15px;
  line-height: 1.6;
  color: $brand-charcoal-dark;
}

.beta-onboarding-modal__steps {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 8px;
}
.beta-onboarding-modal__step-pill {
  display: inline-block;
  border-radius: 999px;
  padding: 3px 10px;
  font-size: 12px;
  font-weight: 600;
  background: rgba($brand-teal, 0.12);
  color: rgba($brand-charcoal-dark, 0.5);
}
.beta-onboarding-modal__step-pill--active {
  background: $brand-teal;
  color: #fff;
}

.beta-onboarding-modal-wrap .onboarding-video-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  height: 200px;
  margin: 0 0 20px;
  padding: 16px;
  background: rgba($brand-blue-black, 0.04);
  border: 2px dashed rgba($brand-charcoal-blue, 0.18);
  border-radius: 14px;
}
.beta-onboarding-modal-wrap .onboarding-video-placeholder__play {
  display: block;
  color: rgba($brand-charcoal-blue, 0.35);
}
.beta-onboarding-modal-wrap .onboarding-video-placeholder__label {
  margin: 0;
  font-size: 14px;
  color: rgba($brand-charcoal-dark, 0.5);
}

.beta-onboarding-modal__footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 16px 28px 24px;
  border-top: 1px solid rgba($brand-blue-black, 0.07);
}
.beta-onboarding-modal__footer .btn {
  border-radius: 999px;
  min-height: 44px;
  padding: 10px 24px;
  font-size: 15px;
  font-weight: 600;
  transition: background 0.18s ease, box-shadow 0.18s ease, transform 0.15s ease;
}
.beta-onboarding-modal__footer .btn-primary {
  box-shadow: 0 6px 16px rgba($brand-charcoal-blue, 0.22);
}
.beta-onboarding-modal__footer .btn-primary:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 10px 22px rgba($brand-charcoal-blue, 0.28);
}

@media (max-width: 600px) {
  .beta-onboarding-modal__header {
    padding: 28px 20px 18px;
  }
  .beta-onboarding-modal__body {
    padding: 20px;
  }
  .beta-onboarding-modal__footer {
    padding: 14px 20px 20px;
    flex-wrap: wrap;
  }
  .beta-onboarding-modal__footer .btn {
    flex: 1 1 auto;
    min-width: 0;
  }
}

.la-wrapper--support .la-support-cookies-btn {
  font-size: 14px; /* 25% larger than 1rem */
}

/* About "Built around" section: same 1px divider as top of page */
.la-wrapper.la-wrapper--about #about-what-we-offer .la-section-header .la-about-hero-separator,
.la-wrapper.la-wrapper--about #faq-items .la-section-header .la-about-hero-separator,
.la-wrapper.la-wrapper--about #faq-questions .la-section-header .la-about-hero-separator {
  height: 1px;
  max-width: 100%;
  border: none;
  border-radius: 0;
  background: rgba(0, 0, 0, 0.12);
}

.la-wrapper.la-wrapper--about #about-hero .la-pricing-hero-subtitle,
.la-wrapper.la-wrapper--about #faq-hero .la-pricing-hero-subtitle {
  max-width: 748px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: 2rem;
  padding-left: 1rem;
  padding-right: 1rem;
}

.la-wrapper.la-wrapper--about #about-hero .la-section-header + .la-feature-grid {
  margin-top: -2rem;
}

/* Features page hero: same layout and styling as about hero top */
.la-wrapper.la-wrapper--about #features-hero .la-section-header,
.la-wrapper.la-wrapper--features #features-hero .la-section-header {
  margin-bottom: 0;
  max-width: 748px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 1rem;
  padding-right: 1rem;
  width: 100%;
  box-sizing: border-box;
  text-align: center;
}

/* Public Speak Mode demo */
#within_ember:has(#content .demo-board-page) {
  --topbar-height: 0px !important;
}

#within_ember:has(#content .demo-board-page) #content {
  padding-top: 0 !important;
}

.demo-board-page {
  min-height: 100vh;
  box-sizing: border-box;
  padding: 0.75rem;
  background:
    radial-gradient(circle at top left, rgba(44, 183, 176, 0.16), transparent 28rem),
    linear-gradient(135deg, #070b12 0%, #111722 50%, #0b111b 100%);
}

.demo-board-page--speak-only {
  height: 100dvh;
  min-height: 100dvh;
  overflow: hidden;
}

.demo-board-page__main {
  gap: 1rem;
  width: 100%;
  max-width: none;
  margin: 0;
}

.demo-board-page--speak-only .demo-board-page__main {
  height: 100%;
  min-height: 0;
  overflow: hidden;
}

.demo-board-page__intro,
.demo-board-page__style-panel,
.demo-board-page__board {
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 24px;
  background: linear-gradient(180deg, #0c1018 0%, #151a24 100%);
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.32);
}

.demo-board-page__intro {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.25rem 1.5rem;
}

.demo-board-page__intro h1 {
  margin: 0.1rem 0 0.35rem;
  color: #f8fafc;
  font-size: clamp(2rem, 4vw, 3.25rem);
  line-height: 1.05;
}

.demo-board-page__intro p {
  max-width: 760px;
  margin: 0;
  color: rgba(255, 255, 255, 0.74);
  font-size: 1.1rem;
}

.demo-board-page__eyebrow {
  margin: 0;
  color: #8fe4df !important;
  font-size: 0.95rem !important;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.demo-board-page__intro-actions,
.demo-board-page__board-title {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.demo-board-page__sentence-row {
  position: sticky;
  top: 0.75rem;
  z-index: 20;
  align-items: stretch;
  width: 100%;
  min-width: 0;
  overflow: hidden;
}

.demo-board-page .md-board-detail-sentence-bar {
  min-width: 0;
  overflow: hidden;
}

.demo-board-page__sentence-preview {
  flex: 1 1 0;
  min-width: 0;
  max-width: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font: inherit;
  text-align: left;
}

.demo-board-page .demo-board-page__sentence-preview.md-board-detail-sentence-bar__text--with-symbols {
  flex-wrap: nowrap;
  justify-content: flex-start;
  overflow: hidden;
}

.demo-board-page .md-board-detail-sentence-bar__actions {
  flex: 0 0 auto;
}

.demo-board-page__sentence-preview .md-board-detail-sentence-bar__chip {
  flex: 0 0 auto;
  align-self: center;
  height: 54px;
  min-width: 40px;
  min-height: 0;
  max-height: 54px;
  padding: 2px 6px;
  overflow: hidden;
}

.demo-board-page__sentence-preview .md-board-detail-sentence-bar__chip-img {
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
}

.demo-board-page__sentence-preview .md-board-detail-sentence-bar__chip-label {
  max-width: 54px;
  overflow: hidden;
  font-size: 14px;
  line-height: 1.05;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.demo-board-page__sentence-ellipsis {
  flex: 0 0 auto;
  align-self: center;
  padding: 0 0.55rem;
  color: rgba(255, 255, 255, 0.74);
  font-size: 1.65rem;
  font-weight: 800;
  letter-spacing: 0.04em;
}

.demo-board-page__sentence-text-preview {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.demo-board-page__sentence-dialog-backdrop {
  position: fixed;
  z-index: 2000;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  background: rgba(0, 0, 0, 0.58);
}

.demo-board-page__sentence-dialog {
  width: 96vw;
  max-width: 920px;
  max-height: 76vh;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 24px;
  background: linear-gradient(180deg, #0c1018 0%, #151a24 100%);
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
  color: #f8fafc;
}

.demo-board-page__sentence-dialog-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 1.15rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
}

.demo-board-page__sentence-dialog-header h2 {
  margin: 0;
  color: #f8fafc;
  font-size: 1.35rem;
}

.demo-board-page__sentence-dialog-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.08);
  color: #f8fafc;
  cursor: pointer;
  font-size: 1.8rem;
  line-height: 1;
}

.demo-board-page__sentence-dialog-body {
  max-height: 60vh;
  overflow: auto;
  padding: 1rem;
  color: #f8fafc;
  font-size: 1.4rem;
  line-height: 1.4;
}

.demo-board-page__sentence-dialog-body--symbols {
  display: flex;
  align-items: stretch;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.demo-board-page__sentence-dialog-chip {
  flex: 0 0 auto;
}

.demo-board-page__exit-link,
.demo-board-page__settings-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 52px;
  min-width: 52px;
  min-height: 52px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 18px;
  background: rgba(47, 63, 86, 0.92);
  color: #fff;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08), 0 8px 20px rgba(15, 23, 42, 0.18);
  cursor: pointer;
  padding: 0;
  text-decoration: none;
}

.demo-board-page__exit-link:hover,
.demo-board-page__exit-link:focus-visible,
.demo-board-page__settings-link:hover,
.demo-board-page__settings-link:focus-visible,
.demo-board-page__settings-link--active {
  color: #fff;
  background: rgba(58, 107, 199, 0.95);
  outline: none;
}

.demo-board-page__status {
  margin: 0;
  padding: 0.85rem 1rem;
  border: 1px solid rgba(20, 127, 130, 0.18);
  border-radius: 16px;
  background: rgba(20, 127, 130, 0.08);
  color: #0f4f52;
  font-size: 1rem;
  font-weight: 700;
}

.demo-board-page__board {
  width: 100%;
  padding: 0.5rem;
}

.demo-board-page--speak-only .demo-board-page__board {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}

.demo-board-page--speak-only .demo-board-page__board > .ember-view {
  flex: 1 1 auto;
  align-self: center;
  min-width: 0;
  min-height: 0;
  max-width: 100%;
