// ── Feature grid & cards (landing-alt + about "What We Offer" + features page + features modal) ─
#la-features,
#about-what-we-offer,
#faq-items,
#faq-questions,
#features-hero,
.la-features-modal-body {
.la-feature-grid {
  display: grid;
    /* auto-fit handles wrapping without explicit breakpoints: at ≥~930px → 3 cols,
       ≥~620px → 2 cols, below that → 1 col. No media queries needed. */
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 32px;
    align-items: stretch;
  }

  .la-feature-card {
    display: flex;
    flex-direction: column;
    background: #ffffff;
    border: 1px solid rgba($indigo, 0.06);
    border-radius: 28px;
    box-shadow:
      0 8px 20px rgba(0, 0, 0, 0.06),
      0 2px 6px rgba(0, 0, 0, 0.04);
    padding: 40px 32px 32px;
    text-align: center;
  }

  .la-feature-card h3 {
    margin: 0 0 16px;
  }

  .la-feature-card p {
    margin: 0;
  }

  .la-feature-icon {
    width: 64px;
    height: 64px;
    margin: 0 auto 20px;
    border-radius: 18px;
    display: grid;
    place-items: center;
    font-size: 30px;
    line-height: 1;
    border: 1px solid rgba($indigo, 0.05);
  box-shadow:
      0 6px 14px rgba(0, 0, 0, 0.05),
      inset 0 1px 0 rgba(255, 255, 255, 0.7);
  }

  /* Soften icon color surfaces to match system */
  .la-feature-icon--coral {
    background: linear-gradient(
      180deg,
      rgba(240, 106, 91, 0.10),
      rgba(240, 106, 91, 0.05)
    );
  }

  .la-feature-icon--teal {
    background: linear-gradient(
      180deg,
      rgba(63, 127, 123, 0.10),
      rgba(63, 127, 123, 0.05)
    );
  }

  .la-feature-icon--navy {
    background: linear-gradient(
      180deg,
      rgba($indigo, 0.08),
      rgba($indigo, 0.04)
    );
  }

  /* (Stagger removed — was a 24px offset on cards 4–6 tuned for the fixed
     3×2 grid. With auto-fit wrapping, cards 4–6 land in varying positions
     so the stagger created uneven vertical gaps when the grid wrapped.) */

  .la-feature-card--faq {
    grid-column: 1 / -1;
    width: 100%;
    max-width: min(64rem, 100%);
    margin-left: auto;
    margin-right: auto;
    text-align: left;
  }

  .la-feature-card--faq .la-feature-icon {
    margin-left: 0;
    margin-right: auto;
  }

  .la-feature-card--faq h3 {
    text-align: left;
  }

  .la-faq-card__text {
    margin: 0;
    font-size: 17px;
    line-height: 1.75;
    color: rgba($indigo, 0.88);
    text-align: left;
  }

  .la-feature-card--faq .la-faq-card__text + .la-faq-card__text {
    margin-top: 1rem;
  }

  .la-faq-list {
    margin: 0.5rem 0 0;
    padding-left: 1.35rem;
    text-align: left;
    line-height: 1.75;
    font-size: 17px;
    color: rgba($indigo, 0.88);
  }

  .la-faq-list li {
    margin-bottom: 0.5rem;
  }

  .la-faq-list li:last-child {
    margin-bottom: 0;
  }

  .la-faq-article__title {
    margin: 0 0 0.25rem;
  }

  .la-faq-article-body {
    margin-top: 0.75rem;
  }

  .la-faq-read-toggle {
    margin: 0;
    padding: 0.5rem 0;
    min-height: 44px;
    align-self: flex-start;
    background: none;
    border: none;
    font-family: inherit;
    font-size: 17px;
    font-weight: $aac-font-weight-bold;
    color: $brand-teal;
    text-decoration: underline;
    text-underline-offset: 3px;
    cursor: pointer;
    text-align: left;

    &:hover {
      color: $brand-stormy-teal;
    }

    &:focus-visible {
      @include focus-ring($color: $brand-verdigris);
    }
  }

  .la-faq-read-toggle--after {
    margin-top: 1rem;
  }

  .la-faq-subhead {
    margin: 1.75rem 0 0.65rem;
    font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
    font-size: 14px;
    font-weight: $aac-font-weight-bold;
    color: $indigo;
    line-height: 1.35;
    text-align: left;
  }

  .la-faq-article-body .la-faq-subhead:first-of-type {
    margin-top: 0.25rem;
  }

  .la-faq-type-block__title {
    margin: 1.25rem 0 0.5rem;
    font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
    font-size: 14px;
    font-weight: $aac-font-weight-bold;
    color: $brand-teal;
    line-height: 1.4;
    text-align: left;
  }

  .la-faq-type-block {
    margin-top: 1rem;
    padding: $aac-spacing-20 $aac-spacing-24;
    background: rgba(63, 127, 123, 0.06);
    border: 1px solid rgba(63, 127, 123, 0.14);
    border-radius: $aac-radius-lg;
    text-align: left;
  }

  .la-faq-type-block--follow {
    margin-top: $aac-spacing-20;
  }

  .la-faq-type-block .la-faq-type-block__title:first-child {
    margin-top: 0;
  }

  .la-faq-inline-label {
    margin: 1rem 0 0.35rem;
    font-size: 16px;
    font-weight: $aac-font-weight-bold;
    color: rgba($indigo, 0.92);
    text-align: left;
  }

  .la-faq-type-block .la-faq-inline-label:first-of-type {
    margin-top: 0.5rem;
  }

  .la-faq-lead {
    font-weight: $aac-font-weight-bold;
    color: rgba($indigo, 0.95);
  }

  .la-faq-list--tight {
    margin-top: 0.35rem;
  }

  .la-faq-list--tight li {
    margin-bottom: 0.35rem;
  }

  .la-faq-callout {
    margin: 1.25rem 0;
    padding: $aac-spacing-20 $aac-spacing-24;
    background: linear-gradient(135deg, rgba(58, 107, 199, 0.08), rgba($brand-teal, 0.08));
    border-left: 4px solid $brand-smart-blue;
    border-radius: 0 $aac-radius-md $aac-radius-md 0;
    text-align: left;
  }

  .la-faq-callout__title {
    margin: 0 0 0.5rem;
    font-size: 17px;
    font-weight: $aac-font-weight-bold;
    color: $indigo;
  }

  .la-faq-callout__text {
    margin: 0;
    font-size: 17px;
    line-height: 1.75;
    color: rgba($indigo, 0.9);
  }
}

#faq-items .la-feature-grid,
#faq-questions .la-feature-grid {
  gap: $aac-spacing-28;
}

/* FAQ articles: use more horizontal space on large screens (cards were capped at ~52rem) */
@media (min-width: 1100px) {
  #faq-items .la-feature-card--faq,
  #faq-questions .la-feature-card--faq {
    max-width: min(76rem, 100%);
  }
}

@media (min-width: 1400px) {
  #faq-items .la-feature-card--faq,
  #faq-questions .la-feature-card--faq {
    max-width: min(88rem, 100%);
  }
}

/* Tablet: tighter gap and disable stagger. Column count handled by auto-fit
   on the base rule — no need to hard-set grid-template-columns here. */
@media (max-width: 1024px) {
  #la-features,
  #about-what-we-offer,
  #faq-items,
  #faq-questions,
  .la-features-modal-body {
    .la-feature-grid {
      gap: 24px;
    }

    .la-feature-card:nth-child(4),
    .la-feature-card:nth-child(5),
    .la-feature-card:nth-child(6) {
      transform: none;
    }
  }
}

/* Phone: tighter gap + smaller card padding. auto-fit collapses to 1 column
   naturally around ~620px based on the 280px minmax. */
@media (max-width: 820px) {
  #la-features,
  #about-what-we-offer,
  #faq-items,
  #faq-questions,
  .la-features-modal-body {
    .la-feature-grid {
      gap: 20px;
    }

    .la-feature-card {
      padding: 32px 24px 28px;
      border-radius: 24px;
    }

    .la-feature-icon {
      width: 56px;
      height: 56px;
      font-size: 26px;
      margin-bottom: 16px;
    }
  }
}

// Scroll-triggered entrance: cards start hidden, animate when section is in view
@keyframes la-feature-card-enter {
  from {
    opacity: 0;
    transform: translateY(28px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes la-feature-card-enter-stagger {
  from {
    opacity: 0;
    transform: translateY(52px); /* slide distance only — no resting offset */
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Landing-alt "Why LingoLinq" specifically — 3×2 grid (3 cards per row, 2 rows)
   on max screens, dropping to 2-col at 820px (iPad landscape) and 1-col at 480px.
   Overrides the shared auto-fit rule that other sections still use. */
#la-features .la-feature-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
@media (max-width: 820px) {
  #la-features .la-feature-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 480px) {
  #la-features .la-feature-grid {
    grid-template-columns: 1fr;
  }
}

#la-features .la-feature-card {
  opacity: 0;
  transform: translateY(28px);
}

/* Cards 4-6 used to start 52px lower (for the zigzag effect). Now that the
   grid wraps with auto-fit, a card's position in a row isn't stable at every
   viewport width, so all cards share the same 28px initial offset. */
#la-features .la-feature-card:nth-child(4),
#la-features .la-feature-card:nth-child(5),
#la-features .la-feature-card:nth-child(6) {
  transform: translateY(28px);
}

#la-features.la-features-visible .la-feature-card {
  animation: la-feature-card-enter 0.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

#la-features.la-features-visible .la-feature-card:nth-child(4),
#la-features.la-features-visible .la-feature-card:nth-child(5),
#la-features.la-features-visible .la-feature-card:nth-child(6) {
  animation: la-feature-card-enter-stagger 0.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

@media (max-width: 1024px) {
  #la-features .la-feature-card:nth-child(4),
  #la-features .la-feature-card:nth-child(5),
  #la-features .la-feature-card:nth-child(6) {
    transform: translateY(28px);
  }
  #la-features.la-features-visible .la-feature-card:nth-child(4),
  #la-features.la-features-visible .la-feature-card:nth-child(5),
  #la-features.la-features-visible .la-feature-card:nth-child(6) {
    animation-name: la-feature-card-enter;
  }
}

#la-features.la-features-visible .la-feature-card:nth-child(1) { animation-delay: 0.05s; }
#la-features.la-features-visible .la-feature-card:nth-child(2) { animation-delay: 0.12s; }
#la-features.la-features-visible .la-feature-card:nth-child(3) { animation-delay: 0.19s; }
#la-features.la-features-visible .la-feature-card:nth-child(4) { animation-delay: 0.26s; }
#la-features.la-features-visible .la-feature-card:nth-child(5) { animation-delay: 0.33s; }
#la-features.la-features-visible .la-feature-card:nth-child(6) { animation-delay: 0.4s; }

