.la-wrapper.la-wrapper--about .la-plan-section .la-plan-check {
  background: rgba($brand-teal, 0.2);
  color: $brand-stormy-teal;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.08), 0 1px 2px rgba(0, 0, 0, 0.05);
