  font-weight: $aac-font-weight-medium;
}

// ── CTA Section ─────────────────────────────────────────────────────────────
.la-cta-section {
  padding: $aac-spacing-64 $aac-spacing-40;
  position: relative;
  overflow: hidden;
  border-radius: 24px;
}

@keyframes la-cta-gradient-shift {
  0%, 100% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
}

/* Ready to start: modern CTA container with double outline (landing-alt), slightly lighter gradient */
.la-wrapper #la-cta.la-cta-section {
  max-width: 900px;
  width: 92%;
  margin-top: 24px;
  margin-bottom: 24px;
  margin-left: auto;
  margin-right: auto;
  padding: 48px 64px 56px;
  border-radius: 24px;
  background: linear-gradient(
    125deg,
    #f2faf9 0%,
    #fcfbf5 20%,
    #eef8f7 42%,
    #fefdf8 62%,
    #f2faf9 82%,
    #fcfbf5 100%
  );
  background-size: 200% 200%;
  animation: la-cta-gradient-shift 12s ease-in-out infinite;
  border: 2px solid rgba(63, 127, 123, 0.16);
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.85) inset,
    0 0 0 3px rgba(63, 127, 123, 0.12),
    $la-shadow-md;
  transition: box-shadow 0.25s ease, transform 0.25s ease;

  &:hover {
    box-shadow:
      0 0 0 1px rgba(255, 255, 255, 0.9) inset,
      0 0 0 3px rgba(63, 127, 123, 0.2),
      0 12px 28px rgba(0, 0, 0, 0.06),
      0 4px 8px rgba(0, 0, 0, 0.04);
  }

  .la-cta-headline { margin-bottom: 12px; }
  .la-cta-description { margin-bottom: 28px; }
  .la-cta-buttons { gap: 16px; }
  .la-cta-buttons .la-btn {
    min-height: 56px;
    padding: $aac-spacing-12 30px;
  }
  .la-cta-buttons .la-btn--lg {
    min-height: 56px;
    padding: $aac-spacing-14 32px;
  }
}

// CTA with no bg: use dark text and ghost button for contrast on page background
.la-wrapper .la-cta-section .la-cta-headline {
  color: $la-navy;
  margin-bottom: 24px;

  em {
    font-style: normal;
    color: $brand-smart-blue; /* same as "nothing you don't" (.la-plan-title em) */
  }
}
.la-wrapper .la-cta-section .la-cta-description {
  color: rgba($indigo, 0.9);
}
/* Glass badge (matches Why LingoLinq / What educators say / Accessibility First) — see #la-features block */
.la-wrapper .la-cta-section .la-cta-eyebrow {
  color: #0d5c5f;
  padding: 6px $aac-spacing-20;
  font-weight: $aac-font-weight-bold;
}
/* Schedule a District Demo: same bg, shadow, etc. as hero "Watch Demo" */
.la-wrapper .la-cta-section .la-btn--ghost {
  font-weight: $aac-font-weight-semi;
  background: rgba($brand-charcoal-blue, 0.7);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  color: rgba(255, 255, 255, 0.86);
  border: 1px solid rgba(255, 255, 255, 0.11);
  padding: 14px 26px;
  border-radius: 28px;
  transform: translateY(-2px);
  box-shadow: none;
  transition: background 0.25s ease, border-color 0.25s ease, color 0.25s ease, transform 0.2s ease, box-shadow 0.25s ease;

  &:hover {
    background: rgba(78, 88, 102, 0.8);
    color: rgba(255, 255, 255, 0.95);
    border-color: rgba(255, 255, 255, 0.18);
    text-decoration: none;
    transform: translateY(-3px);
    box-shadow: none;
  }
}

.la-cta-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  position: relative;
  z-index: 1;
  max-width: 560px;
  margin: 0 auto;
}

.la-cta-eyebrow {
  display: inline-block;
  font-size: $aac-font-size-xs * 1.38;
  font-weight: $aac-font-weight-medium;
  text-transform: uppercase;
  letter-spacing: $aac-letter-spacing-wide;
  color: rgba($brand-honey-bronze, 0.9);
  background: transparent;
  border: 1px solid rgba($brand-honey-bronze, 0.35);
  border-radius: $aac-radius-pill;
  padding: 5px $aac-spacing-16;
  margin-bottom: $aac-spacing-24;
}

.la-wrapper .la-cta-headline {
  font-family: 'Maitree', serif;
  font-size: 38px;
  font-weight: normal;
  color: white;
  letter-spacing: -0.025em;
  line-height: 1.15;
  margin: 0 0 $aac-spacing-16;
}

.la-cta-section .la-cta-description {
  font-size: $aac-font-size-base * 1.15;
  font-weight: 400;
  color: rgba($indigo, 0.9);
  line-height: 1.8;
  letter-spacing: 0.005em;
  margin: 0 0 $aac-spacing-32;
}

/* Start Free Today: same bg, shadow, etc. as hero "Try LingoLinq Free" */
.la-cta-section .la-btn--primary {
  background: $la-hero-cta-bg;
  color: $la-navy;
  border: 1px solid rgba($brand-honey-bronze, 0.5);
  filter: brightness(1.02);
  box-shadow: none;

  &:hover {
    filter: brightness(0.96);
    box-shadow: none;
    color: $la-navy;
  }
}

.la-cta-buttons {
  display: flex;
  gap: $aac-spacing-16;
  align-items: center;
  flex-wrap: wrap;
  justify-content: center;
}

/* Pricing page CTA: match landing-alt hero buttons (Try LingoLinq / Watch Demo) */
.la-wrapper.la-wrapper--pricing .la-cta-buttons .la-btn--primary {
  background: $la-cta-gradient;
  color: $la-navy;
  border: 1px solid rgba(232, 122, 111, 0.5);
  filter: brightness(1.02);
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.2), 0 2px 5px rgba(0, 0, 0, 0.1);
  animation: ctaGlow 6s ease-in-out infinite;

  &:hover {
    filter: brightness(0.96);
    box-shadow: 0 10px 36px rgba(0, 0, 0, 0.25), 0 4px 12px rgba(0, 0, 0, 0.12);
    color: $la-navy;
  }
}

.la-wrapper.la-wrapper--pricing .la-cta-buttons .la-btn--ghost,
.la-wrapper.la-wrapper--pricing .la-pricing-cloud-extras-cta .la-btn--ghost {
  font-weight: $aac-font-weight-semi;
  background: rgba(255, 255, 255, 0.22);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  color: $la-navy;
  border: 1px solid rgba(0, 0, 0, 0.12);
  padding: $aac-spacing-12 30px;
  border-radius: $aac-radius-pill;
  box-shadow:
    0 4px 56px rgba(0, 0, 0, 0.012),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
  transition: background 0.25s ease, border-color 0.25s ease, color 0.25s ease, transform 0.2s ease, box-shadow 0.25s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.32);
    color: $la-navy;
    border-color: rgba(0, 0, 0, 0.18);
    text-decoration: none;
    box-shadow:
      0 6px 24px rgba(0, 0, 0, 0.08),
      inset 0 1px 0 rgba(255, 255, 255, 0.22);
  }
}

/* Ready to start section: animate entire block when section scrolls into view */
@keyframes la-cta-section-enter {
  from {
    opacity: 0;
    transform: translateY(32px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

#la-cta .la-cta-inner {
  opacity: 0;
  animation: la-cta-section-enter 0.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  animation-play-state: paused;
}

#la-cta.la-cta-visible .la-cta-inner {
  animation-play-state: running;
}

.la-btn--lg {
  padding: $aac-spacing-14 $aac-spacing-32;
  font-size: $aac-font-size-base;
}

.la-btn--ghost {
  background: transparent;
  color: rgba(white, 0.75);
  border: 1px solid rgba(white, 0.2);
  padding: $aac-spacing-10 $aac-spacing-24;
  border-radius: $aac-radius-pill;
  font-size: $aac-font-size-sm;
  font-weight: $aac-font-weight-semi;
  text-decoration: none;
  transition: all 0.2s ease;
  cursor: pointer;

  &:hover {
    background: rgba(white, 0.08);
    color: white;
    border-color: rgba(white, 0.35);
  }
}

// ── A11y bar ─────────────────────────────────────────────────────────────────
.la-a11y-bar {
  display: flex;
  align-items: flex-start;
  gap: $aac-spacing-14;
  background: $cat-actions-bg;
  border: 1px solid $cat-actions-base;
  border-radius: $aac-radius-lg;
  padding: $aac-spacing-16 $aac-spacing-20;

  p {
    font-size: $aac-font-size-sm;
    color: $color-text-mid;
    margin: 0;
    line-height: $aac-line-height-loose;
  }

  a {
    color: $cat-actions-text;
    font-weight: $aac-font-weight-bold;

    &:hover { color: $color-text; }
  }

  .la-sidebar & {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: $aac-spacing-4 $aac-spacing-8;
    align-items: center;
    padding: $aac-spacing-12;
    background: linear-gradient(135deg, rgba($la-navy, 0.04) 0%, white 60%);
    border-color: rgba($la-navy, 0.3);

    a { color: $indigo; &:hover { color: color.adjust($indigo, $lightness: -10%); } }
    font-size: $la-panel-font-size-xs * 1.09;

    .la-a11y-icon { grid-row: 1; grid-column: 1; padding-right: $aac-spacing-12; }
    .la-a11y-heading { grid-row: 1; grid-column: 2; font-size: $la-panel-font-size-base * 1.035; color: $indigo; }
    p { grid-row: 2; grid-column: 1 / -1; font-size: $la-panel-font-size-xs * 1.1 * 1.09; color: $indigo; word-wrap: break-word; overflow-wrap: break-word; }
    p strong { color: $brand-teal; }
  }
}

.la-a11y-icon {
  font-size: 36px;
  flex-shrink: 0;
  margin-top: 2px;
}

// ── Divider ──────────────────────────────────────────────────────────────────
.la-divider {
  border: none;
  height: 2px;
  background: linear-gradient(90deg, transparent 0%, rgba($la-teal, 0.25) 30%, rgba($la-teal, 0.25) 70%, transparent 100%);
  margin: 0;
}

// ── Footer (modern) ───────────────────────────────────────────────────────────
.la-footer {
  /* Zero horizontal padding so the bg tint extends edge-to-edge; the centered
     content column is handled by .la-footer-inner's max-width + margin:auto.
     Full-bleed full-viewport-width: the footer sits inside `.la-main` which
     has heavy left/right padding (calc(spacing-28 + 5rem)) — that padding
     would otherwise inset the footer's tinted background. Using the
     standard 100vw + negative margin-left/right trick breaks the footer
     out of `.la-main`'s content box and lets its background paint
     edge-to-edge at every screen width. */
  padding-top: $aac-spacing-48;
  padding-right: 0;
  padding-bottom: $aac-spacing-40;
  padding-left: 0;
  margin-top: 0;
  background: rgba($la-navy, 0.03);
  border-top: none;
  position: relative;
  width: 100vw;
  margin-left: calc(50% - 50vw);
  margin-right: calc(50% - 50vw);
}

.la-footer-inner {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: $aac-spacing-40 $aac-spacing-32;
  margin-bottom: $aac-spacing-40;
  max-width: 1200px;
  margin-left: auto;
  margin-right: auto;
  padding: 0;

  @include aac-respond-to('lg') {
    grid-template-columns: 1fr 1fr;
    gap: $aac-spacing-32 $aac-spacing-24;
  }
}

.la-footer-brand {
  max-width: 320px;

  p {
    font-size: $aac-font-size-sm;
    color: rgba($la-navy, 0.7);
    line-height: 1.65;
    margin: $aac-spacing-14 0 0;
    letter-spacing: 0.01em;
  }
}

/* Footer logo: ~25% narrower, no gap after image, Lingo and Linq same style */
.la-footer-logo {
  display: inline-flex;
  align-items: center;
  gap: 0;
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: $aac-font-size-lg * 0.75;
  font-weight: $aac-font-weight-black;
  letter-spacing: $aac-letter-spacing-base;
  white-space: nowrap;
  text-decoration: none;
  color: $la-logo-left;
  transition: opacity 0.2s ease;

  .app-logo__lingo,
  .app-logo__linq,
  & > span:first-child,
  & > span:last-child {
    color: $la-logo-left;
    font-style: normal;
  }

  &:hover {
    text-decoration: none;
    opacity: 0.88;
  }
}

.la-footer-logo-img {
  height: auto; /* width set via size="75px" (25% narrower than default 100px); keep aspect ratio */
}

.la-footer-col {
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-12;

  nav {
    display: flex;
    flex-direction: column;
    gap: $aac-spacing-8;
  }

  h4 {
    font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
    font-size: 14px;
    font-weight: $aac-font-weight-black;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: rgba($la-navy, 0.75);
    margin: 0 0 $aac-spacing-4;
  }

  a,
  a:visited {
    font-size: $aac-font-size-sm;
    color: $la-navy;
    text-decoration: none;
    transition: color 0.2s ease, opacity 0.2s ease;

    &:hover {
      color: $brand-teal;
      text-decoration: none;
    }
  }
}

.la-footer-link-btn {
  background: none;
  border: none;
  padding: 0;
  margin: 0;
  font-size: $aac-font-size-sm;
  font-family: inherit;
  color: rgba($la-navy, 0.85);
  text-decoration: none;
  text-align: left;
  cursor: pointer;
  transition: color 0.2s ease, opacity 0.2s ease;

  &:hover {
    color: $brand-teal;
    text-decoration: none;
  }
}

.la-footer-link-btn:focus-visible {
  @include focus-ring($color: $brand-verdigris);
}

.la-footer-bottom {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  justify-content: space-between;
  gap: $aac-spacing-12;
  padding-top: $aac-spacing-28;
  border-top: 1px solid rgba($la-navy, 0.08);
  max-width: 1200px;
  margin-left: auto;
  margin-right: auto;
}

.la-footer-bottom__copy {
  font-size: $aac-font-size-xs;
  color: rgba($la-navy, 0.75);
  letter-spacing: 0.02em;
  flex: 0 0 auto;
  white-space: nowrap;
}

.la-footer-bottom-trailing {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  gap: $aac-spacing-10;
  flex: 0 0 auto;
}

/* Hero-aligned pill: same radius, surface, and shadow as .la-hero-badge (Cloud-based, etc.) */
a.la-footer-bottom-a11y-wcag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px 3px 12px;
  flex-shrink: 0;
  background: rgba(255, 255, 255, 0.98);
  border: 1px solid rgba(0, 0, 0, 0.1);
  border-radius: 12px;
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.07), inset 0 1px 0 rgba(255, 255, 255, 0.95);
  transition: background 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
  text-decoration: none;
  color: inherit;
  cursor: pointer;

  &:hover {
    background: #ffffff;
    border-color: rgba(0, 0, 0, 0.12);
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.12), inset 0 1px 0 rgba(255, 255, 255, 1);

    .la-footer-bottom-a11y-wcag__label {
      color: $brand-teal;
    }
  }

  &:focus-visible {
    @include focus-ring($color: $brand-verdigris);
    border-radius: 12px;
  }

  .la-badge--in-a11y-wcag-pill {
    opacity: 1;
    text-transform: none;
    letter-spacing: 0.04em;
    font-size: 14px;
    font-weight: $aac-font-weight-semi;
    padding: 4px 8px;
    margin: 0;
    border-radius: 8px;
    background: rgba($brand-teal, 0.12);
    color: #0d5c5f;
    border: 1px solid rgba($brand-teal, 0.2);
    box-shadow: none;
  }

  .la-footer-bottom-a11y-wcag__label {
    font-size: $aac-font-size-sm;
    font-weight: $aac-font-weight-semi;
    color: rgba($la-navy, 0.88);
    padding: 0;
    margin: 0;
    font-family: inherit;
    text-align: left;
    white-space: nowrap;
    transition: color 0.2s ease;
  }
}

.la-mobile-drawer-a11y-wcag {
  margin: 6px 16px 10px;
  align-self: flex-start;

  .la-footer-bottom-a11y-wcag__label {
    text-align: left;
  }
}

/* la-footer responsive: industry collapsing (multi-col → 2-col → single-col) */
@media (max-width: $aac-breakpoint-lg) {
  .la-footer {
    padding-top: $aac-spacing-40;
    padding-bottom: $aac-spacing-32;
  }
  .la-footer-inner {
    margin-bottom: $aac-spacing-32;
  }
}

@media (max-width: $aac-breakpoint-md) {
  .la-footer {
    padding: $aac-spacing-32 $aac-spacing-20 $aac-spacing-28;
  }
  .la-footer-inner {
    gap: $aac-spacing-24 $aac-spacing-20;
    margin-bottom: $aac-spacing-28;
  }
  .la-footer-brand {
    max-width: 100%;
  }
  .la-footer-bottom {
    padding-top: $aac-spacing-20;
    gap: $aac-spacing-12;
  }
}

@media (max-width: $aac-breakpoint-sm) {
  .la-footer {
    padding: $aac-spacing-24 $aac-spacing-16 $aac-spacing-24;
  }
  .la-footer-inner {
    gap: $aac-spacing-20;
    margin-bottom: $aac-spacing-24;
  }
  .la-footer-col h4 {
    margin-top: $aac-spacing-8;
  }
  .la-footer-col:nth-child(2) h4 {
    margin-top: 0;
  }
  .la-footer-bottom {
    padding-top: $aac-spacing-16;
    gap: $aac-spacing-12;
  }
}

/* Collapsible footer (same breakpoint as navbar: 1024px) — brand + hamburger only when collapsed */
.la-footer__mobile {
  display: none;
}

.la-footer--collapsible .la-footer__main--desktop {
  grid-column: 2 / -1;
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: $aac-spacing-40 $aac-spacing-32;
}

.la-footer--collapsible .la-footer__main--desktop .la-footer-bottom {
  grid-column: 1 / -1;
}

@media (max-width: $aac-breakpoint-lg) {
  /* ≤1024px footer layout: brand/tagline on top centered, then the
     three link columns (Product / Resources / Company) below in
     their existing 3-column grouping, centered horizontally on the
     page. The columns themselves keep their own internal left
     alignment so each heading sits flush above its links. The
     bottom row (copyright + accessibility) spans full width below
     the columns. The hamburger drawer is suppressed since the
     content is now exposed directly. This structure is flexible at
     all widths below 1024px — `grid-template-columns: repeat(3, auto)`
     plus `justify-content: center` lets the cluster shrink to fit. */
  .la-footer--collapsible .la-footer-inner {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    margin-bottom: $aac-spacing-24;
  }
  .la-footer--collapsible .la-footer-brand {
    max-width: 600px;
    text-align: center;
    margin-bottom: $aac-spacing-16;
  }
  .la-footer--collapsible .la-footer-brand p {
    text-align: center;
  }
  .la-footer--collapsible .la-footer__main--desktop {
    display: grid !important;
    grid-template-columns: repeat(3, auto);
    gap: $aac-spacing-32 $aac-spacing-40;
    justify-content: center;
    width: 100%;
    max-width: 100%;
  }
  .la-footer--collapsible .la-footer__main--desktop .la-footer-col {
    grid-column: auto;
    /* Reset the 5rem left-padding the surrounding 2-col layout
       applies to .la-footer-col:nth-child(2)/(4) — that horizontal
       inset breaks the centered cluster here. */
    padding-left: 0 !important;
    /* Keep each column's heading + links flush-left within its own
       cell so the section reads cleanly even though the whole
       cluster is centered on the page. */
    text-align: left;
  }
  .la-footer--collapsible .la-footer__main--desktop .la-footer-col h4,
  .la-footer--collapsible .la-footer__main--desktop .la-footer-col nav {
    text-align: left;
  }
  /* Bottom row spans full footer width and lives under the cluster. */
  .la-footer--collapsible .la-footer__main--desktop .la-footer-bottom {
    grid-column: 1 / -1;
  }
  .la-footer--collapsible .la-footer__mobile,
  .la-footer--collapsible .la-footer__mobile .la-topbar-hamburger,
  .la-footer--collapsible .la-footer__hamburger {
    display: none !important;
  }
  /* The mobile drawer panel triggered by the hamburger duplicates
     the now-visible columns, so keep it hidden along with its
     trigger. */
  .la-footer--collapsible .la-mobile-drawer {
    display: none !important;
  }
  .la-footer--collapsible .la-footer-bottom {
    padding-top: $aac-spacing-16;
  }
}

/* ≤640px: the 3-column cluster no longer fits cleanly across the
   viewport — links wrap mid-column, the cluster gets pushed off
   center, and gaps eat what's left of the layout. Stack the three
   columns vertically (still centered) so each section reads cleanly
   at narrow widths. The brand-on-top-centered structure from the
   ≤1024px block is preserved. */
@media (max-width: $aac-breakpoint-sm) {
  .la-footer--collapsible .la-footer__main--desktop {
    grid-template-columns: 1fr !important;
    gap: $aac-spacing-24 !important;
    justify-content: stretch !important;
  }
  .la-footer--collapsible .la-footer__main--desktop .la-footer-col {
    text-align: center !important;
    align-items: center;
  }
  .la-footer--collapsible .la-footer__main--desktop .la-footer-col h4,
  .la-footer--collapsible .la-footer__main--desktop .la-footer-col nav {
    text-align: center !important;
  }
  .la-footer--collapsible .la-footer-bottom {
    flex-direction: column;
    align-items: center;
    gap: $aac-spacing-12;
    text-align: center;
  }
  /* Override the base .la-footer-bottom__copy `white-space: nowrap`
     so the copyright string can wrap onto multiple lines instead of
     getting clipped by the viewport edge at narrow widths. */
  .la-footer--collapsible .la-footer-bottom .la-footer-bottom__copy {
    white-space: normal;
    max-width: 100%;
  }
}

.la-footer-bottom-badges {
  display: flex;
  gap: $aac-spacing-10;

  .la-badge {
    font-size: 14px;
    font-weight: $aac-font-weight-semi;
    letter-spacing: 0.08em;
    padding: 5px $aac-spacing-12;
    opacity: 1;
    border-radius: 6px;
    transition: opacity 0.2s ease, transform 0.2s ease;

    &:hover {
      opacity: 0.9;
    }
  }

  .la-badge--wcag {
    background: rgba($brand-teal, 0.1);
    color: #0d5c5f;
    border: 1px solid rgba($brand-teal, 0.2);
  }

  .la-badge--oss {
    background: rgba($la-navy, 0.06);
    color: rgba($la-navy, 0.75);
    border: 1px solid rgba($la-navy, 0.12);
  }
}

// ── Right panel ───────────────────────────────────────────────────────────────
.la-panel {
  grid-area: panel;
  background: $color-surface;
  border-left: 1px solid $color-border;
  padding: $aac-spacing-20;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-16;
}

.la-panel-card {
  background: white;
  border-radius: $aac-radius-lg;
  border: 1px solid $color-border;
  padding: $aac-spacing-16;

  &.la-panel-card--testimonial {
    border-color: rgba($la-teal, 0.3);
    background: linear-gradient(135deg, rgba($la-teal, 0.04) 0%, white 60%);
  }

  &.la-panel-card--cta {
    background: $indigo;
    border-color: $indigo;
  }
}

.la-panel-card-eyebrow {
  font-size: $la-panel-font-size-xs;
  font-weight: $aac-font-weight-black;
  text-transform: uppercase;
  letter-spacing: $aac-letter-spacing-wide;
  color: $brand-teal;
  margin-bottom: $aac-spacing-10;

  .la-panel-card--cta & {
    color: $brand-honey-bronze;
  }
}

.la-testimonial-quote {
  font-size: $la-panel-font-size-sm;
  font-style: italic;
  color: $color-text-mid;
  line-height: $aac-line-height-loose;
  margin: 0 0 $aac-spacing-14;
  border: none;
  padding: 0;

  &::before { content: ''; }
  &::after  { content: ''; }
}

.la-testimonial-author {
  font-size: $la-panel-font-size-sm;
  font-weight: $aac-font-weight-black;
  color: $color-text;
  margin-bottom: $aac-spacing-2;
}

.la-testimonial-role {
  font-size: $la-panel-font-size-xs;
  color: $brand-teal;
  opacity: 1;
}

.la-wrapper .la-cta-title {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: $la-panel-font-size-base * 1.15;
  font-weight: $aac-font-weight-black;
  color: white;
  letter-spacing: -0.02em;
  line-height: 1.15;
  margin: 0 0 $aac-spacing-12;
  padding-left: $aac-spacing-8;
}

.la-wrapper .la-cta-body {
  font-size: $la-panel-font-size-xs * 1.1;
  font-weight: 400;
  color: rgba(white, 0.68);
  line-height: 1.8;
  letter-spacing: 0.005em;
  margin: 0 0 $aac-spacing-20;
}

.la-cta-actions {
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-8;
}

.la-checklist {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-8;

  li {
    display: flex;
    align-items: center;
    gap: $aac-spacing-8;
    font-size: $la-panel-font-size-sm;
    color: $color-text-mid;
  }

  .la-check {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background: rgba($brand-honey-bronze, 0.15);
    color: $brand-teal;
    font-size: 14px;
    font-weight: $aac-font-weight-black;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1), 0 1px 2px rgba(0, 0, 0, 0.06);
  }
}

.la-check {
  color: $cat-people-text;
  font-weight: $aac-font-weight-black;
  flex-shrink: 0;
}

// ── Features modal ──────────────────────────────────────────────────────────
.la-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: $aac-spacing-12 $aac-spacing-24;
  background: $indigo;
}

.la-modal-header-label {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: $aac-font-size-base;
  font-weight: $aac-font-weight-black;
  text-transform: uppercase;
  letter-spacing: $aac-letter-spacing-wide;
  color: $brand-honey-bronze;
}

.la-modal-close {
  display: flex;
  align-items: center;
  justify-content: center;
  /* WCAG 2.5.5 AAA touch target (44px min) + AAC standard headroom.
     Updated 2026-04-11 per WCAG audit; was 32×32. */
  width: 48px;
  height: 48px;
  min-width: 48px;
  min-height: 48px;
  border-radius: $aac-radius-circle;
  border: 1px solid rgba(white, 0.15);
  background: rgba(white, 0.08);
  color: rgba(white, 0.7);
  font-size: 14px;
  cursor: pointer;
  transition: all 0.15s ease;

  &:hover {
    background: rgba(white, 0.15);
    color: white;
  }
}

/* Features modal: exact styles from landing-alt #la-features (Why LingoLinq) */
.la-features-modal-body {
  background-color: #F7F9FA;
  padding: $aac-spacing-32 $aac-spacing-32 $aac-spacing-40;
  border-radius: 0;
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-32;
  position: relative;
  overflow: hidden;

  .la-section-header {
    text-align: center;
    max-width: 640px;
    margin: 0 auto;
  }

  .la-section-title {
    font-family: 'Maitree', serif;
    font-size: calc(38px * 0.85); /* 15% smaller than landing */
    font-weight: normal;
    color: $la-navy;
    margin: 0 0 24px;
    letter-spacing: -0.02em;
    line-height: 1.15;
    font-kerning: normal;

    em {
      font-style: normal;
      color: $brand-smart-blue;
    }
  }
}

.la-features-modal-wrap {
  border-radius: $aac-radius-xl;
  overflow: hidden;
  box-shadow: $la-shadow-lg;
  margin: -15px 0; /* vertical only so header extends to left/right edges of modal */
}

.modal-content:has(.la-features-modal-wrap) {
  background: none;
  border: none;
  box-shadow: none;
  overflow: visible !important;
  max-height: none !important;
  padding: 0;
}

.modal-dialog:has(.la-features-modal-wrap) {
  width: 90%;
  max-width: 90%;
  padding-left: 0;
  padding-right: 0;
}

// Features modal: header matches support modal (width kept via .modal-dialog:has(.la-features-modal-wrap) above)
.la-features-modal-wrap .la-modal-header {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  padding: 20px 24px;
  border-bottom: 1px solid var(--md-line);
  background: rgba(255, 255, 255, 0.6);
}
.la-features-modal-wrap .la-modal-header-label {
  margin: 0;
  font-weight: 900;
  font-size: 20px;
  letter-spacing: -0.2px;
  color: var(--md-ink);
  flex: 1 1 auto;
  min-width: 0;
}
.la-features-modal-wrap .la-modal-close {
  display: flex;
  align-items: center;
  justify-content: center;
  /* WCAG AA + AAC touch target — was 36×36 */
  width: 48px;
  height: 48px;
  min-width: 48px;
  min-height: 48px;
  padding: 0;
  margin: 0;
  border: 1px solid rgba($brand-blue-black, 0.12);
  border-radius: 50%;
  background-color: $surface-300 !important;
  background: $surface-300 !important;
  color: var(--md-muted);
  cursor: pointer;
  font-size: 18px;
  line-height: 1;
  transition: color 0.2s ease, background 0.2s ease, border-color 0.2s ease, transform 0.2s ease-out, box-shadow 0.2s ease;

  &:hover {
    color: var(--md-ink);
    background-color: $surface-400 !important;
    background: $surface-400 !important;
    border-color: rgba($brand-blue-black, 0.2);
    transform: translateY(-2px) scale(1.04);
    box-shadow: 0 4px 12px rgba($brand-blue-black, 0.14), 0 2px 4px rgba($brand-blue-black, 0.08);
  }
  &:active {
    transform: translateY(0) scale(0.98);
    box-shadow: 0 1px 3px rgba($brand-blue-black, 0.08);
  }
}

// ── Cloud Extras modal (same styling as support modal: uses la-support-modal-wrap) ──
/* Content inside la-support-modal-body: feature list and notes */
.la-cloud-extras-modal-wrap .la-cloud-extras-features-heading {
  font-size: 17px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--md-ink);
  margin: 0 0 20px;
}

.la-cloud-extras-modal-wrap .la-cloud-extras-feature-list {
  list-style: none;
  margin: 0 0 24px;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.la-cloud-extras-modal-wrap .la-cloud-extras-feature-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  min-width: 0;
}

.la-cloud-extras-modal-wrap .la-cloud-extras-check {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  margin-top: 2px;
  border-radius: 50%;
  background: rgba(44, 183, 176, 0.14);
  color: var(--md-teal, $brand-verdigris);
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
}

.la-cloud-extras-modal-wrap .la-cloud-extras-feature-content {
  flex: 1 1 auto;
  min-width: 0;
}

.la-cloud-extras-modal-wrap .la-cloud-extras-feature-title {
  display: block;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--md-ink);
  margin-bottom: 4px;
}

.la-cloud-extras-modal-wrap .la-cloud-extras-feature-desc {
  margin: 0;
  font-size: 14px;
  line-height: 1.5;
  color: var(--md-muted);
}

.la-cloud-extras-modal-wrap .la-cloud-extras-evolving {
  margin: 0 0 12px;
  font-size: 15px;
  line-height: 1.55;
  color: var(--md-ink);
}

.la-cloud-extras-modal-wrap .la-cloud-extras-lifetime-note {
  margin: 0;
  padding: 12px 16px;
  font-size: 15px;
  line-height: 1.5;
  color: var(--md-ink);
  background: rgba($brand-blue-black, 0.06);
  border-radius: var(--md-r-md, 12px);
  border-left: 3px solid var(--md-teal, $brand-verdigris);
}

// ── Support modal (same styling as Getting Started modal on modern dashboard) ──
/* Dialog and content: match Getting Started modal */
.modal .modal-dialog:has(.la-support-modal-wrap),
.modal .modal-dialog:has(.la-speak-mode-intro-modal-wrap),
.modal .modal-dialog:has(.la-new-board-modal-wrap),
.modal .modal-dialog:has(.la-generate-board-modal-wrap),
.modal .modal-dialog:has(.la-add-app-modal-wrap) {
  width: 100%;
  max-width: 520px;
  border-radius: var(--md-r-lg);
  overflow: hidden;
}
.modal .modal-dialog:has(.la-new-board-modal-wrap),
.modal .modal-dialog:has(.la-generate-board-modal-wrap) {
  /* 50% wider on full screens, fluid down to mobile (clamp at 96vw),
     and edge-to-edge on phones for max usable space.
     Fills full viewport height; body scrolls internally. */
  max-width: min(900px, 96vw);
  width: min(900px, 96vw);
  height: 100vh;
  height: 100dvh;
  max-height: 100vh;
  max-height: 100dvh;
  margin: 0 auto;
  display: flex;
  align-items: stretch;
}
.modal .modal-content:has(.la-new-board-modal-wrap),
.modal .modal-content:has(.la-generate-board-modal-wrap) {
  display: flex;
  flex-direction: column;
  height: 100%;
  max-height: 100%;
}
.la-new-board-modal-wrap {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-height: 0;
}
.la-new-board-modal-wrap .la-support-modal-body {
  flex: 1 1 auto;
  overflow-y: auto;
  min-height: 0;
}
.la-new-board-modal-wrap .la-modal-header,
.la-new-board-modal-wrap .la-new-board-modal-footer {
  flex-shrink: 0;
}
@media (max-width: 600px) {
  .modal .modal-dialog:has(.la-new-board-modal-wrap),
  .modal .modal-dialog:has(.la-generate-board-modal-wrap) {
    max-width: 100vw;
    width: 100vw;
    margin: 0;
    border-radius: 0;
  }
}

.modal .modal-dialog:has(.md-dashboard-supervisors-modal-wrap) {
  max-width: min(720px, 96vw);
}
.modal-content:has(.md-dashboard-supervisors-modal-wrap) {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.98));
  border-radius: var(--md-r-lg);
  border: 1px solid var(--md-line);
  box-shadow: var(--md-shadow);
  padding: 0;
  overflow: hidden;
  max-height: none !important;
}
.md-dashboard-supervisors-modal__scroll {
  max-height: min(72vh, 720px);
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
}
.md-supervisors-page--modal {
  padding: 16px 20px 24px;
  margin: 0;
}
.md-dashboard-supervisors-modal__section {
  margin-bottom: 1.5rem;
}
.md-dashboard-supervisors-modal__section:last-child {
  margin-bottom: 0;
}
.md-dashboard-supervisors-modal__heading {
  margin: 0 0 0.35rem;
  font-size: 1.5625rem; /* was 1.25rem; +25% */
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--md-ink);
}
.md-dashboard-supervisors-modal__lead {
  margin: 0 0 1rem;
  font-size: 14px; /* was 1.05rem; +25% */
  color: var(--md-muted);
  line-height: 1.45;
}
.md-dashboard-supervisors-modal__badge {
  display: inline-flex;
  margin-bottom: 1rem;
}
.md-dashboard-supervisors-modal__settings {
  margin-top: 0.5rem;
}
.md-dashboard-supervisors-modal__settings .ll-bento-supervision-inline {
  display: flex;
  flex-direction: column;
  align-items: stretch;
}
.md-dashboard-supervisors-modal__settings .ll-bento-supervision-inline > button.md-btn--primary {
  align-self: center;
  margin-top: 0.75rem;
}
.md-dashboard-supervisors-modal__section--rooms .md-dashboard-supervisors-modal__heading {
  margin-bottom: 0.75rem;
}
.md-dashboard-supervisors-modal-wrap .md-person__main--btn {
  width: 100%;
  text-align: left;
  border: none;
  background: transparent;
  cursor: pointer;
  font: inherit;
  color: inherit;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 0;
  border-radius: 12px;
}
.md-dashboard-supervisors-modal-wrap .md-person__main--btn:hover {
  background: rgba(44, 183, 176, 0.06);
}
.md-dashboard-supervisors-modal-wrap .md-person__main--btn:focus-visible {
  @include focus-ring;
}
.md-dashboard-supervisors-modal-wrap .md-person__link-btn {
  background: none;
  border: none;
  padding: 0;
  margin: 0;
  font: inherit;
  color: rgba($brand-teal, 0.95);
  text-decoration: underline;
  cursor: pointer;
  text-align: left;
}
.md-dashboard-supervisors-modal-wrap .md-person__link-btn:hover {
  color: #0d5c5e;
}
.md-dashboard-supervisors-modal-wrap .md-rooms-list__btn {
  color: rgba($brand-teal, 0.95);
}
.modal-content:has(.la-support-modal-wrap),
.modal-content:has(.la-speak-mode-intro-modal-wrap),
.modal-content:has(.la-new-board-modal-wrap),
.modal-content:has(.la-generate-board-modal-wrap),
.modal-content:has(.la-add-app-modal-wrap) {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.98));
  border-radius: var(--md-r-lg);
  border: 1px solid var(--md-line);
  box-shadow: var(--md-shadow);
  padding: 0;
  overflow: hidden;
  max-height: none !important;
}
/* Add App modal */
.la-add-app-modal-wrap {
  color: var(--md-ink);
  min-width: 0;
  position: relative;
}
.la-add-app-modal-wrap .la-modal-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 20px 24px;
  border-bottom: 1px solid var(--md-line);
  background: rgba(255, 255, 255, 0.6);
}
.la-add-app-modal-wrap .la-modal-header-label {
  margin: 0;
  font-weight: 900;
  font-size: 20px;
  letter-spacing: -0.2px;
  color: var(--md-ink);
  flex: 1 1 auto;
  min-width: 0;
}
.la-add-app-modal-wrap .la-modal-close {
  background: none;
  border: none;
  font-size: 28px;
  line-height: 1;
  color: var(--md-muted);
  cursor: pointer;
  padding: 0 4px;
  flex-shrink: 0;
}
.la-add-app-modal-wrap .la-modal-close:hover {
  color: var(--md-ink);
}
.la-modal-header-icon--app {
  width: 46px;
  height: 46px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: rgba($brand-dusty-denim, 0.10);
  border: 1px solid var(--md-line);
  flex-shrink: 0;
}
.la-add-app-modal-body {
  padding: 24px;
}
.la-add-app-modal-desc {
  font-size: 15px;
  line-height: 1.6;
  color: var(--md-ink);
  margin: 0 0 8px;
}
.la-add-app-modal-stores {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
  padding: 28px 0;
}
.la-add-app-modal-store-link {
  display: inline-block;
  transition: transform 0.15s ease, opacity 0.15s ease;
}
.la-add-app-modal-store-link:hover {
  transform: translateY(-2px);
  opacity: 0.85;
}
.la-add-app-modal-store-img {
  height: 46px;
  display: block;
}
.la-add-app-modal-hint {
  font-size: 14px;
  line-height: 1.5;
  color: var(--md-muted);
  margin: 0;
  text-align: center;
}

/* ── My Devices modal (modern) ── */
.la-devices-modal-wrap {
  color: var(--md-ink);
  min-width: 0;
  position: relative;
}
.la-devices-modal-wrap .la-modal-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 20px 24px;
  border-bottom: 1px solid var(--md-line);
  background: rgba(255, 255, 255, 0.6);
}
.la-devices-modal-wrap .la-modal-header-label {
  margin: 0;
  font-weight: 900;
  font-size: 20px;
  letter-spacing: -0.2px;
  color: var(--md-ink);
  flex: 1 1 auto;
  min-width: 0;
}
.la-devices-modal-wrap .la-modal-close {
  background: none;
  border: none;
  font-size: 28px;
  line-height: 1;
  color: var(--md-muted);
  cursor: pointer;
  padding: 0 4px;
  flex-shrink: 0;
  transition: color 0.15s ease;
}
.la-devices-modal-wrap .la-modal-close:hover {
  color: var(--md-ink);
}
.la-modal-header-icon--devices {
  width: 52px;
  height: 52px;
  border-radius: 16px;
  display: grid;
  place-items: center;
  background: rgba($brand-verdigris, 0.10);
  border: 1px solid var(--md-line);
  flex-shrink: 0;
}
.la-devices-modal-body {
  padding: 16px 24px 8px;
}
.la-devices-list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.la-devices-item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 14px 16px;
  border-radius: 12px;
  border: 1px solid transparent;
  transition: background 0.15s ease, border-color 0.15s ease;
}
.la-devices-item + .la-devices-item {
  margin-top: 4px;
}
.la-devices-item:hover {
  background: rgba($brand-verdigris, 0.04);
  border-color: var(--md-line);
}
.la-devices-item--current {
  background: rgba($brand-verdigris, 0.06);
  border-color: rgba($brand-verdigris, 0.18);
}
.la-devices-item--current:hover {
  background: rgba($brand-verdigris, 0.09);
}
.la-devices-item__icon-wrap {
  width: 52px;
  height: 52px;
  flex-shrink: 0;
  border-radius: 16px;
  display: grid;
  place-items: center;
  background: rgba(44, 183, 176, 0.12);
  border: 1px solid var(--md-line);
  margin-top: 2px;
}
.la-devices-item__icon-wrap--mobile {
  background: rgba($brand-dusty-denim, 0.10);
}
.la-devices-item__icon-wrap--web {
  background: rgba($brand-verdigris, 0.10);
}
.la-devices-item--current .la-devices-item__icon-wrap {
  border-color: rgba($brand-verdigris, 0.25);
}
.la-devices-item__info {
  flex: 1 1 auto;
  min-width: 0;
}
.la-devices-item__name {
  font-size: 16px;
  font-weight: 600;
  color: var(--md-ink);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: color 0.15s ease;
}
.la-devices-item__name:hover {
  color: var(--md-teal);
}
.la-devices-item__edit-icon {
  opacity: 0;
  transition: opacity 0.15s ease;
