/* ---------- Grid ---------- */
.md-grid {
  display: grid !important;

  gap: 28px !important;

  grid-template-columns: 55fr 45fr !important;

  grid-template-areas:
    "boards speak"
    "boards extras"
    ". sup" !important;
  grid-template-rows: auto auto 0 !important;

  /* Stretch items to fill their grid cells so a shorter card on
     one side doesn't leave empty space below itself before the
     row gap — the row gap then becomes the ONLY visible vertical
     spacing between adjacent cards, identical across all rows. */
  align-items: stretch !important;

  max-width: 100% !important;

  overflow: hidden !important;

}
.md-grid--with-getting-started {
  grid-template-areas:
    "getting_started getting_started"
    "divider divider"
    "boards speak"
    "boards extras"
    ". sup" !important;
  grid-template-rows: auto auto auto auto 0 !important;

}
/* Grid variant when org management card is shown — full-width row
   BELOW boards/speak/extras (admin and supervisor users see Boards,
   Speak Mode, and Extras at the top of their dashboard, with My
   Organizations grounded as a secondary action below). */
.md-grid--with-org-mgmt {
  grid-template-areas:
    "boards speak"
    "boards extras"
    "org_mgmt org_mgmt"
    ". sup" !important;
  grid-template-rows: auto auto auto 0 !important;
}
/* Caseload top-left + Speak top-right (tops flush). Boards spans
   rows 2-3 on the left. Right column stacks Extras then My
   Organizations — both same width as Speak. Org's bottom flushes
   with Boards' bottom. */
.md-grid--with-caseload.md-grid--with-org-mgmt {
  grid-template-areas:
    "caseload speak"
    "boards extras"
    "boards org_mgmt"
    ". sup" !important;
  grid-template-rows: auto auto auto 0 !important;
}
/* Caseload only (no org management) */
.md-grid--with-caseload:not(.md-grid--with-org-mgmt) {
  grid-template-areas:
    "caseload caseload"
    "boards speak"
    "boards extras"
    ". sup" !important;
  grid-template-rows: auto auto auto 0 !important;
}
/* Both getting-started and org management — org_mgmt grounded below
   the primary boards/speak/extras stack instead of pinned above. */
.md-grid--with-getting-started.md-grid--with-org-mgmt {
  grid-template-areas:
    "getting_started getting_started"
    "divider divider"
    "boards speak"
    "boards extras"
    "org_mgmt org_mgmt"
    ". sup" !important;
  grid-template-rows: auto auto auto auto auto 0 !important;
}
/* Getting-started + caseload + org management — caseload top-left,
   speak top-right (tops flush). Boards spans rows on the left;
   right column stacks extras then org_mgmt (same width as speak). */
.md-grid--with-getting-started.md-grid--with-caseload.md-grid--with-org-mgmt {
  grid-template-areas:
    "getting_started getting_started"
    "divider divider"
    "caseload speak"
    "boards extras"
    "boards org_mgmt"
    ". sup" !important;
  grid-template-rows: auto auto auto auto auto 0 !important;
}
/* Getting-started + caseload (no org management) */
.md-grid--with-getting-started.md-grid--with-caseload:not(.md-grid--with-org-mgmt) {
  grid-template-areas:
    "getting_started getting_started"
    "divider divider"
    "caseload caseload"
    "boards speak"
    "boards extras"
    ". sup" !important;
  grid-template-rows: auto auto auto auto auto 0 !important;
}
/* Caseload card — multi-radial composition over a soft white→cream
   linear base. Sizes scaled from the original 1400px design width
   down to the caseload card's actual width (583px), so the blobs
   read at the same relative proportion they did in the source.
   Specificity bumped to .md-grid .md-card.md-card--caseload so this
   wins over the base .md-grid .md-card { background: ... !important }
   rule (line ~40604), which would otherwise override our radial
   stack via the shorthand. */
.md-grid .md-card.md-card--caseload {
  grid-area: caseload !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  justify-content: space-between !important;
  flex-wrap: wrap !important;
  gap: 16px !important;
  padding: 20px 24px !important;
  border-radius: var(--md-r-lg) !important;
  background:
    radial-gradient(583px 292px at 10% 5%, rgba(49, 111, 112, 0.09), rgba(0, 0, 0, 0) 50%),
    radial-gradient(500px 250px at 90% 15%, rgba(70, 80, 95, 0.03), rgba(0, 0, 0, 0) 50%),
    radial-gradient(458px 292px at 50% 95%, rgba(55, 65, 81, 0.03), rgba(0, 0, 0, 0) 50%),
    radial-gradient(375px 208px at 80% 55%, rgba(42, 157, 143, 0.07), rgba(0, 0, 0, 0) 45%),
    radial-gradient(333px 167px at 25% 65%, rgba(76, 134, 216, 0.025), rgba(0, 0, 0, 0) 50%),
    linear-gradient(rgb(255, 255, 255) 0%, rgb(252, 254, 253) 50%, rgb(244, 250, 249) 100%) !important;
  border: 1px solid var(--md-line) !important;
  border-bottom: 2px solid rgba($la-navy, 0.08) !important;
}
.md-card--caseload .md-card__head {
  flex: 1 1 auto !important;
  border-bottom: none !important;
  padding-bottom: 0 !important;
}
/* Org management card: full-width like getting-started */
.md-card--org-management {
  grid-area: org_mgmt !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  justify-content: space-between !important;
  flex-wrap: wrap !important;
  gap: 16px !important;
  padding: 20px 24px !important;
  border-radius: var(--md-r-lg) !important;
  background: linear-gradient(135deg, rgba($brand-dusty-denim, 0.08) 0%, rgba($brand-verdigris, 0.06) 100%) !important;
  border: 1px solid rgba($brand-dusty-denim, 0.12) !important;
}
.md-card--org-management .md-card__head {
  flex: 1 1 auto !important;
  border-bottom: none !important;
  padding-bottom: 0 !important;
}
.md-card--org-management .md-card__org-list {
  display: flex !important;
  flex-wrap: wrap !important;
  gap: 8px !important;
  align-items: center !important;
}
/* The card is a wrapping flex row; when it wraps (narrow width) the
   action button drops to its own line and left-aligns. `margin-left:
   auto` pushes it to the right edge of its div in BOTH the inline and
   wrapped states. Scoped to the org-management card's direct-child
   button so other .md-btn usages are unaffected. */
.md-card--org-management > .md-btn {
  margin-left: auto !important;
}

/* --- Org dropdown (multi-org selector on dashboard) --- */
.md-org-dropdown {
