}
.md-grid__divider::before {
  content: "" !important;

  display: block !important;

  width: 100% !important;

  height: 1px !important;

  background: linear-gradient(90deg, transparent 0%, rgba($la-navy, 0.12) 12%, rgba($la-navy, 0.18) 50%, rgba($la-navy, 0.12) 88%, transparent 100%) !important;

}

/* ---------- User page (My Account) hero and summary ---------- */
.md-hero--user {
  position: relative;
  padding: 36px 24px 32px !important;
  width: 100%;
  margin-left: auto;
  margin-right: auto;
  display: flex;
  align-items: center;
  gap: 28px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.97), rgba(248, 250, 252, 0.95));
  border: 1px solid var(--md-line);
  border-bottom: 2px solid rgba($la-navy, 0.08);
  border-radius: var(--md-r-lg, 22px);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.05);
}
.md-hero--user__avatar-wrap {
  position: relative;
  flex-shrink: 0;
  /* Flex-row places the STATUS card immediately to the right of the
     avatar (was stacked underneath when this was flex-direction: column).
     The online_marker inside is `position: absolute` so it stays pinned
     to the avatar regardless of axis. align-items: center keeps the
     pill vertically centered against the 96px avatar. */
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 16px;
}
.md-hero--user__avatar {
  width: 96px;
  height: 96px;
  border-radius: 24px;
  object-fit: cover;
  padding: 8px;
  border: 2px solid rgba($brand-verdigris, 0.15);
  background: rgba(255, 255, 255, 0.8);
  box-shadow: 0 4px 12px rgba($brand-blue-black, 0.08);
}
.md-hero--user__body {
  flex: 1 1 auto;
  min-width: 0;
}
.md-hero--user__name-row {
  display: flex;
  align-items: center;
  gap: 0;
  margin: 0 0 10px;
}
.md-hero--user__name {
  margin: 0;
  height: auto;
  font-size: 26px;
  font-weight: 900;
  letter-spacing: -0.3px;
  color: var(--md-ink);
  line-height: 1.3;
}
.md-hero--user__details {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px 0;
  margin: 0 0 2px;
}
.md-hero--user__location-row {
  margin: 0 0 4px;
}
.md-hero--user__detail-sep {
  display: inline-block;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--md-muted);
  opacity: 0.65;
  margin: 0 12px;
  vertical-align: middle;
}
.md-hero--user__username {
  font-size: 18px;
  color: var(--md-muted);
  font-weight: 600;
}
.md-hero--user__meta {
  font-size: 17px;
  color: var(--md-muted);
  line-height: 1.6;
}
.md-hero--user__url {
  margin: 8px 0 0;
  font-size: 15px;
  line-height: 1.5;
}
.md-hero--user__url a {
  color: var(--md-teal);
  font-weight: 600;
  text-decoration: none;
  transition: color 0.15s ease;
}
.md-hero--user__url a:hover {
  color: #1a7a70;
}
.md-hero--user .online_marker {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 12px;
  height: 12px;
  border-radius: 999px;
  background: #22c55e;
  border: 2px solid rgba(255, 255, 255, 0.9);
}
.md-user-summary {
  color: var(--md-ink);
  min-width: 0;
  width: 100%;
  box-sizing: border-box;
}
.md-user-summary__page-divider {
  border: none;
  border-top: 1.5px solid rgba($brand-blue-black, 0.12);
