/* ── Goal-list item — modern row inside the goals card ── */
/* Action group (right side of each goal row): icon-tile buttons with
   labels below the icon. Replaces the prior bootstrap btn-lg float-
   right group so the actions read as a deliberate toolbar instead of
   stacked text buttons. */
.md-goal-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  justify-content: center;
  gap: 8px;
  margin-top: 18px;
  clear: both;
}
/* Pass-through wrapper — keeps the existing template grouping for the
   active-goal pair (New Note + Quick Assessment) but flows children
   directly into the parent flex layout so all tiles share one even
   gap rule. */
.md-goal-actions__group {
  display: contents;
}
.md-goal-action {
  flex: 1 1 0;
  min-width: 5rem;
  min-height: 5rem;
  padding: 8px;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid rgba($la-navy, 0.10);
  border-radius: 10px;
  background: linear-gradient(180deg, rgba($la-navy, 0.02) 0%, rgba($la-navy, 0.07) 100%);
  color: $brand-charcoal-dark;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.12s ease, border-color 0.12s ease, box-shadow 0.12s ease;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    0 1px 2px rgba($la-navy, 0.04);
}
.md-goal-action:hover {
  background: linear-gradient(180deg, rgba($la-navy, 0.04) 0%, rgba($la-navy, 0.12) 100%);
  border-color: rgba($la-navy, 0.20);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.95),
    0 2px 6px rgba($la-navy, 0.08);
}
.md-goal-action__icon {
  font-size: 18px;
  color: $la-navy;
  line-height: 1;
}
.md-goal-action__label {
  display: block;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.2;
  color: $la-navy;
  text-align: center;
  white-space: normal;
}

/* Role-color modifiers — match the caseload action tile palette:
     Note     → blue   (communication / writing)
     Assess   → teal   (measurement / diagnostic)
     Prio     → violet (priority / setting)
     Retire   → coral  (completion)
     Restore  → teal   (revival)
     Delete   → coral  (destruction) */
.md-goal-action--note {
  background: linear-gradient(180deg, rgba($brand-dusty-denim, 0.04) 0%, rgba($brand-dusty-denim, 0.18) 100%);
  border-color: rgba($brand-dusty-denim, 0.20);
}
.md-goal-action--note:hover {
  background: linear-gradient(180deg, rgba($brand-dusty-denim, 0.06) 0%, rgba($brand-dusty-denim, 0.30) 100%);
  border-color: rgba($brand-dusty-denim, 0.45);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 1),
    0 2px 4px rgba($brand-dusty-denim, 0.10),
    0 6px 12px -3px rgba($brand-dusty-denim, 0.18);
}
.md-goal-action--assess {
  background: linear-gradient(180deg, rgba($brand-verdigris, 0.05) 0%, rgba($brand-verdigris, 0.20) 100%);
  border-color: rgba($brand-verdigris, 0.22);
}
.md-goal-action--assess:hover {
  background: linear-gradient(180deg, rgba($brand-verdigris, 0.08) 0%, rgba($brand-verdigris, 0.32) 100%);
  border-color: rgba($brand-verdigris, 0.48);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 1),
    0 2px 4px rgba($brand-verdigris, 0.12),
    0 6px 12px -3px rgba($brand-verdigris, 0.20);
}
.md-goal-action--prio {
  background: linear-gradient(180deg, rgba(139, 92, 246, 0.04) 0%, rgba(139, 92, 246, 0.18) 100%);
  border-color: rgba(139, 92, 246, 0.20);
}
.md-goal-action--prio:hover {
  background: linear-gradient(180deg, rgba(139, 92, 246, 0.06) 0%, rgba(139, 92, 246, 0.30) 100%);
  border-color: rgba(139, 92, 246, 0.45);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 1),
    0 2px 4px rgba(139, 92, 246, 0.10),
    0 6px 12px -3px rgba(139, 92, 246, 0.18);
}
.md-goal-action--retire,
.md-goal-action--delete {
  background: linear-gradient(180deg, rgba(232, 122, 111, 0.05) 0%, rgba(232, 122, 111, 0.20) 100%);
  border-color: rgba(232, 122, 111, 0.22);
}
.md-goal-action--retire:hover,
.md-goal-action--delete:hover {
  background: linear-gradient(180deg, rgba(232, 122, 111, 0.08) 0%, rgba(232, 122, 111, 0.32) 100%);
  border-color: rgba(232, 122, 111, 0.48);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 1),
    0 2px 4px rgba(232, 122, 111, 0.12),
    0 6px 12px -3px rgba(232, 122, 111, 0.20);
}
.md-goal-action--restore {
  background: linear-gradient(180deg, rgba($brand-verdigris, 0.05) 0%, rgba($brand-verdigris, 0.20) 100%);
  border-color: rgba($brand-verdigris, 0.22);
}
.md-goal-action--restore:hover {
  background: linear-gradient(180deg, rgba($brand-verdigris, 0.08) 0%, rgba($brand-verdigris, 0.32) 100%);
  border-color: rgba($brand-verdigris, 0.48);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 1),
    0 2px 4px rgba($brand-verdigris, 0.12),
    0 6px 12px -3px rgba($brand-verdigris, 0.20);
}

/* Contain the floated flag/avatar so the goal-item card grows to
   fit its content (and the action toolbar that now sits centered
   below it) instead of letting floats spill out below the bottom
   border. */
.md-goals__card .well.goal {
  display: flow-root;
}

/* Coaching Strategies panel — clean caseload-card-style surface
   with AAC industry-standard partner strategies. Neutral navy
   vocabulary (no teal tint), modern icon badges replacing numbered
   chips, and subtle layered shadow for depth. The supervisor's
   original goal.description is preserved as a "Therapist note"
   callout at the bottom when present. */
.md-goal-coaching {
  margin-top: 18px;
  padding: 22px 24px;
  background: linear-gradient(180deg, #ffffff 0%, rgba($la-navy, 0.02) 100%);
  border: 1px solid rgba($la-navy, 0.08);
  border-radius: 16px;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 1),
    0 1px 3px rgba($la-navy, 0.04),
    0 6px 18px -6px rgba($la-navy, 0.10);
}
/* details/summary collapsible behavior — closed by default, expands
   on click. The summary IS the head, so it's clickable. Default
   marker hidden in favor of the rounded chevron badge on the right. */
.md-goal-coaching:not([open]) .md-goal-coaching__head {
  margin-bottom: 0;
  padding-bottom: 0;
  border-bottom: none;
}
.md-goal-coaching__head {
  display: flex;
  align-items: center;
  gap: 14px;
  cursor: pointer;
  list-style: none;
  margin-bottom: 18px;
  padding-bottom: 14px;
  border-bottom: 1px solid rgba($la-navy, 0.07);
  user-select: none;
  transition: margin 0.15s ease, padding 0.15s ease, border-color 0.15s ease;
}
.md-goal-coaching__head::-webkit-details-marker {
  display: none;
}
.md-goal-coaching__head::marker {
  content: '';
}
.md-goal-coaching__head-text {
  flex: 1;
  min-width: 0;
}
.md-goal-coaching__chevron {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: rgba($la-navy, 0.04);
  border: 1px solid rgba($la-navy, 0.10);
  color: $la-navy;
  transition: transform 0.18s ease, background 0.12s ease;
}
.md-goal-coaching__head:hover .md-goal-coaching__chevron {
  background: rgba($la-navy, 0.08);
}
.md-goal-coaching[open] .md-goal-coaching__chevron {
  transform: rotate(180deg);
}
.md-goal-coaching__eyebrow {
  display: block;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.10em;
  color: rgba($la-navy, 0.55);
  margin-bottom: 6px;
}
.md-goal-coaching__lead {
  margin: 0;
  font-size: 14px;
  font-weight: 500;
  color: rgba($la-navy, 0.78);
  line-height: 1.5;
}
.md-goal-coaching__list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.md-goal-coaching__item {
  display: flex;
  align-items: flex-start;
  gap: 14px;
}
.md-goal-coaching__icon {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: linear-gradient(180deg, rgba($la-navy, 0.02) 0%, rgba($la-navy, 0.07) 100%);
  border: 1px solid rgba($la-navy, 0.08);
  color: $la-navy;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    0 1px 2px rgba($la-navy, 0.04);
}
.md-goal-coaching__body {
  flex: 1;
  min-width: 0;
  padding-top: 2px;
}
.md-goal-coaching__body strong {
  display: block;
  font-size: 15px;
  font-weight: 700;
  color: $la-navy;
  margin-bottom: 4px;
  line-height: 1.3;
}
.md-goal-coaching__body p {
  margin: 0;
  font-size: 14px;
  line-height: 1.55;
  color: rgba($la-navy, 0.72);
}
.md-goal-coaching__note {
  position: relative;
  margin-top: 18px;
  padding: 14px 16px 14px 19px;
  background: rgba($la-navy, 0.03);
  border-radius: 8px;
  overflow: hidden;
}
.md-goal-coaching__note::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background: linear-gradient(180deg, $brand-verdigris 0%, $brand-stormy-teal 100%);
}
.md-goal-coaching__note-label {
  display: inline-block;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.10em;
  color: rgba($la-navy, 0.60);
  margin-bottom: 4px;
}
.md-goal-coaching__note p {
  margin: 0;
  font-size: 14px;
  line-height: 1.55;
  color: rgba($la-navy, 0.80);
}
/* Override the legacy `.goal .description` rule (white-space:nowrap +
   ellipsis + max-width: calc(100% - 200px)) so the full goal
   description wraps across the available width in the modern card.
   The 200px reserve was for the old float-right button cluster; now
   that the actions sit centered below the content, the description
   can take the full row. */
.md-goals__card .well.goal .description {
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
  max-width: 100%;
}

/* Modern dimensional flag icon — sits in the 50px badge slot where
   no badge image is available. */
.md-goal-flag-icon {
  display: block;
  margin-top: 4px;
}

/* Info pill for the goal's "started/ended X ago" timestamp — gray
   glassy gradient surface with a hairline navy outline and a soft
   contact shadow so it reads as a raised metadata badge sitting
   beside the flag, directly under the goal summary. */
.md-goal-time-pill {
