/* Modern checkboxes */
.md-preferences__form input[type="checkbox"] {
  -webkit-appearance: none !important;
  -moz-appearance: none !important;
  appearance: none !important;
  display: inline-block !important;
  position: relative !important;
  top: 0 !important;
  left: 0 !important;
  width: 18px !important;
  height: 18px !important;
  min-width: 18px;
  flex-shrink: 0;
  margin-top: 3px;
  border: 1.5px solid rgba($brand-blue-black, 0.25) !important;
  border-radius: 4px !important;
  background: #fff !important;
  cursor: pointer;
  vertical-align: middle;
  margin: 0 8px 0 0 !important;
  transition: border-color 0.15s ease, background 0.15s ease;
}
.md-preferences__form input[type="checkbox"]:checked {
  background: #fff !important;
  border-color: rgba($brand-blue-black, 0.4) !important;
}
.md-preferences__form input[type="checkbox"]:checked::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 5px;
  width: 5px;
  height: 10px;
  border: solid $brand-charcoal-blue !important;
  border-width: 0 2px 2px 0 !important;
  transform: rotate(45deg);
}
.md-preferences__form input[type="checkbox"]:hover {
  border-color: rgba($brand-blue-black, 0.4) !important;
}
.md-preferences__form .big_checkbox {
  padding-left: 0 !important;
  padding-top: 0 !important;
  margin-top: 0.3rem;
}
.md-preferences__form .big_checkbox label {
  padding-left: 0 !important;
}
.md-preferences__form .checkbox {
