/* Flex + Bootstrap columns: column width from Bootstrap at each breakpoint; min-width keeps card from being cut off */
.md-user-summary__board-grid > div {
  padding: 0;
  flex: 0 0 auto;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  /* Card width (2.4rem*2 + 160px image + buffer); wrap before content is cut off */
