/* --- Speak Card --- */
.md-card--speak { grid-area: speak; padding-bottom: 20px; overflow: visible; position: relative; }
/* Match the My Caseload card's one-row layout: head on the left, the
   primary action button (Continue Speaking) on the right, on the same
   row — and drop the visible divider line between head and body. The
   button is now a direct child of .md-card--speak (see template), so
   space-between pushes it to the right edge. Specificity is bumped to
   `.md-grid .md-card.md-card--speak` so it wins over the generic
   `.md-grid .md-card { background/etc !important }` rule, matching the
   approach used for .md-card--caseload above. The base body styles for
   .md-card--speak (grid-area / overflow / position / padding-bottom)
   stay in the rule right above; only the layout + divider are added/
   overridden here. */
.md-grid .md-card.md-card--speak {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  justify-content: space-between !important;
  flex-wrap: wrap !important;
  gap: 16px !important;
  padding: 20px 24px !important;
}
.md-card--speak .md-card__head {
  flex: 1 1 auto !important;
  border-bottom: none !important;
  padding-bottom: 0 !important;
}
/* When the speak card is narrow enough that the action button
   wraps to its own row (flex-wrap: wrap above), `justify-content:
   space-between` no longer reaches it — wrapped flex rows align
   their items to flex-start by default. Force the button to the
   row's right edge with margin-left: auto so the visual reads as
   "head on the left, action on the right" at every column width,
   matching the wider single-row layout. */
.md-card--speak > .md-btn {
  margin-left: auto !important;
}
.md-card--speak .md-card__head,
.md-card--speak .md-card__row,
.md-card--speak .md-card__org-list {
  position: relative !important;

  z-index: 1 !important;

}
.md-card--speak:has(.md-card__org-list) {
  display: flex !important;

  flex-direction: column !important;

  padding-bottom: calc(18px + 1rem) !important;

}
.md-card--speak .md-card__org-list {
  display: flex !important;

  justify-content: flex-end !important;

  margin-top: auto !important;

  padding-top: 2rem !important;

}
.md-card__icon {
  width: 46px !important;

  height: 46px !important;

  border-radius: 16px !important;

  display: grid !important;

  place-items: center !important;

  background: rgba(255, 255, 255, 0.75) !important;

  border: 1px solid var(--md-line) !important;

}
.md-card__icon--speak { background: rgba(44, 183, 176, 0.12); }
/* SVG icon (when using mic SVG instead of img): .md-card__icon--speak .md-card__icon-svg--mic { color: rgba(44, 183, 176, 0.92); } */
.md-card__icon-img {
  width: 100% !important;

  height: 100% !important;

  object-fit: contain !important;

}

.md-card__row {
  margin-top: 14px !important;

  display: flex !important;

  align-items: center !important;

  justify-content: space-between !important;

  gap: 12px !important;

}
.md-card__row .md-btn--primary {
  width: fit-content !important;

  flex-shrink: 0 !important;

  white-space: nowrap !important;

}

.md-chip {
  display: inline-flex !important;

  align-items: center !important;

  gap: 10px !important;

  padding: 10px 20px !important;

  border-radius: 999px !important;

  border: 1px solid var(--md-line) !important;

  background: rgba(255, 255, 255, 0.70) !important;

  color: $la-navy !important;

  font-weight: 650 !important;

}
.md-chip__dot {
  width: 8px !important;

  height: 8px !important;

  border-radius: 999px !important;

  background: linear-gradient(135deg, var(--md-teal), rgba(91, 141, 239, 0.9)) !important;

}

.md-btn {
  /* WCAG 2.5.5 AAA touch target — was 12px 16px (~36×38). */
  padding: 14px 20px !important;
  min-height: 44px !important;

  border-radius: 16px !important;

  border: 1px solid var(--md-line) !important;

  font-weight: 850 !important;

  box-shadow: var(--md-shadow-2) !important;

  background: rgba(255, 255, 255, 0.72) !important;

  transition: transform 0.12s ease, background 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease !important;

}
.md-btn:hover {
  background: rgba(255, 255, 255, 0.92) !important;
  border-color: rgba($brand-verdigris, 0.35) !important;
  box-shadow: 0 4px 14px rgba($la-navy, 0.10) !important;
}
.md-btn:active { transform: scale(var(--md-tap)); }

.md-btn--primary {
  background: rgba($brand-dusty-denim, 0.3) !important;

  border-color: rgba($brand-dusty-denim, 0.22) !important;

  color: $la-navy !important;

}
.md-btn--primary:hover {
  background: rgba($brand-dusty-denim, 0.45) !important;
  border-color: rgba($brand-dusty-denim, 0.35) !important;
  box-shadow: 0 4px 14px rgba($brand-dusty-denim, 0.15) !important;
}

.md-btn--pill {
  border-radius: 999px !important;

  padding: calc(6px + 0.25rem) calc(12px + 0.25rem) !important;

  font-size: 14px !important; /* WCAG minimum; was 0.9em */

}
.md-btn--primary.md-btn--pill {
  background: linear-gradient(135deg, rgba(44, 183, 176, 0.12), rgba(91, 141, 239, 0.10)) !important;

  backdrop-filter: blur(10px) !important;

  -webkit-backdrop-filter: blur(10px) !important;

  border-color: rgba(255, 255, 255, 0.5) !important;

  color: var(--md-ink) !important;

}
.md-btn--primary.md-btn--pill:hover {
  background: linear-gradient(135deg, rgba(44, 183, 176, 0.18), rgba(91, 141, 239, 0.15)) !important;

  border-color: rgba(255, 255, 255, 0.6) !important;

}

.md-btn--ghost {
  background: rgba(255, 255, 255, 0.62) !important;

}
.md-btn--ghost:hover {
  background: rgba(255, 255, 255, 0.88) !important;
  border-color: rgba($la-navy, 0.15) !important;
  box-shadow: 0 4px 14px rgba($la-navy, 0.08) !important;
}

.md-btn--wide { width: 100%; margin-top: 12px; }

.md-card__bg--wave {
  position: absolute !important;

  inset: -40% -10% auto -10% !important;

  height: calc(220px + 5rem) !important;

  background:
    radial-gradient(circle at 30% 60%, rgba(44, 183, 176, 0.10), transparent 60%),
    radial-gradient(circle at 70% 40%, rgba(107, 152, 241, 0.08), transparent 60%),
    rgba(255, 255, 255, 0.05) !important;
  filter: blur(0px) !important;

  opacity: 0.7 !important;

  pointer-events: none !important;

}

/* --- Boards Card --- */
.md-card--boards { grid-area: boards; }
/* Dashboard home: primary action buttons */
.md-grid--dashboard .md-card--speak .md-btn--primary,
.md-grid--dashboard .md-card--extras .md-btn--primary,
.md-grid--dashboard .md-card--boards .md-btn--primary {
