}
.md-card--boards .md-stat {
  padding: 10px 12px !important;

}

/* Center "Back to Boards" button when new board form is open */
.md-card__head--center-back {
  position: relative !important;

  justify-content: center !important;

}
.md-card__head--center-back .md-card__left,
.md-card__head--center-back .md-stat {
  position: absolute !important;

  visibility: hidden !important;

  pointer-events: none !important;

}

/* Inline Create a New Board form on Boards tab (same content as modal) */
.md-card__new-board-inline {
  margin-top: 16px !important;

  max-height: 70vh !important;

  overflow-y: auto !important;

}
.md-card__new-board-inline .modal-content--standalone {
  max-width: 100% !important;

  margin: 0 !important;

  box-shadow: none !important;

}
.md-card__new-board-inline .board_drop {
  display: block !important;

}

/* New Board page/card – modern dashboard styling (standalone or inline) */
.new-board--modern {
  background: var(--md-surface) !important;

  border-radius: var(--md-r-lg) !important;

  border: 1px solid var(--md-line) !important;

  box-shadow: var(--md-shadow) !important;

  overflow: hidden !important;

}
.new-board--modern .modal-header {
  padding: 20px 24px !important;

  border-bottom: 1px solid var(--md-line) !important;

  background: rgba(255, 255, 255, 0.5) !important;

}
.new-board--modern .modal-header h3 {
  margin: 0 !important;

  font-weight: 900 !important;

  font-size: 20px !important;

  letter-spacing: -0.2px !important;

  color: var(--md-ink) !important;

}
.new-board--modern .create-board-actions {
  display: flex !important;

  flex-wrap: wrap !important;

  gap: 10px !important;

  margin-top: 12px !important;

}
.new-board--modern .create-board-actions .btn,
.new-board--modern .create-board-actions button {
  padding: 10px 14px !important;

  border-radius: 16px !important;

  border: 1px solid var(--md-line) !important;

  font-weight: 750 !important;

  background: rgba(255, 255, 255, 0.72) !important;

  color: var(--md-ink) !important;

  box-shadow: var(--md-shadow-2) !important;

}
.new-board--modern .create-board-actions .btn:hover,
.new-board--modern .create-board-actions button:hover {
  background: rgba(255, 255, 255, 0.88) !important;

}
/* Top-right Create Board: visually match the footer primary CTA
   (teal→blue gradient) instead of inheriting the neutral header
   action-button look. Higher specificity than the rule above. */
.new-board--modern .create-board-actions .new-board__submit--top {
  /* Push only this button to the far right of the flex row; the
     Import / Paste HTML / Generate group stays left-aligned. */
  margin-left: auto !important;
  border: 1px solid rgba(44, 183, 176, 0.18) !important;
  font-weight: 850 !important;
  background: linear-gradient(135deg, rgba(44, 183, 176, 0.24), rgba(91, 141, 239, 0.20)) !important;
  color: var(--md-ink) !important;
}
.new-board--modern .create-board-actions .new-board__submit--top:hover {
  background: linear-gradient(135deg, rgba(44, 183, 176, 0.32), rgba(91, 141, 239, 0.28)) !important;
}
/* Import Board(s) wraps its button in a .file_select_holder span (so the
   hidden file input can intercept clicks). In a flex row, force the span
   to behave like a sibling button — and use overflow: visible so the
   button's box-shadow renders fully (the global .file_select_holder rule
   sets overflow: hidden, which would clip the shadow and make the button
   look subtly different from its neighbors). */
.new-board--modern .create-board-actions .file_select_holder {
  display: inline-flex !important;
  align-items: stretch !important;
  padding: 0 !important;
  margin: 0 !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  overflow: visible !important;
  position: relative;
}
.new-board--modern .create-board-actions .file_select_holder > .btn,
.new-board--modern .create-board-actions .file_select_holder > button {
  margin: 0 !important;
}
.new-board--modern .modal-body {
  padding: 24px !important;

  background: rgba(255, 255, 255, 0.4) !important;

}
.new-board--modern .form-group {
  margin-bottom: 18px !important;

}
.new-board--modern .form-group label.control-label {
  display: block !important;

  margin-bottom: 6px !important;

  font-weight: 750 !important;

  font-size: 14px !important;

  color: var(--md-ink) !important;

}
.new-board--modern .form-control {
  border-radius: 14px !important;

  border: 1px solid var(--md-line) !important;

  padding: 10px 14px !important;

  background: rgba(255, 255, 255, 0.9) !important;

  color: var(--md-ink) !important;

}
.new-board--modern #new_board_name,
.new-board--modern #new_board_rows,
.new-board--modern #new_board_columns {
  font-size: 14px !important;

}
.new-board--modern .form-control:focus-visible {
  border-color: var(--md-teal) !important;

  outline: none !important;

  box-shadow: 0 0 0 2px rgba(44, 183, 176, 0.2) !important;

}
.new-board--modern .input-group .btn {
  padding: 8px 12px !important;

  border-radius: 14px !important;

  border: 1px solid var(--md-line) !important;

  background: rgba(255, 255, 255, 0.72) !important;

  font-weight: 700 !important;

}
.new-board--modern .input-group .form-control {
  border-radius: 14px !important;

}
.new-board--modern .modal-footer {
  padding: 20px 24px !important;

  border-top: 1px solid var(--md-line) !important;

  background: rgba(255, 255, 255, 0.5) !important;

}
.new-board--modern .modal-footer .new-board__submit,
.new-board--modern .modal-footer .btn-primary {
  padding: 12px 24px !important;

  border-radius: 16px !important;

  border: 1px solid rgba(44, 183, 176, 0.18) !important;

  font-weight: 850 !important;

  background: linear-gradient(135deg, rgba(44, 183, 176, 0.24), rgba(91, 141, 239, 0.20)) !important;

  color: var(--md-ink) !important;

  box-shadow: var(--md-shadow-2) !important;

}
.new-board--modern .modal-footer .new-board__submit:hover:not(:disabled),
.new-board--modern .modal-footer .btn-primary:hover:not(:disabled) {
  background: linear-gradient(135deg, rgba(44, 183, 176, 0.32), rgba(91, 141, 239, 0.28)) !important;

}
.new-board--modern .modal-footer .new-board__submit:disabled,
.new-board--modern .modal-footer .btn-primary:disabled {
  /* Light gray bg + dark slate text for WCAG AA contrast (~12.5:1) — replaces
     the prior opacity: 0.7 treatment which washed out both layers and failed
     contrast against the footer background. */
  background: #e5e7eb !important;
  color: #1f2937 !important;
  border: 1px solid rgba(31, 41, 55, 0.18) !important;
  box-shadow: none !important;
  opacity: 1 !important;
  cursor: not-allowed !important;
}
/* Standalone (page) footer: Cancel sits to the left of Create Board, group
   centered horizontally on the page. Cancel-then-primary follows modern
   web/SaaS convention (macOS HIG / Material / GitHub / Stripe / Figma). */
.new-board--modern .modal-footer .new-board__footer-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
  justify-content: center;
}
/* Row that holds a section's verdigris title pill + a small gray
   "optional" pill side-by-side. flex-start keeps both pinned to the
   left edge of the section, with a tight gap between the two. */
.nb-section__title-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  align-self: flex-start;
  /* Cancel the parent .nb-section's flex gap on this row's bottom — the
     section's `gap: 12px` should remain between row and hint, but the
     row itself is just one logical line. */
  margin: 0;
}
/* Small gray "optional" chip. Sized to read as a sibling of the
   eyebrow pill but visually subordinate — neutral fill, lighter type,
   no uppercase. The pill chrome (rounded, soft border, faint inset
   highlight) mirrors the verdigris pill's shape so they read as a
   pair. */
.nb-section__optional-pill {
  display: inline-flex;
  align-items: center;
  padding: 4px 12px;
  font-size: 14px;
  font-weight: 500;
  font-style: italic;
  letter-spacing: 0;
  text-transform: lowercase;
  color: rgba($la-navy, 0.62);
  background: rgba(13, 36, 56, 0.06);
  border: 1px solid rgba(13, 36, 56, 0.10);
  border-radius: 999px;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.5);
}
/* Field-level "optional" pill — sits inline next to a regular field
   label (Description, "Are you creating this board for someone else?")
   rather than next to a section eyebrow. Smaller and tighter than
   `.nb-section__optional-pill`, but same color language so the two
   read as a system. Margin-left pulls it off the label text by 8px. */
.nb-field__optional-pill {
  display: inline-flex;
  align-items: center;
  margin-left: 8px;
  padding: 2px 10px;
  font-size: 14px;
  font-weight: 500;
  font-style: italic;
  letter-spacing: 0;
  text-transform: lowercase;
  color: rgba($la-navy, 0.55);
  background: rgba(13, 36, 56, 0.05);
  border: 1px solid rgba(13, 36, 56, 0.09);
  border-radius: 999px;
  vertical-align: middle;
  /* Reset the label's bold weight + text-transform — the pill's own
     italic-lowercase styling should win regardless of whose child
     element it lives in. */
  text-decoration: none;
}
/* Required-field pill — same shape as the optional pill but a warm
   accent so "required" reads as a stronger signal than "optional". */
.nb-field__required-pill {
  display: inline-flex;
  align-items: center;
  margin-left: 8px;
  padding: 2px 10px;
  font-size: 14px;
  font-weight: 600;
  font-style: italic;
  letter-spacing: 0;
  text-transform: lowercase;
  color: #b8761c;
  background: rgba(232, 163, 23, 0.12);
  border: 1px solid rgba(232, 163, 23, 0.32);
  border-radius: 999px;
  vertical-align: middle;
  text-decoration: none;
}

/* ── AI mode header: status pill + "other methods" pill ────────────
   The pill mirrors the board-detail edit "Editing…" badge
   (.md-board-detail-header__editing-badge): verdigris rounded pill,
   two-row column (icon+title row, caption row). The other-methods
   control sits below it and returns to the regular options. */
.nb-ai-mode-wrap {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}
.nb-ai-mode-badge {
  flex-shrink: 0;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 4px 14px 6px;
  border-radius: 999px;
  background: rgba($brand-verdigris, 0.10);
  color: $brand-verdigris-aa;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.02em;
  white-space: nowrap;
}
.nb-ai-mode-badge__row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: 100%;
}
.nb-ai-mode-badge__caption {
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.02em;
  line-height: 1.1;
  width: 100%;
  text-align: center;
  color: $brand-slate-gray;
}
.nb-ai-mode-other {
  appearance: none;
  cursor: pointer;
  padding: 6px 16px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 700;
  color: rgba($la-navy, 0.7);
  background: rgba(13, 36, 56, 0.05);
  border: 1px solid rgba(13, 36, 56, 0.12);
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}
.nb-ai-mode-other:hover,
.nb-ai-mode-other:focus-visible {
  color: $la-navy;
  background: rgba(13, 36, 56, 0.09);
  border-color: rgba(13, 36, 56, 0.2);
  outline: none;
}
.md-board-detail--dark .nb-ai-mode-badge {
  background: rgba($brand-verdigris, 0.22);
  color: color.adjust($brand-verdigris, $lightness: 22%);
}
.md-board-detail--dark .nb-ai-mode-badge__caption {
  color: color.adjust($brand-verdigris, $lightness: 22%);
}
/* AI-mode header: keep the badge + "Other methods" button on a single
   left-aligned row, tucked just under the "Create a New Board" title.
   50% larger than the base pill/control sizes. Scoped via :has so the
   regular (non-AI) header layout is unaffected. */
.new-board--modern .create-board-actions:has(.nb-ai-mode-wrap),
.la-new-board-modal-actions:has(.nb-ai-mode-wrap) {
  width: 100% !important;
  justify-content: flex-start !important;
}
/* Button pinned to the left edge, badge centered across the full modal
   width (the two 1fr side columns keep the badge optically centered on
   the page regardless of the button's width). Both on one row. */
.nb-ai-mode-wrap {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  width: 100%;
  margin: 0;
  gap: 12px;
}
.nb-ai-mode-wrap .nb-ai-mode-other {
  grid-column: 1;
  justify-self: start;
}
.nb-ai-mode-wrap .nb-ai-mode-badge {
  grid-column: 2;
  justify-self: center;
}
/* Lift the "Generating with AI" pill out of the wrap and onto the
   title row, centered across the modal. The button stays in the grid
   below-left. Anchored to the header's title baseline: header
   padding-top (20px) + ~half the 20px h3 line box ≈ 32px. */
.new-board--modern .modal-header {
  position: relative !important;
}
.new-board--modern .modal-header .create-board-actions:has(.nb-ai-mode-wrap) .nb-ai-mode-badge {
  position: absolute;
  top: 32px;
  left: 50%;
  transform: translate(-50%, -50%);
  margin: 0;
}
/* Narrow screens: swap the two — the "Other Create Board Methods"
   button moves up onto the title row (centered, absolute) and the AI
   badge drops back into the grid's left column. Mirrors the desktop
   placements exactly, just with the elements traded. */
@media (max-width: 1024px) {
  .new-board--modern .modal-header .create-board-actions:has(.nb-ai-mode-wrap) .nb-ai-mode-badge {
    position: static;
    top: auto;
    left: auto;
    transform: none;
    /* 1rem top margin so the badge sits below (not flush against) the
       absolute-positioned Other Create Board Methods button on the title
       row. Set here (instead of on the lower-specificity wrap rule below)
       so this rule's margin shorthand doesn't zero it out. */
    margin: 1rem 0 0;
  }
  .new-board--modern .modal-header .create-board-actions:has(.nb-ai-mode-wrap) .nb-ai-mode-other {
    position: absolute;
    top: 32px;
    left: 50%;
    transform: translate(-50%, -50%);
    margin: 0;
  }
  .nb-ai-mode-wrap .nb-ai-mode-badge {
    /* Span the full grid track and center horizontally so the badge
       sits on the page's centerline (not constrained by the 1fr/auto/1fr
       column the button used to anchor). */
    grid-column: 1 / -1;
    justify-self: center;
  }
  .nb-ai-mode-wrap .nb-ai-mode-other {
    grid-column: 2;
    justify-self: center;
  }
}
