  width: auto !important;
  max-width: none !important;
  float: none !important;
}
.md-stats-compare-row--filter > [class*='col-']:nth-child(3)[style*="#{'border-left'}"] {
  border-left: 1px solid rgba(240, 106, 91, 0.35) !important;
}
/* Form inside period columns: full width, flex, center its content */
.md-stats-compare-row--filter > .md-stats-filter:first-child .md-stats-filter__form,
.md-stats-compare-row--filter > [class*='col-']:first-child .md-stats-filter__form,
.md-stats-compare-row--filter > .md-stats-filter:nth-child(3) .md-stats-filter__form,
.md-stats-compare-row--filter > [class*='col-']:nth-child(3) .md-stats-filter__form {
  display: flex !important;
  flex-wrap: wrap;
  justify-content: center !important;
  align-items: center !important;
  width: 100% !important;
  max-width: 100%;
}
/* Comparison: compact single-row layout per side, centered */
.md-stats-compare-row .md-stats-filter .md-stats-filter__form {
  justify-content: center;
}
.md-stats-compare-row .md-stats-filter .md-stats-filter__row--period-actions {
