  pointer-events: none;
  visibility: hidden;
}
.md-shell--board-view .md-grid {
  grid-template-columns: 1fr;
  grid-template-rows: 1fr;
  grid-template-areas: "boards";
  gap: 0;
  align-items: stretch;
  min-height: 60vh;
}
.md-shell--board-view .md-card--speak,
.md-shell--board-view .md-card--sup,
.md-shell--board-view .md-card--reports,
.md-shell--board-view .md-card--extras {
