}
.md-shell--board-view .md-boards-page .md-strip__label { margin-top: 10px; }
.md-shell--board-view .md-boards-page .md-thumb {
  height: 72px;
  border-radius: 17px;
}
.md-shell--board-view .md-boards-page .md-thumb__icon {
  width: 43px;
  height: 43px;
}
.md-shell--board-view .md-boards-page .md-btn {
  padding: 14px 19px;
