}

/* ---------- Supervisor view (Supervisors tab: only supervisors card expanded, full list) ---------- */
.md-shell--supervisor-view .md-hero {
  opacity: 0 !important;

  transform: translateY(-12px) scale(0.98) !important;

  max-height: 0 !important;

  margin: 0 !important;

  padding: 0 !important;

  overflow: hidden !important;

  pointer-events: none !important;

  visibility: hidden !important;

