/* ─── Board-alt edit mode: lean inner_header ─────────────────────────
   In edit mode, only the editing toolbar (Edit, Paint, Undo, Redo,
   Grid +/-, Ideas, More, Save, Cancel) should be visible in the
   #inner_header. The brand logo, identity dropdown, beta-feedback link,
   support link, settings, and style switcher all hide. */
#within_ember.board-alt-view.edit-mode-active {
  #inner_header #nav_header h1.with_board {
    display: none !important;
  }
  #inner_header #identity {
    display: none !important;
  }
  /* With logo + identity hidden, center the remaining edit toolbar
     buttons horizontally inside the inner_header. */
  #inner_header {
    text-align: center !important;
  }
  #inner_header #nav_header {
    display: block !important;
    text-align: center !important;
    width: 100%;
  }
}

/* ─── Wide / Skinny edit-toolbar buttons: responsive breakpoints ─────
   Default app rules render `.skinny` always-on and `.wide` always-off.
   Inside the board-alt edit toolbar, swap that so the text-labeled
   "wide" buttons show on >= 900px screens and the icon-only "skinny"
   buttons show below 900px. */
#within_ember.board-alt-view.edit-mode-active {
  #inner_header #nav_header .btn .skinny,
  #inner_header #nav_header .btn.wide {
    display: none !important;
  }
  #inner_header #nav_header .btn .wide {
    display: inline !important;
  }
  @media (max-width: 899px) {
    #inner_header #nav_header .btn .skinny {
      display: inline !important;
    }
    #inner_header #nav_header .btn .wide {
      display: none !important;
    }
  }
}

// === Board Alt View: speech-card styled buttons ===
#within_ember.board-alt-view {
  .board {
    background: $brand-charcoal-blue !important;
  }

  &:has(#nav_header) .board {
    margin-top: 2.25rem;
  }

  &:has(#nav_header) #stash_hover {
    /* Positioning kept exactly as the original (margins 0/0). Only
       the fixed 82×82 / 41px-block sizing is relaxed to auto so the
       27px icon + two-line label is no longer clipped. */
    margin-top: 0 !important;
    margin-left: 0 !important;
    width: max-content !important;
    height: auto !important;
    .option {
      float: none !important;
      display: block !important;
      width: 100% !important;
      height: auto !important;
      &:last-child {
        border-left: none !important;
        border-top: 1px solid #ccc !important;
        padding-left: 5px !important;
      }
    }
  }

  .board .button {
    border: 2px solid var(--btn-bg, $color-linen) !important;
    border-radius: 12px !important;
    box-shadow: 0 1px 3px rgba($indigo, 0.06);
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
    color: $indigo !important;
  }
  /* Add interior padding directly on the <a class="button"> link element.
     The inner img_holder and button-label-holder are absolutely positioned
     against this link's padding box, so insetting them by 4px each gives
     the visible "more padding inside the button" effect. */
  .board a.button {
    padding: 4px !important;
  }
  .board a.button .img_holder {
    top: 4px !important;
    left: 4px !important;
    right: 4px !important;
    width: calc(100% - 8px) !important;
  }
  .board a.button .button-label-holder {
    left: 4px !important;
    width: calc(100% - 8px) !important;
  }
  .board a.button .button-label-holder:not(.top) {
    bottom: 2px !important;
  }
  .board a.button .button-label-holder.top {
    top: 2px !important;
  }
  /* The shared `.button span.button-label` sets a fixed height equal to
     the font-size with `line-height: 1.1` and `overflow: hidden`, so the
     bottom of descenders ("p", "g", "y" in "Top Page" / "dining room")
     gets clipped on the board-alt grid. The global border-box means
     adding padding-bottom alone would eat the fixed height and clip
     MORE — so switch this label to content-box and add a font-relative
     bottom pad. content-box keeps the fixed line height while the extra
     0.3em sits BELOW it inside the overflow box, so the full glyph shows
     at every text size. Scoped to board-alt; board-detail uses a
     different label element and is unaffected. */
  .board a.button span.button-label {
    box-sizing: content-box !important;
    padding-bottom: 0.3em !important;
  }

  // Focus words (dim_button): strengthen dimming on board-alt grid (same intent as board-view block above).
  .board .button.dim_button {
    opacity: 0.4 !important;
    filter: saturate(45%) brightness(0.88) !important;
  }
  &.mid_dim .board .button.dim_button {
    opacity: 0.32 !important;
    filter: saturate(38%) brightness(0.84) !important;
  }
  &.extra_dim .board .button.dim_button {
    opacity: 0.22 !important;
    filter: saturate(30%) brightness(0.78) !important;
  }

  .board .button.focus_word_button {
    opacity: 1 !important;
    filter: saturate(100%) brightness(1) !important;
    outline: 3px solid rgba($brand-verdigris, 0.95) !important;
    outline-offset: 2px !important;
    box-shadow:
      0 0 0 5px rgba($brand-verdigris, 0.22),
      0 4px 16px rgba($la-navy, 0.12) !important;
    z-index: 2;
  }


  .board .button.touched,
  .board .button:focus-visible {
    border-width: 2px !important;
    border-color: $cat-people-base !important;
    box-shadow: 0 0 0 3px rgba(123, 174, 140, 0.25) !important;
  }

  .board .button .img_holder {
    background: #e8f5f4 !important;
  }

  /* Transparent label-holder lets the button's bg show through so the top
     section matches the rest of the button. The 2px border reads uniformly
     because the label-holder no longer paints over it. */
  .board .button .button-label-holder {
    background: transparent !important;
  }

  .board .button .button-label {
    font-weight: 700 !important;
    color: $indigo !important;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif !important;
  }

  /* Match the board-detail "Colored Corner" folder setting:
     a square quarter-circle "fan" wedge in the top-right, fully
     saturated (no brightness filter), painted with the button's
     darkened ring color — same depth as the inner ring on its
     siblings, mirroring board-detail's use of `var(--btn-border)`.
     `--btn-ring-color` is set by bound_classes alongside `--btn-bg`
     (autoBorder.darken(20)) for every colored button, so the corner
     reads at the same depth as the outline rather than the lighter
     fill. Falls back to `--btn-bg` for legacy buttons that only have
     a fill set. Size scales fluidly with button width via clamp(),
     so small buttons get small corners and large buttons get
     proportionally larger ones — no text-size-class breakpoints. */
  .board .button .action_container.folder,
  .board .button .action_container.integration {
    top: 0 !important;
    right: 0 !important;
    width: clamp(10px, 22%, 28px) !important;
    height: clamp(10px, 22%, 28px) !important;
    border: none !important;
    border-radius: 0 0 0 100% !important;
    background: var(--btn-ring-color, var(--btn-bg, currentColor)) !important;
    filter: none !important;
    opacity: 1 !important;
    z-index: 3;
    pointer-events: none;
    transform: none !important;
    .action {
      visibility: hidden !important;
    }
  }
}

