// === Board View: Modern light aesthetic (regular board page, not board-alt) ===
#within_ember.board-view {
  // Warm-to-cool gradient background matching landing-alt / authenticated-view feel
  background: linear-gradient(
    160deg,
    #{color.adjust($brand-stone-100, $lightness: 5%)} 0%,
    #{color.adjust($brand-stone-200, $lightness: 5%)} 40%,
    #eaf2f1 100%
  ) !important;

  // Board grid: frosted glass background only — no margin/width override since
  // computeHeight() sizes the board from window.innerWidth/Height; changing those
  // would misalign the pixel-positioned button grid.
  // background has no !important so boards with a custom background.color (set as
  // inline style by board_style) keep their author-specified color.
  #content .board {
    background: rgba(255, 255, 255, 0.72);
    box-shadow: 0 8px 32px rgba($brand-blue-black, 0.09), 0 1px 4px rgba($brand-blue-black, 0.05) !important;
  }

  // Buttons: lighten background 50% toward white, subtle border, softer radius
  .board .button {
    background: color-mix(in oklch, var(--btn-bg, $color-linen) 50%, white) !important;
    border: 2px solid var(--btn-bg, $color-linen) !important;
    border-radius: 12px !important;
    box-shadow: 0 1px 3px rgba($indigo, 0.06) !important;
    transition: border-color 0.15s ease, box-shadow 0.15s ease !important;
    color: $indigo !important;
    filter: saturate(70%);
  }

  // Focus words: `dim_button` is set on non-focus buttons (bound_classes + board contextualized_buttons).
  // This shell applies `filter: saturate(70%)` to every `.board .button`, which stacks with the global
  // `.board .button.dim_button { opacity: … }` rules and makes dimming look too subtle. Override filter +
  // opacity for dim buttons only so focus words stand out clearly.
  .board .button.dim_button {
    opacity: 0.38 !important;
    filter: saturate(38%) brightness(0.9) !important;
  }
  &.mid_dim .board .button.dim_button {
    opacity: 0.3 !important;
    filter: saturate(32%) brightness(0.85) !important;
  }
  &.extra_dim .board .button.dim_button {
