// === Board Picker Overlay ===
@keyframes board-picker-backdrop-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

@keyframes board-picker-expand {
  from {
    opacity: 0;
    transform: translateX(-50%) scaleY(0.04) scaleX(0.18) translateY(-6px);
  }
  50% {
    opacity: 1;
  }
  to {
    opacity: 1;
    transform: translateX(-50%) scaleY(1) scaleX(1) translateY(0);
  }
}

@keyframes board-picker-icon-to-x {
  from { transform: rotate(0deg) scale(1); }
  to   { transform: rotate(90deg) scale(0.9); }
}

#board_picker_backdrop {
  cursor: default;
  animation: board-picker-backdrop-in 0.2s ease both;
}

.board-picker-btn--open {
  background: rgba($brand-dusty-denim, 0.15) !important;
  border-color: rgba($brand-dusty-denim, 0.4) !important;
  color: #2c5fa8 !important;

  svg {
    animation: board-picker-icon-to-x 0.2s cubic-bezier(0.22, 1, 0.36, 1) both;
  }
}

#board_picker {
  position: fixed;
  top: var(--topbar-height);
  left: 50%;
  transform: translateX(-50%);
  width: min(80vw, 960px);
  bottom: 12px;
  z-index: 901;
  background: rgba(246, 247, 250, 0.94);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  overflow-y: auto;
  overscroll-behavior: contain;
  transform-origin: top center;
  animation: board-picker-expand 0.28s cubic-bezier(0.22, 1, 0.36, 1) both;
  border: 1px solid rgba($brand-blue-black, 0.10);
  border-radius: 16px;
  box-shadow: 0 10px 40px rgba($brand-blue-black, 0.18);
  isolation: isolate;

  // Ambient orbs in the flanking empty space
  &::before,
  &::after {
    content: '';
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
    z-index: -1;
  }

  // Top-right orb
  &::before {
    width: 420px;
    height: 420px;
    top: -80px;
    right: -60px;
    background: radial-gradient(circle, rgba($brand-dusty-denim, 0.13) 0%, rgba($brand-dusty-denim, 0.0) 70%);
  }

  // Bottom-left orb
  &::after {
    width: 360px;
    height: 360px;
    bottom: -60px;
    left: -40px;
    background: radial-gradient(circle, rgba(63, 127, 123, 0.10) 0%, rgba(63, 127, 123, 0.0) 70%);
  }
}

#board_picker_header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 5% 14px;
  border-bottom: 1px solid rgba($la-navy, 0.15);
}

#board_picker_header .la-section-eyebrow-badge {
  margin-bottom: 0 !important;
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border: none !important;
  box-shadow: none !important;
  color: $la-navy !important;
  font-size: 20px !important;
  font-weight: 700 !important;
  padding: 0 !important;
  letter-spacing: -0.01em !important;
}

.board-picker__close {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 1.5px solid rgba($brand-blue-black, 0.14);
  background: rgba(255, 255, 255, 0.70);
  color: #3a4a66;
  cursor: pointer;
  box-shadow: 0 2px 8px rgba($brand-blue-black, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.9);
  transition: background 0.15s ease, color 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
  padding: 0;

  &:hover {
    background: rgba(255, 255, 255, 0.95);
    border-color: rgba($brand-blue-black, 0.22);
    color: $indigo;
    box-shadow: 0 4px 14px rgba($brand-blue-black, 0.13), inset 0 1px 0 rgba(255, 255, 255, 1);
  }

  &:active {
    background: rgba(240, 242, 248, 0.95);
    box-shadow: 0 1px 4px rgba($brand-blue-black, 0.10);
  }
}

.board-picker__filter-row {
  display: flex;
  align-items: stretch;
  flex-wrap: wrap;
  gap: 10px;
  /* Row now hosts just Change Home Board + New Board (the Home Board
     shortcut and Filter input were lifted out to other slots). Center
     the pair on the modal centerline so they read as a balanced
     two-button group, rather than getting glued to the left/right
     edges by `margin-left: auto`. */
  justify-content: center;
  width: 92%;
  max-width: 720px;
  /* 1rem top margin so the row sits lower in the modal, off the
     header's bottom edge. */
  margin: 1rem auto 0;
}
/* "Set Home Board" / "Change Home Board" toggle. Base style copied
   verbatim from the (removed) `.board-picker__home-btn` so the
   visual continuity carries: same white pill, navy ink, 1.5px subtle
   border, verdigris hover accent. The --active (selection mode)
   variant stays loud-verdigris so the modal still announces "you're
   now picking a home board" when toggled on. */
.board-picker__set-home-btn {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 8px 16px;
  background: rgba(255, 255, 255, 0.8);
  border: 1.5px solid rgba($la-navy, 0.12);
  border-radius: 12px;
  color: $la-navy;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;
}
.board-picker__set-home-btn:hover {
  border-color: $brand-verdigris;
  background: rgba(255, 255, 255, 0.95);
  box-shadow: 0 1px 4px rgba($brand-verdigris, 0.12);
}
.board-picker__set-home-btn--active {
  background: $brand-verdigris-aa;
  border-color: $brand-verdigris-aa;
  color: #fff;
  box-shadow: 0 2px 6px rgba($brand-verdigris-aa, 0.30);
}
.board-picker__set-home-btn--active:hover {
  background: $brand-verdigris;
  border-color: $brand-verdigris;
  color: #fff;
  box-shadow: 0 2px 6px rgba($brand-verdigris-aa, 0.30);
}
/* Home-glyph icon to the left of the label — verdigris-aa fill so it
   reads as the "home" accent and not as decoration. In --active mode
   the parent flips to a verdigris fill, so the icon needs to flip to
   white to stay legible against it. */
.board-picker__set-home-btn-icon {
  flex-shrink: 0;
  color: $brand-verdigris-aa;
}
.board-picker__set-home-btn--active .board-picker__set-home-btn-icon {
  color: #fff;
}
/* "New Board" — pushed to the far right of the filter row via
   margin-left: auto. Background mirrors the home-page dashboard's
   `.md-btn--primary.md-btn--pill` so the entry-point reads the same
   wherever the user sees it (home dashboard, My Boards modal,
   boards page). Text/border colors match too, since the gradient is
   light enough that white text would be unreadable. */
.board-picker__new-board-btn {
  flex-shrink: 0;
  /* `margin-left: auto` previously pushed this to the far right of
     the filter row. Removed so the parent's `justify-content: center`
     can keep the (Change Home Board + New Board) pair grouped on
     the centerline instead. */
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 44px;
  padding: 8px 14px;
  background: linear-gradient(135deg, rgba(44, 183, 176, 0.12), rgba(91, 141, 239, 0.10));
  border: 1px solid rgba(255, 255, 255, 0.5);
  border-radius: 12px;
  color: var(--md-ink);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  /* Stronger shadow so the low-contrast translucent gradient still
     reads as a raised, tappable control against the modal/page
     background (the gradient alone fails WCAG vs the surrounding
     surface). Outer drop + close inner lift + subtle inset top
     highlight for depth. */
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.6) inset,
    0 1px 2px rgba($la-navy, 0.12),
    0 6px 14px rgba($la-navy, 0.22);
  transition: background 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
}
.board-picker__new-board-btn:hover {
  background: linear-gradient(135deg, rgba(44, 183, 176, 0.18), rgba(91, 141, 239, 0.15));
  border-color: rgba(255, 255, 255, 0.6);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.65) inset,
    0 2px 4px rgba($la-navy, 0.14),
    0 10px 22px rgba($la-navy, 0.28);
  color: var(--md-ink);
}
/* Boards page "New Board" button (components/boards-browser.hbs) had
   no styling — gets the same gradient look as the My Boards modal +
   home dashboard pill, plus the matching pill shape since browser
   defaults left it unstyled before. */
.ub-boards-page__new-board-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 44px;
  padding: calc(6px + 0.25rem) calc(12px + 0.25rem);
  background: linear-gradient(135deg, rgba(44, 183, 176, 0.12), rgba(91, 141, 239, 0.10));
  border: 1px solid rgba(255, 255, 255, 0.5);
  border-radius: 999px;
  color: var(--md-ink);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  /* Stronger shadow so the low-contrast translucent gradient still
     reads as a raised, tappable control against the modal/page
     background (the gradient alone fails WCAG vs the surrounding
     surface). Outer drop + close inner lift + subtle inset top
     highlight for depth. */
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.6) inset,
    0 1px 2px rgba($la-navy, 0.12),
    0 6px 14px rgba($la-navy, 0.22);
  transition: background 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
}
.ub-boards-page__new-board-btn:hover {
  background: linear-gradient(135deg, rgba(44, 183, 176, 0.18), rgba(91, 141, 239, 0.15));
  border-color: rgba(255, 255, 255, 0.6);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.65) inset,
    0 2px 4px rgba($la-navy, 0.14),
    0 10px 22px rgba($la-navy, 0.28);
  color: var(--md-ink);
}
/* Selection-mode banner: shown above the filter row while the user
   is in "Set/Change Home Board" mode. Reuses the verdigris notice
   styling from __no-home-msg so the two messages read as a family. */
.board-picker__selecting-home-msg {
  width: 92%;
  max-width: 720px;
  margin: 0 auto 8px;
  padding: 10px 14px;
  background: rgba($brand-verdigris-aa, 0.14);
  border: 1px solid rgba($brand-verdigris-aa, 0.40);
  border-radius: 10px;
  color: $brand-verdigris-aa;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  text-align: center;
}
.board-picker__home-btn {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  /* WCAG 2.5.5 AAA touch target. */
  min-height: 44px;
  padding: 8px 16px;
  background: rgba(255, 255, 255, 0.8);
  border: 1.5px solid rgba($la-navy, 0.12);
  border-radius: 12px;
  color: $la-navy;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;
}
.board-picker__home-btn:hover {
  border-color: $brand-verdigris;
  background: rgba(255, 255, 255, 0.95);
  box-shadow: 0 1px 4px rgba($brand-verdigris, 0.12);
}
.board-picker__home-btn--unset {
  border-color: rgba($brand-verdigris-aa, 0.45);
  background: rgba($brand-verdigris-aa, 0.06);
}
.board-picker__home-btn--unset:hover {
  border-color: $brand-verdigris-aa;
  background: rgba($brand-verdigris-aa, 0.10);
}
.board-picker__no-home-msg {
  width: 90%;
  max-width: 480px;
  margin: 0 auto 8px;
  padding: 10px 14px;
  background: rgba($brand-verdigris-aa, 0.08);
  border: 1px solid rgba($brand-verdigris-aa, 0.25);
  border-radius: 10px;
  color: $la-navy;
  font-size: 14px;
  line-height: 1.4;
  text-align: center;
}
.board-picker__home-btn-icon {
  flex-shrink: 0;
  color: $brand-verdigris-aa;
}
.board-picker__home-btn-label {
  white-space: nowrap;
}
.board-picker__filter {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding: 8px 14px;
  background: rgba(255, 255, 255, 0.8);
  border: 1.5px solid rgba($la-navy, 0.12);
  border-radius: 12px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.board-picker__filter:focus-within {
  border-color: $brand-verdigris;
  box-shadow: 0 0 0 3px rgba($brand-verdigris, 0.12);
}
.board-picker__filter-icon {
  flex-shrink: 0;
  color: $brand-cool-steel;
}
.board-picker__filter-input {
  flex: 1;
  border: none;
  outline: none;
  background: transparent;
  font-size: 15px;
  color: $la-navy;
  min-width: 0;
}
.board-picker__filter-input:focus-visible {
  @include focus-ring;
}
.board-picker__filter-input::placeholder {
