}
.board-picker__filter-clear {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border: none;
  border-radius: 50%;
  background: rgba($la-navy, 0.08);
  color: $brand-slate-gray;
  cursor: pointer;
  padding: 0;
