    transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease, transform 0.15s ease;
    &:hover {
      background: rgba($brand-blue-black, 0.08);
      border-color: rgba($brand-blue-black, 0.18);
      color: $indigo;
      transform: translateX(-2px);
    }
  }
  &__subresult {
