    border: 1px solid rgba($brand-blue-black, 0.10);
    cursor: pointer;
    transition: background 0.15s ease, color 0.15s ease;
  }
  &__folder-rename-save {
    background: rgba(44, 183, 176, 0.1);
    color: $brand-stormy-teal;
    &:hover {
      background: rgba(44, 183, 176, 0.2);
    }
  }
  &__folder-rename-cancel {
    background: rgba($brand-blue-black, 0.04);
    color: #8a96a8;
