  /* Home Board tile distinction on the boards page — mirrors the
     dashboard board strip's `.md-strip__item--home` + badge and the
     My Boards picker's `.board-picker__item--home` so all three
     surfaces flag the user's home board the same way. Verdigris
     halo on the tile, floating uppercase "HOME BOARD" pill above. */
  &__board-item--home {
    position: relative;
    .btn.simple_board_icon {
      border-color: $brand-verdigris !important;
      border-width: 2px !important;
      box-shadow:
        0 0 0 4px rgba($brand-verdigris, 0.12),
        0 8px 24px rgba($brand-verdigris, 0.18),
        0 2px 12px rgba(0, 0, 0, 0.06) !important;
    }
  }
  &__board-item-home-badge {
    position: absolute;
    top: -10px;
    left: 50%;
    transform: translateX(-50%);
    background: linear-gradient(135deg, $brand-verdigris, $brand-verdigris-aa);
    color: #fff;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    padding: 4px 10px;
    border-radius: 999px;
    box-shadow: 0 2px 6px rgba($la-navy, 0.22);
    white-space: nowrap;
    pointer-events: none;
    z-index: 1;
  }
  /* Defensive override: the boards-page parent grid sets
     `> .simple_board_holder > * { width: 100%; display: flex;
     align-items: stretch }` (line ~36561) which stretches the home
     badge into a wide ribbon across the top of the tile. Higher
     specificity (0,3,0) wins against that (0,2,1) rule and keeps the
     badge as a centered shrink-to-fit pill. */
  &__board-item.simple_board_holder > &__board-item-home-badge {
    width: auto;
    max-width: max-content;
    display: inline-block;
    align-self: auto;
  }

  /* Fixed card width so every board tile aligns on boards + search pages */
  $ub-boards-page-card-w: 280px;
  &__board-grid {
    display: flex !important;
    flex-wrap: wrap;
    justify-content: center;
    gap: 0.5rem 0.75rem;
    margin-left: 0 !important;
    margin-right: 0 !important;
    width: 100%;
    overflow-anchor: none;

    .simple_board_holder {
      padding: 0;
      flex: 0 0 $ub-boards-page-card-w;
      width: $ub-boards-page-card-w;
      max-width: 100%;
      display: flex;
      flex-direction: column;
      align-items: stretch;
      justify-content: flex-start;
      box-sizing: border-box;

      > .ember-view,
      > * {
        width: 100%;
        max-width: 100%;
        min-width: 0;
        box-sizing: border-box;
        display: flex;
        flex-direction: column;
        align-items: stretch;
      }
    }

    // Board card styling (matches md-user-summary__available-boards)
    .board_with_action.simple_board_holder .btn.simple_board_icon,
    .simple_board_holder .btn.simple_board_icon {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: flex-start;
      width: 100%;
      max-width: 100%;
      box-sizing: border-box;
      height: auto;
      /* Consistent min-height so every tile in the grid takes up the
         same vertical footprint by default (gives the boards page a
         clean uniform-grid feel). Tiles auto-grow past this when
         their content needs more room (long titles, longer author
         lines, etc.) thanks to `height: auto`. */
      min-height: 300px;
      /* Top padding bumped 1rem (2.4rem → 3.4rem) so the icon,
         title, and PREVIEW pill stack sit 1rem lower from the top
         edge. Bottom padding back to 2rem (the PREVIEW pill is
         anchored at the bottom of the flex column via margin-top:
         auto, so this padding becomes the breathing strip beneath
         the pill). */
      padding: 3.4rem 2.4rem 2rem;
      border-radius: var(--md-r-lg, 16px);
      border: 1px solid var(--md-line, rgba($brand-blue-black, 0.12));
      background: rgba(255, 255, 255, 0.92);
      box-shadow: 0 2px 12px rgba(0, 0, 0, 0.06);
      color: var(--md-ink);
      transition: border-color 0.2s ease, box-shadow 0.2s ease;
      font-size: 19.5px;
      overflow: visible;
    }
    .board_with_action.simple_board_holder .btn.simple_board_icon:hover,
    .simple_board_holder .btn.simple_board_icon:hover {
      border-color: rgba(44, 183, 176, 0.3);
      box-shadow: 0 6px 20px rgba(0, 0, 0, 0.08);
    }
    .simple_board_holder .btn.simple_board_icon img {
      width: 100%;
      max-width: 160px;
      height: 110px;
      object-fit: contain;
      object-position: center;
      margin-bottom: 1rem;
      flex-shrink: 0;
    }
    .simple_board_holder .btn.simple_board_icon .name {
      width: 100%;
      font-size: 1.69rem;
      font-weight: 600;
      line-height: 1.4;
      margin: 0 0 6px;
      max-height: none;
      overflow: visible;
      display: block;
      -webkit-line-clamp: unset;
      line-clamp: unset;
      -webkit-box-orient: unset;
      text-align: center;
      padding: 0 4px;
      word-wrap: break-word;
    }
    .simple_board_holder .btn.simple_board_icon .author {
      font-size: 17px;
      color: var(--md-muted);
      margin: 0;
      padding: 0 2px;
      display: flex;
      flex-direction: column;
      align-items: center;
      max-width: 100%;
    }
    .simple_board_holder .btn.simple_board_icon .author__username {
      color: $brand-charcoal-blue;
      font-size: 17px;
    }
    .simple_board_holder .btn.simple_board_icon .author__username--long {
      font-size: 14px;
    }
    .simple_board_holder .btn.simple_board_icon .info {
      /* PREVIEW pill: in-flow flex child of the simple_board_icon,
         pushed to the BOTTOM of the tile via `margin-top: auto`. Since
         every tile has `min-height: 300px` and `justify-content:
         flex-start`, `margin-top: auto` absorbs all the empty space
         between the title block and the pill — so the pill always
         sits at the same bottom position across all tiles, regardless
         of title length. `order: 99` keeps it as the last flex
         child. */
      position: static !important;
      top: auto !important;
      left: auto !important;
      right: auto !important;
      bottom: auto !important;
      transform: none !important;
      order: 99;
      align-self: center;
      margin-top: auto;
      padding: 5px 13px;
      font-size: 12px;
      display: inline-flex;
      flex-direction: row;
      align-items: center;
      gap: 6px;
      z-index: 4;
    }

    @media (min-width: 480px) { gap: 0.75rem 1rem; }
    @media (min-width: 768px) { gap: 1rem 1.25rem; }
    @media (min-width: 1024px) { gap: 1rem 1.5rem; }
  }

  /* Remove board: top-center inside card. Global .board_action uses top:-45px (tab above tile in
     legacy column grid); without position:relative on the holder it jumps to the page top. */
  .board_with_action {
    position: relative;
  }
  .board_with_action .board_action {
    top: 14px;
    left: 50%;
    right: auto;
    transform: translateX(-50%);
    width: 44px;
    height: 44px;
    min-width: 44px;
    min-height: 44px;
    padding: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid rgba($brand-blue-black, 0.12);
    border-bottom-width: 1px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.97);
    box-shadow: 0 2px 10px rgba($brand-blue-black, 0.08);
    font-size: 17px;
    color: rgba(75, 78, 92, 0.75);
    z-index: 6;
    transition:
      visibility 0s 0.15s linear,
      opacity 0.18s ease 0.15s,
      background 0.15s ease,
      color 0.15s ease,
      box-shadow 0.15s ease,
      border-color 0.15s ease;
  }
  .board_with_action .board_action:hover,
  .board_with_action .board_action:focus-visible {
    background: #fff;
    color: #b02a2a;
    border-color: rgba(176, 42, 42, 0.28);
    box-shadow: 0 3px 14px rgba($brand-blue-black, 0.12);
  }
  .board_with_action .board_action:focus-visible {
    @include focus-ring-inset;
  }

  &__show-more {
    width: 100%;
    padding: 16px 0 4px;
    display: flex;
    justify-content: center;
  }
  &__show-more-btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 9px 24px;
    border-radius: 999px;
    border: 1.5px solid rgba($brand-teal, 0.3);
    background: rgba(255,255,255,0.9);
    color: $brand-teal;
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 0.04em;
    text-decoration: none;
    box-shadow: 0 1px 4px rgba($brand-teal, 0.08);
    transition: background 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;
    &:hover {
      background: rgba($brand-teal, 0.07);
      border-color: $brand-teal;
      box-shadow: 0 3px 10px rgba($brand-teal, 0.15);
      transform: translateY(-1px);
      text-decoration: none;
      color: $brand-teal;
    }
  }
  &__show-more-chevrons {
    display: inline-flex;
    flex-direction: column;
    align-items: center;
    gap: 0;
    opacity: 0.75;

    .glyphicon {
      font-size: 14px;
      line-height: 0.6;
      display: block;
      margin: -2px 0;
    }
  }
  &__loading { color: #8a9ab8; font-size: 14px; padding: 12px 0; }

  // ── Back to Top ─────────────────────────────────────────────
  &__back-to-top-wrap {
    position: sticky;
    bottom: 2rem;
    z-index: 100;
    display: flex;
    justify-content: flex-end;
    pointer-events: none;
    padding: 0 1rem;
  }
  &__back-to-top {
    pointer-events: auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 2px;
    width: 52px;
    height: 52px;
    border-radius: 50%;
    border: 1.5px solid rgba($brand-teal, 0.25);
    background: rgba(255, 255, 255, 0.92);
    backdrop-filter: blur(10px);
    color: $brand-teal;
    cursor: pointer;
    box-shadow: 0 2px 12px rgba($brand-blue-black, 0.10), 0 4px 20px rgba($brand-teal, 0.08);
    transition: background 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    animation: ub-back-to-top-fade-in 0.3s ease forwards;

    .glyphicon {
      font-size: 14px;
      line-height: 1;
    }
    &:hover {
      background: rgba($brand-teal, 0.08);
      border-color: $brand-teal;
      box-shadow: 0 4px 18px rgba($brand-teal, 0.18), 0 6px 24px rgba($brand-blue-black, 0.10);
      transform: translateY(-2px);
    }
    &:active {
      transform: translateY(0);
      box-shadow: 0 2px 8px rgba($brand-teal, 0.12);
    }
  }
  &__back-to-top-label {
    font-size: 14px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    line-height: 1;
  }
  @keyframes ub-back-to-top-fade-in {
    from { opacity: 0; transform: translateY(10px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  // ── Getting Started ───────────────────────────────────────
  &__getting-started {
    position: relative;
    overflow: hidden;
    min-height: 120px;
  }
  &__getting-started-actions {
    position: absolute;
    top: 50%;
    right: 20px;
    transform: translateY(-50%);
    display: flex;
    align-items: center;
    gap: 14px;
    z-index: 1;

    .md-card__getting-started-btn {
      transform: none;
      align-self: auto;
      margin-top: 0;
      text-decoration: none;
      &:hover { text-decoration: none; }
    }
  }
  &__gs-secondary-btn {
    display: inline-flex;
    align-items: center;
    padding: 7px 18px;
    border-radius: 999px;
    border: 1px solid rgba($brand-blue-black, 0.18);
    background: rgba(255,255,255,0.45);
    color: $brand-slate-blue;
    font-size: 14px;
    font-weight: 500;
    text-decoration: none;
    transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
    &:hover {
      background: rgba(255,255,255,0.65);
      border-color: rgba($brand-blue-black, 0.28);
      color: $indigo;
      text-decoration: none;
    }
  }
}

// ── Delete folder confirmation modal ──
.la-delete-folder-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba($brand-blue-black, 0.4);
  backdrop-filter: blur(4px);
  animation: la-delete-folder-fade-in 0.2s ease;
}
.la-delete-folder-modal {
  width: 100%;
  max-width: 440px;
  margin: 16px;
  border-radius: var(--md-r-lg, 16px);
  border: 1px solid var(--md-line, rgba($brand-blue-black, 0.1));
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(248, 250, 252, 0.98));
  box-shadow: 0 20px 60px rgba($brand-blue-black, 0.2), 0 8px 24px rgba($brand-blue-black, 0.1);
  overflow: hidden;
  animation: la-delete-folder-scale-in 0.25s cubic-bezier(0.22, 1, 0.36, 1);
}
.la-delete-folder-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.35);
  z-index: 1039;
}
.la-delete-folder-modal--inline {
  /* Viewport-centered modal — both axes. The old logic anchored
     `top` via a `--delete-folder-top` custom prop set in JS based on
     the Delete button's getBoundingClientRect (rect.bottom + 8px),
     but in the new destination-card layout the Delete button sits
     far-right and the modal landed off-center. translate(-50%, -50%)
     centers cleanly regardless of where the trigger lives. */
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 1040;
  margin: 0;
  max-width: 440px;
  animation: la-delete-folder-center-in 0.25s cubic-bezier(0.22, 1, 0.36, 1);
}
@keyframes la-delete-folder-center-in {
  from { opacity: 0; transform: translate(-50%, -50%) scale(0.95); }
  to { opacity: 1; transform: translate(-50%, -50%) scale(1); }
}
.la-delete-folder-modal .la-modal-header {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  padding: 20px 24px;
  border-bottom: 1px solid var(--md-line, rgba($brand-blue-black, 0.08));
  background: rgba(255, 255, 255, 0.6);
}
.la-delete-folder-modal .la-modal-header-label {
  margin: 0;
  font-weight: 900;
  font-size: 20px;
  letter-spacing: -0.2px;
  color: var(--md-ink, $indigo);
  flex: 1 1 auto;
}
.la-delete-folder-modal .la-modal-close {
  display: flex;
  align-items: center;
  justify-content: center;
  /* WCAG AA + AAC touch target — was 36×36 */
  width: 48px;
  height: 48px;
  min-width: 48px;
  min-height: 48px;
  padding: 0;
  margin: 0;
  border: 1px solid rgba($brand-blue-black, 0.12);
  border-radius: 50%;
  background: $surface-300;
  color: var(--md-muted, #8a96a8);
  cursor: pointer;
  font-size: 18px;
  line-height: 1;
  transition: color 0.2s ease, background 0.2s ease;
  &:hover {
    color: var(--md-ink, $indigo);
    background: $surface-400;
  }
}
.la-delete-folder-modal-body {
  padding: 24px;
  text-align: center;
}
.la-delete-folder-modal-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: rgba($brand-danger, 0.08);
  color: $brand-danger;
  margin: 0 auto 16px;
}
.la-delete-folder-modal-title {
  font-size: 18.4px;
  font-weight: 600;
  color: var(--md-ink, $indigo);
  margin: 0 0 8px;
  line-height: 1.4;
}
.la-delete-folder-modal-desc {
  font-size: 16.1px;
  color: var(--md-muted, #8a96a8);
  margin: 0;
  line-height: 1.5;
}
.la-delete-folder-modal-actions {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin: 0 24px;
  padding: 20px 0 24px;
  border-top: 1px solid var(--md-line, rgba($brand-blue-black, 0.08));
}
.la-delete-folder-modal-delete {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 20px;
  border-radius: 999px;
  border: none;
  background: $brand-danger;
  color: #fff;
  font-weight: 700;
  font-size: 15px;
  cursor: pointer;
  transition: filter 0.15s ease;
  &:hover {
    filter: brightness(1.1);
  }
}
.la-delete-folder-modal-cancel {
  padding: 10px 18px;
  border-radius: 999px;
  border: 1px solid var(--md-line, rgba($brand-blue-black, 0.1));
  background: rgba($brand-blue-black, 0.06);
  color: var(--md-ink, $indigo);
  font-weight: 600;
  font-size: 15px;
  cursor: pointer;
  transition: background 0.15s ease;
  &:hover {
    background: rgba($brand-blue-black, 0.1);
  }
}
@keyframes la-delete-folder-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes la-delete-folder-scale-in {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

// ── Folder drop animation keyframes ──
// Smooth pop-up with a single clean overshoot then settle
@keyframes folder-full {
  0%   { transform: scale(0.98); }
  50%  { transform: scale(1.02); }
  100% { transform: scale(1); }
}
@keyframes folder-card-full {
  0%   { transform: translateY(3px); opacity: 0.8; }
  50%  { transform: translateY(-3px); opacity: 1; }
  100% { transform: translateY(0); opacity: 1; }
}
@keyframes folder-back-full {
  0%   { box-shadow: 0 0 0 0 rgba(44, 183, 176, 0.4), 0 4px 16px rgba(27, 42, 65, 0.20); filter: brightness(1.08); }
  50%  { box-shadow: 0 0 0 10px rgba(44, 183, 176, 0), 0 5px 18px rgba(27, 42, 65, 0.18); filter: brightness(1.02); }
  100% { box-shadow: 0 4px 16px rgba(27, 42, 65, 0.20), 0 8px 32px rgba(27, 42, 65, 0.10), inset 0 1px 0 rgba(255, 255, 255, 0.08); filter: brightness(1); }
}
@keyframes folder-tab-full {
  0%   { filter: brightness(1.15); }
  100% { filter: brightness(1); }
}
@keyframes folder-count-full {
  0%   { transform: scale(0.9); opacity: 0.6; }
  50%  { transform: scale(1.06); opacity: 1; }
  100% { transform: scale(1); }
}

