  font-style: italic;
}
.md-translate-status {
  text-align: center;
  font-size: 14px;
  color: $brand-slate-gray;
  padding: 24px 0;
}
.md-translate-status--error {
  color: $brand-danger;
}
/* Stack rows full-width on narrow viewports — source above input. */
@media (max-width: 540px) {
  .md-translate-row {
    grid-template-columns: 1fr;
    row-gap: 8px;
  }
}

/* ── Edit Room Details modal — curriculum row repeater ──────────── */
.md-edit-unit-curriculum {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.md-edit-unit-curriculum__row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr) auto;
  align-items: center;
  gap: 8px;
}
.md-edit-unit-curriculum__remove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  padding: 0;
  border-radius: 8px;
  border: 1px solid rgba($la-navy, 0.10);
  background: transparent;
  color: rgba($la-navy, 0.55);
  cursor: pointer;
  flex-shrink: 0;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}
.md-edit-unit-curriculum__remove:hover,
.md-edit-unit-curriculum__remove:focus-visible {
  background: rgba(220, 53, 69, 0.08);
  border-color: rgba(220, 53, 69, 0.25);
  color: #dc3545;
  outline: none;
}
.md-edit-unit-curriculum__add {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  align-self: flex-start;
  padding: 6px 12px;
  margin-top: 4px;
  border-radius: 999px;
  border: 1px dashed rgba($brand-slate-blue, 0.45);
  background: rgba($brand-slate-blue, 0.06);
  color: $brand-slate-blue;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}
.md-edit-unit-curriculum__add:hover,
.md-edit-unit-curriculum__add:focus-visible {
  background: rgba($brand-slate-blue, 0.12);
  border-color: rgba($brand-slate-blue, 0.70);
