/* ─────────────────────────────────────────────────────────────────────────
   Custom confirm dialog — brand-styled replacement for browser confirm().
   Used in button-settings "Clear Button" and reusable elsewhere.
   ───────────────────────────────────────────────────────────────────────── */
.ll-confirm-overlay {
  position: absolute;
  inset: 0;
  z-index: 100;
  background: rgba(15, 23, 42, 0.55);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: inherit;
  animation: ll-loading-overlay-fade-in 120ms ease-out;
}
.ll-confirm-card {
  background: #fff;
  border-radius: 16px;
  padding: 36px 40px 32px;
  box-shadow: 0 18px 48px rgba(15, 23, 42, 0.28);
  max-width: 520px;
  width: 90%;
  text-align: center;
}
.ll-confirm-title {
  margin: 0 0 12px;
  font-size: 1.7rem;
  font-weight: 700;
  color: $la-navy;
}
.ll-confirm-desc {
  margin: 0 0 28px;
  font-size: 1.4rem;
  color: $brand-charcoal-dark;
  line-height: 1.5;
}
.ll-confirm-actions {
  display: flex;
  gap: 12px;
  justify-content: center;
}
.ll-confirm-btn {
  padding: 14px 32px;
  min-height: 52px;
  border: none;
  border-radius: 10px;
  font-size: 1.4rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.12s ease, box-shadow 0.12s ease;
}
.ll-confirm-btn--cancel {
  background: $surface-200;
  color: $brand-charcoal-dark;
}
.ll-confirm-btn--cancel:hover {
  background: color.adjust($surface-200, $lightness: -5%);
}
.ll-confirm-btn--danger {
  background: $brand-danger;
  color: #fff;
}
.ll-confirm-btn--danger:hover {
  background: color.adjust($brand-danger, $lightness: -8%);
  box-shadow: 0 4px 12px rgba($brand-danger, 0.3);
}
@media (prefers-reduced-motion: reduce) {
  .ll-confirm-overlay { animation: none; }
}
