/* ─────────────────────────────────────────────────────────────────────────
   Global loading overlay — used during major route transitions (e.g. exit
   speak mode → home page). Dims + blurs the background; centers a card with
   a spinner and status message. Controlled by app_state.loading_overlay_message.
   ───────────────────────────────────────────────────────────────────────── */
.ll-loading-overlay {
  position: fixed;
  inset: 0;
  z-index: 10050;
  background: rgba(15, 23, 42, 0.55);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  animation: ll-loading-overlay-fade-in 180ms ease-out;
}
.ll-loading-overlay__card {
  background: #fff;
  border-radius: 14px;
  padding: 28px 36px;
  box-shadow: 0 18px 48px rgba(15, 23, 42, 0.28);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  min-width: 240px;
  max-width: calc(100vw - 32px);
}
.ll-loading-overlay__spinner {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 4px solid rgba(42, 157, 143, 0.18);
  border-top-color: #2a9d8f;
  animation: ll-loading-overlay-spin 0.9s linear infinite;
}
.ll-loading-overlay__message {
  margin: 0;
  font-size: 16px;
  font-weight: 500;
  color: #1f2937;
  text-align: center;
}
@keyframes ll-loading-overlay-spin {
  to { transform: rotate(360deg); }
}
@keyframes ll-loading-overlay-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
@media (prefers-reduced-motion: reduce) {
  .ll-loading-overlay { animation: none; }
  .ll-loading-overlay__spinner { animation-duration: 2.5s; }
}
/* Modal-scoped variant — sits absolutely inside its modal-body
   container instead of covering the viewport. Same card chrome
   so the visual reads as the same loading state, just confined
   to the modal's bounds. Used by the board-preview modal while
   the preview canvas finishes settling every button-image
   promise. */
.ll-loading-overlay--in-modal {
  position: absolute;
  z-index: 5;
  background: rgba(255, 255, 255, 0.88);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}

/* ── Modern Toast Notification ─────────────────────────
   Slides in from the top-right, auto-dismisses, doesn't
   block the UI. Replaces the legacy flash-notice pattern. */
.ll-toast {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  max-width: min(420px, calc(100vw - 48px));
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px 14px 18px;
  background: #fff;
  border-radius: 12px;
  border-left: 4px solid $brand-verdigris;
  box-shadow: 0 10px 28px rgba($la-navy, 0.18), 0 2px 6px rgba($la-navy, 0.08);
  color: $la-navy;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.4;
  z-index: 10000;
  animation: ll-toast-slide-in 0.28s cubic-bezier(0.16, 1, 0.3, 1);
}
.ll-toast__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: $brand-verdigris;
}
.ll-toast__message {
  flex: 1;
}
.ll-toast__close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  padding: 0;
  margin-left: 4px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: rgba($la-navy, 0.5);
  cursor: pointer;
  transition: background 0.12s ease, color 0.12s ease;
  flex-shrink: 0;
}
.ll-toast__close:hover {
  background: rgba($la-navy, 0.08);
  color: $la-navy;
}
.ll-toast__close:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px $brand-verdigris;
}

/* Kind variants — change the accent color & icon tint */
.ll-toast--success {
  border-left-color: #2ecc71;
}
.ll-toast--success .ll-toast__icon { color: #2ecc71; }
.ll-toast--warning {
  border-left-color: #f39c12;
}
.ll-toast--warning .ll-toast__icon { color: #f39c12; }
.ll-toast--error {
  border-left-color: $brand-danger;
}
.ll-toast--error .ll-toast__icon { color: $brand-danger; }

@keyframes ll-toast-slide-in {
  from { opacity: 0; transform: translate(-50%, 12px); }
  to   { opacity: 1; transform: translate(-50%, 0); }
}
@media (prefers-reduced-motion: reduce) {
  .ll-toast { animation: none; }
}
@media (max-width: 480px) {
  .ll-toast {
    bottom: 12px;
    left: 12px;
    right: 12px;
    transform: none;
    max-width: none;
  }
  /* On phones the toast spans the full width, so the slide-in needs to
     animate without the centering translate. */
  @keyframes ll-toast-slide-in {
    from { opacity: 0; transform: translateY(12px); }
    to   { opacity: 1; transform: translateY(0); }
  }
}

/* ── Tooltip background override (keep last) ──
   Anything on an ancestor that drops opacity/filter would bleed through the
   ::after pseudo. Isolate the tooltip into its own stacking context with a
   fully-opaque fill that nothing else can undercut. */
#within_ember .md-board-detail-edit-toolbar [data-tooltip]:hover:not(:active)::after,
.md-board-detail--dark .md-board-detail-edit-toolbar [data-tooltip]:hover:not(:active)::after {
  background: #1b2a4a !important;
  background-color: #1b2a4a !important;
  opacity: 1 !important;
  filter: none !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  mix-blend-mode: normal !important;
  isolation: isolate !important;
  z-index: 9999 !important;
  box-shadow: 0 0 0 1px #1b2a4a, 0 4px 16px rgba(0, 0, 0, 0.35) !important;
}
#within_ember .md-board-detail-edit-toolbar [data-tooltip]:hover:not(:active)::before,
.md-board-detail--dark .md-board-detail-edit-toolbar [data-tooltip]:hover:not(:active)::before {
  border-bottom-color: #1b2a4a !important;
  opacity: 1 !important;
  filter: none !important;
  mix-blend-mode: normal !important;
  z-index: 9999 !important;
}

/* ── Accessibility: 14px font-size floor for vendored Bootstrap ──
   The vendored Bootstrap 3 ships ~26 built-in selectors that render text
   below our 14px accessibility floor (e.g. .small = 85% → 8.5px at 10px
   root, .h6 = 12px, .badge = 12px, .tooltip = 12px, etc). These overrides
   force every such selector up to 14px so any Bootstrap-styled UI in the
   app still meets the AAC legibility requirement. (We deliberately do NOT
   override html's 10px root — doing so would scale every rem-based size in
   the app up by 1.4x and break layouts.) */
small,
.small,
.h6,
h6,
.initialism,
code,
kbd,
pre,
.input-sm,
input.input-sm,
select.input-sm,
textarea.input-sm,
.form-group-sm .form-control,
.form-group-sm .form-control-static,
.form-horizontal .form-group-sm .control-label,
.btn-sm,
.btn-group-sm > .btn,
.btn-xs,
.btn-group-xs > .btn,
.dropdown-header,
.input-group-sm > .input-group-btn > .btn,
.input-group-addon.input-sm,
.pagination-sm > li > span,
.pagination-sm > li > a,
.label,
.badge,
.progress-bar,
.tooltip,
.tooltip-inner,
.popover-title,
sub,
sup,
.h3 .small,
.h6 .small,
blockquote .small,
blockquote footer,
blockquote small {
  font-size: 14px !important;
}

